  ui_story_5080_50800100_112_dialog_content = "今回の任務では、私が隊長となりR・Wの縄張りの砂漠の奥深くまで進入し、\nある特殊な暗鬼について調査する。",
  ui_story_5080_50800100_113_dialog_content = "その暗鬼は高温地帯に出没し、マグマの力を利用する。\n奴らが出没した所にはわかりやすい痕跡が残るんだが――",
