  ui_story_5080_50800100_121_dialog_content = "僕たちR・Wのサメヤマとは仲がいいんだ。\n暗鬼の調査の方は直接サメヤマに聞けばいいと思う。",
  ui_story_5080_50800100_122_dialog_content = "そうだったか…それで大元帥は君たちを指名したのかもしれないな。\n人脈を使って情報を得るのは効率的だ。許可する。行ってきてくれ。",
  ui_story_5080_50800100_123_dialog_content = "え？では、隊長は…",
  ui_story_5080_50800100_124_dialog_content = "私は啓光の隊長だ。砂漠にはびこる賊とは付き合いがないし、\n会えば、思わずその指名手配犯たちを捕まえてしまうかもしれない。",
  ui_story_5080_50800100_125_dialog_content = "君たちだけで行ってくれ。私には構うな。\n独りで偵察をしている。",
