  ui_story_5080_50800100_135_dialog_content = "今回の任務は暗鬼の調査よ。それなのに、あの隊長はなぜ、\n啓光の小隊の情報を集めようとしてるのかしら？",
  ui_story_5080_50800100_136_dialog_content = "勘違いかもしれないけど…\nレイチェルみたいな人はきっと意味のないことはしない気がするんだ。",
  ui_story_5080_50800100_137_dialog_content = "あなたたちの話を聞いてたら、私まで気になってきちゃった…\nまぁ、いいわ。フィリス先輩に聞けばいいだけのことよ。",
  ui_story_5080_50800100_138_dialog_content = "ふにゃあ～、急に連絡してくるにゃんてどうしたのにゃ？\n何か問題でもあったのかにゃ？",
  ui_story_5080_50800100_139_dialog_content = "フィリス先輩、ちょっと聞きたいことがあるんですけど、\n「フリーバード」って名前か、もしくはそれに関係する情報を聞いたことはありますか？",
  ui_story_5080_50800100_140_dialog_content = "うーん…聞いた感じ、啓光の小隊だにゃ。ただ、今はそんな名前の付け方はしてないにゃん。\n資料をしらべれば、何かわかるかもしれにゃいけど。",
  ui_story_5080_50800100_141_dialog_content = "フィリス先輩、お願いします。フリーバードについて、どうしても知りたいんです。\n今度ニボシをご馳走しますから。",
  ui_story_5080_50800100_142_dialog_content = "機密じゃにゃいかぎり、教えてあげても構わにゃいにゃ。\nただニボシは今度必ず持ってきてにゃん。",
  ui_story_5080_50800100_143_dialog_content = "お待たせにゃん。40年近く前その小隊はものすごく危険にゃ任務を\n数十回も完璧にこにゃしてるにゃ。正真正銘の精鋭部隊にゃ～。",
  ui_story_5080_50800100_144_dialog_content = "でも記録によると、「フリーバード」の最後の任務は、\nR・W砂漠であるモノを探すことで…失敗に終わってるにゃ。",
  ui_story_5080_50800100_145_dialog_content = "それ以降の記録は高度な暗号化がされてるにゃん。\n私でも勝手に見られにゃいレベルにゃ～。",
  ui_story_5080_50800100_146_dialog_content = "そんなことってあるんですか？\n情報長官のフィリス先輩でも自由に閲覧できないなんて…",
  ui_story_5080_50800100_147_dialog_content = "隊長が誰かも調べられにゃいにゃ。この機密レベルの高さ、\nしかも長い間保持されてるってことは、おそらく反逆者の類だにゃん。",
  ui_story_5080_50800100_148_dialog_content = "これは大変にゃことだにゃん。\nバイス、いったいどこでその名前を聞いたのにゃ？",
  ui_story_5080_50800201_1_dialog_content = "サメヤマ、遅いな。どうしちゃったのかな？",
  ui_story_5080_50800201_2_dialog_content = "遠くで何だか忙しくしているようだけど、\n工事でもしているのかしら？",
  ui_story_5080_50800201_3_dialog_content = "…",
  ui_story_5080_50800201_4_dialog_content = "バイス、何か悩み事があるみたいだけど大丈夫？",
  ui_story_5080_50800201_5_dialog_content = "え？何でもないわ…隊長がどうして昔の小隊のことなんて聞いたのか、考えてただけ。",
  ui_story_5080_50800201_6_dialog_content = "しかも、その隊長には反逆者の嫌疑がかかってるようね。",
  ui_story_5080_50800201_7_dialog_content = "あの姿を見る限り、レイチェルって偵察を任務とする特殊兵だよね？",
  ui_story_5080_50800201_8_dialog_content = "だったら逆に…反逆者の調査をしてるとか？",
  ui_story_5080_50800201_9_dialog_content = "でも、ずいぶんと前のことよ。\n今もまだ調査を続けてるなんてことがあるかしら？",
  ui_story_5080_50800201_10_dialog_content = "もしかして…反逆を起こした小隊とレイチェルとの間に何か関係があるのかも？",
  ui_story_5080_50800201_11_dialog_content = "「フリーバード」…そして「ホークアイ」…",
  ui_story_5080_50800201_12_dialog_content = "よっ！お前ら、なに苦え顔してんだ？",
  ui_story_5080_50800201_13_dialog_content = "サメヤマ！",
  ui_story_5080_50800201_14_dialog_content = "久しぶりだな。ちっとはたくましくなったみてえじゃねぇか。\nどうだ、俺たちの仲間になる気になったか？",
  ui_story_5080_50800201_15_dialog_content = "えっと、その話だけどやっぱり…",
  ui_story_5080_50800201_16_dialog_content = "ハハハ！構わねえよ。その気になった時に言ってくれりゃいいことだ。\nで、今日はわざわざ俺に何の用だ？",
  ui_story_5080_50800201_17_dialog_content = "実は僕たち、ある特殊な任務を受けて…\nこの砂漠で、ちょっと変わった暗鬼を見てない？",
  ui_story_5080_50800201_18_dialog_content = "ああ？どんな暗鬼だ？",
  ui_story_5080_50800201_19_dialog_content = "うーん、そうだな…\nすごく熱そうな見た目で、火山を好む暗鬼、みたいな？",
  ui_story_5080_50800201_20_dialog_content = "なにふざけたこと言ってやがんだ？\nこの辺りの火山地帯にゃ暗鬼なんざ山ほどいるぞ。",
  ui_story_5080_50800201_21_dialog_content = "火山との親和性が高く、マグマを「利用」できる暗鬼で――",
  ui_story_5080_50800201_22_dialog_content = "異常なほどに強大で、通った所にははっきりとした痕跡が残る。",
  ui_story_5080_50800201_23_dialog_content = "そういう暗鬼に覚えはないかしら？",
  ui_story_5080_50800201_24_dialog_content = "「マグマの暗鬼」…そんなわけねぇ。\nアレはもう十何年も出てねぇはずだ…",
  ui_story_5080_50800201_25_dialog_content = "知ってるの？",
  ui_story_5080_50800201_26_dialog_content = "詳しく聞かせて。その暗鬼の情報を集めてるの。",
  ui_story_5080_50800201_27_dialog_content = "ずいぶん古い話だし、俺たちの過去にも関係ある話なんだが…",
  ui_story_5080_50800201_28_dialog_content = "仕方ねぇ。知りたいってなら、教えてやってもいいぜ。",
  ui_story_5080_50800201_29_dialog_content = "確かにその暗鬼は知ってるが…いや、<color=#FFB400>R・W</color>の古いメンバーは皆、\nそいつに深い恨みがあるって言った方が正しいか。",
  ui_story_5080_50800201_30_dialog_content = "どういう意味かしら？",
  ui_story_5080_50800201_31_dialog_content = "十数年前の<color=#FFB400>暗潮の危機</color>の頃の話だよ。\n俺もまだボスの手下で、小間使いのガキでしかなかった。",
  ui_story_5080_50800201_32_dialog_content = "そんなある日、突然暗鬼が砂嵐みてえに押し寄せてきやがって、\n俺たちは皆、故郷を離れざるを得なくなった。",
  ui_story_5080_50800201_33_dialog_content = "俺たちガキどもを安全に逃がそうと、\nボスは部下を率いて殿を務めたんだが…",
  ui_story_5080_50800201_34_dialog_content = "今でも覚えてるぜ…あの暗鬼の群れの中に1匹、誰もがビビッちまう強さのヤツがいたんだ。\n砂がマグマの熱でガラスになっちまうほどのな…",
  ui_story_5080_50800201_35_dialog_content = "え？",
  ui_story_5080_50800201_36_dialog_content = "あ？聞こえなかったか？ヤツは…",
  ui_story_5080_50800201_37_dialog_content = "ああ！？",
  ui_story_5080_50800201_38_dialog_content = "うわぁああ――！",
  ui_story_5080_50800201_39_dialog_content = "すまぬ、<color=#FFB400>呪われた狂戦士</color>！早く助けよ！",
  ui_story_5080_50800201_40_dialog_content = "PlayerName、あぶない！",
  ui_story_5080_50800201_41_dialog_content = "うおおお――！止まりやがれ！",
  ui_story_5080_50800201_42_dialog_content = "うわあああ――",
  ui_story_5080_50800201_43_dialog_content = "大好きなハニー、歌声は止まらないの～！",
  ui_story_5080_50800201_44_dialog_content = "さすがは<color=#FFB400>呪われた狂戦士</color>！\n実に驚異的な力の持ち主である！",
  ui_story_5080_50800201_45_dialog_content = "ゼタか？それにバーバラとタイニーまで、いったい何してやがんだ？",
  ui_story_5080_50800201_46_dialog_content = "トラックのままキャンプに突っ込むとは、こりゃあまりにも…",
  ui_story_5080_50800201_47_dialog_content = "説明してるヒマはないの、乗って！",
  ui_story_5080_50800201_48_dialog_content = "はあ！？",
  ui_story_5080_50800201_49_dialog_content = "<color=#FFB400>呪われた狂戦士</color>よ！\nまさかおぬしには聞こえぬのか？あの遥か彼方より伝わりし足音が――",
  ui_story_5080_50800201_50_dialog_content = "見よ、来たぞ。「砂漠の腕利きハンター」だ！",
  ui_story_5080_50800201_51_dialog_content = "見て、あれは――",
  ui_story_5080_50800201_52_dialog_content = "<size=45>レイチェル！！</size>",
  ui_story_5080_50800201_53_dialog_content = "あれはいったい誰だ？ゼタ、ちゃんと説明しろ。\nお前、何しでかしやがったんだ？",
  ui_story_5080_50800201_54_dialog_content = "ヤババ…",
  ui_story_5080_50800201_55_dialog_content = "うわぁっ、エアバッグに挟まって抜けらんないよ！",
  ui_story_5080_50800201_56_dialog_content = "それくらいなんだってんだ。待ってろ、ドアを外してやる。",
  ui_story_5080_50800201_57_dialog_content = "ダメだよ。あいつから離れなきゃ！\nあいつは「魔王の牙」なんだよ！",
  ui_story_5080_50800201_58_dialog_content = "「R・Wの賊」！盗んだものを返すんだ！",
  ui_story_5080_50800201_59_dialog_content = "ははっ、偉そうな口ききやがって。",
  ui_story_5080_50800201_60_dialog_content = "よく見りゃ、啓光の兵士じゃねえか。",
  ui_story_5080_50800201_61_dialog_content = "レイチェル、サメヤマ、落ち着いて、話を聞いて…",
  ui_story_5080_50800201_62_dialog_content = "だまれ！！",
  ui_story_5080_50800201_63_dialog_content = "啓光のヤツだってだけじゃねえ。うちのガキどもを追っかけまわして、\n俺たちのキャンプに車を突っ込ませやがって…",
  ui_story_5080_50800201_64_dialog_content = "砂漠で悪事を働くだけでなく、\n大胆にも私の「戦友」まで盗むとは。許さない…",
  ui_story_5080_50800201_65_dialog_content = "ほぉ？やるってか？\nお前らとやり合うのはずいぶんと久しぶりだぜ。",
  ui_story_5080_50800201_66_dialog_content = "かかってこい。",
  ui_story_5080_50800201_67_dialog_content = "おかしなことになっちゃってるよ。\nバイス、カレン、急いで止めなきゃ！",
  ui_story_5080_50800201_68_dialog_content = "僕の指揮に従って、同時に行くよ！",
  ui_story_5080_50800202_1_dialog_content = "ちっこいもんが飛び回ってうるせえな…\nあっちへ行け！",
  ui_story_5080_50800202_2_dialog_content = "これで、どうしようもねえだろ？",
  ui_story_5080_50800202_3_dialog_content = "動くな。空の果てまで吹っ飛ばされたくなければな――",
  ui_story_5080_50800202_4_dialog_content = "おっ？いつの間に爆弾を――\nなかなかやるじゃねえか。",
  ui_story_5080_50800202_5_dialog_content = "この距離では、私もお前もただでは済まない。",
  ui_story_5080_50800202_6_dialog_content = "死ぬのは怖くねぇってか…おもしれぇ、試してみようじゃねえか！",
  ui_story_5080_50800202_7_dialog_content = "「R・Wの頭」が相手とあらば、命など惜しくない…",
  ui_story_5080_50800202_8_dialog_content = "待って待って！2人とも落ち着いて！",
  ui_story_5080_50800202_9_dialog_content = "そうです、隊長。私たちにはまだ任務があるんです！\n任務のことを考えてください！",
  ui_story_5080_50800202_10_dialog_content = "サメヤマ、もし君に何かあったら、他の皆はどうするの？",
  ui_story_5080_50800202_11_dialog_content = "ここにはたくさん「子ども」がいるのよ。",
  ui_story_5080_50800202_12_dialog_content = "「子ども」？",
  ui_story_5080_50800202_13_dialog_content = "うわああん――",
  ui_story_5080_50800202_14_dialog_content = "一体何があったの？ちゃんと話し合って、\n一緒に解決方法を考えようよ。",
  ui_story_5080_50800202_15_dialog_content = "「魔王の牙」を怒らせたのはあたしたちだよ。\nあたしが責任とるから、「仲間たち」は見逃して！",
  ui_story_5080_50800202_16_dialog_content = "…",
  ui_story_5080_50800202_17_dialog_content = "ゼタ、いったい何があったんだ？",
  ui_story_5080_50800202_18_dialog_content = "事の始まりは、勇者ゼタの伝説――",
  ui_story_5080_50800202_19_dialog_content = "勇者ゼタは修練した運転技術にさらに研さんを重ねていたが、\n今だあの「レーシングカーの魔女」には敵わなかった。",
  ui_story_5080_50800202_20_dialog_content = "きっとこれは魔女が「空の末裔」のような強大なる者の力を借りたからに違いない。\n勇者ゼタはそう考え、仲間探しの旅に出た。",
  ui_story_5080_50800202_21_dialog_content = "まさにその時、伝説の<color=#FFB400>吟遊詩人の新星</color>バーバラが現れたのだ！\nその後レジーナも現れ、2人は吟遊詩人の大会で競い合っているようだった。",
  ui_story_5080_50800202_22_dialog_content = "「ねえ、勇者ゼタ。あなたの力で私を助けて。」",
  ui_story_5080_50800202_23_dialog_content = "「あなたさえいれば、レジーナよりも先にたくさんのお客さんを引き付けられる。\nお客さんは私の力の源なの！」",
  ui_story_5080_50800202_24_dialog_content = "「いいね！でも、あたしがいることも忘れないで！\n勇者ゼタの最も忠実な<color=#FFB400>武器マスター</color>をね！」",
  ui_story_5080_50800202_25_dialog_content = "おお！まさか、これが勇者のオーラというものか！\n仲間が自然と集まってきたではないか！",
  ui_story_5080_50800202_26_dialog_content = "こうして勇者一行は旅に出た。レジーナよりも先に、\nマッドロード・ツアーでより多くの客を獲得するために！",
  ui_story_5080_50800202_27_dialog_content = "この流行最前線の<color=#FFB400>R・Wスーパーアイドルステージ</color>カーで、決戦の地…",
  ui_story_5080_50800202_28_dialog_content = "ストップ！いったい何の話をしてるの？\n重要なところだけ話してくれない？",
  ui_story_5080_50800202_29_dialog_content = "…やれやれ。",
  ui_story_5080_50800202_30_dialog_content = "勇者一行が危険な砂漠を駆け抜け、希望の歌声を届けていたその時、\n勇者ゼタは発見したのだ！",
  ui_story_5080_50800202_31_dialog_content = "1羽の孤独な、それでいて誇り高きタカを。",
  ui_story_5080_50800202_32_dialog_content = "あのタカに照明とか音響をやらせてみる？",
  ui_story_5080_50800202_33_dialog_content = "武器マスターはそういうが、ゼタは気づいていた。\nタカの気高い心に。",
  ui_story_5080_50800202_34_dialog_content = "勇者は決めたのだ。そのタカを仲間にしようと！",
  ui_story_5080_50800202_35_dialog_content = "しかし、孤高のタカを追う邪悪な牙がやって来て、\nしつこく追いかけてくるばかりか、攻撃を仕掛けてきたのだ。",
  ui_story_5080_50800202_36_dialog_content = "その弾丸は実に恐ろしく、勇者ゼタも恐怖のあまり…いや、違う違う。\n仲間の安全のため、絶対に車を止めぬと心に決めたのだ！",
  ui_story_5080_50800202_37_dialog_content = "で、スピードあげた挙句、家に突っ込んだってか？",
  ui_story_5080_50800202_38_dialog_content = "ゼタは信じていたぞ。狂戦士のおぬしなら必ず車を止められると！",
  ui_story_5080_50800202_39_dialog_content = "お前なぁ…",
  ui_story_5080_50800202_40_dialog_content = "…バカバカしい。",
  ui_story_5080_50800202_41_dialog_content = "<color=#FFB400>ホークハンター3号</color>を返すんだ。",
  ui_story_5080_50800301_1_dialog_content = "<color=#FFB400>ホークハンター3号</color>って名前だったの？\nカッコいい名前だね！",
  ui_story_5080_50800301_2_dialog_content = "分かった…<color=#FFB400>ホークハンター3号</color>には主がいたんなら…返すよ。\nだから、もうケンカしないでよ…",
  ui_story_5080_50800301_3_dialog_content = "おい、待てよ。暴れるだけ暴れて、さぁ帰ろうってか？",
  ui_story_5080_50800301_4_dialog_content = "啓光のモンが偉そうに堂々と俺たちのキャンプを壊して、\nうちのガキどもを怖がらせておきながら、そのまま帰れると思ってんのか？",
  ui_story_5080_50800301_5_dialog_content = "お前たちが先に<color=#FFB400>ホークハンター3号</color>盗んだんだ。\nどうとでも言うがいい。",
  ui_story_5080_50800301_6_dialog_content = "お前、聞いたことねぇか？\nR・Wの賊はな、「道理じゃなく情で他人を助ける」んだよ。",
  ui_story_5080_50800301_7_dialog_content = "まだやる気か？",
  ui_story_5080_50800301_8_dialog_content = "2人ともいい加減にしようよ。",
  ui_story_5080_50800301_9_dialog_content = "いったい何事かしら？外がずいぶん騒がしいけど、\nこっちもピリピリした雰囲気じゃな～い。",
  ui_story_5080_50800301_10_dialog_content = "イェリア！？",
  ui_story_5080_50800301_11_dialog_content = "お前…どういう風の吹き回しだ？",
  ui_story_5080_50800301_12_dialog_content = "アタシだって外出なんてゴメンだったわよぉ。\nでも…サメヤマ、火山が「吠えてる」の、聞こえたかしら？",
  ui_story_5080_50800301_13_dialog_content = "「怒号の火山」が目覚めたわ。<color=#FFB400>15年前</color>のあの時と同じようにね。",
  ui_story_5080_50800301_14_dialog_content = "なんだと？",
  ui_story_5080_50800301_15_dialog_content = "兄貴、こっちは大丈夫か！？",
  ui_story_5080_50800301_16_dialog_content = "なんとか外の邪魔者は片付けておいたけど、皆、無事かい？",
  ui_story_5080_50800301_17_dialog_content = "おいっ！タイニー、バーバラ、ゼタ、どこだ？",
  ui_story_5080_50800301_18_dialog_content = "お前ら！その人数で急に入ってくるんじゃねえ！",
  ui_story_5080_50800301_19_dialog_content = "こっちはまだ話してるってんだ、おいっ！\n止まれってんだよ、このバカどもがーー！！",
  ui_story_5080_50800301_20_dialog_content = "あちこちで「怒号の火山」が目覚めたって騒いでやがるが、マジか？",
  ui_story_5080_50800301_21_dialog_content = "ゼタ、早くオッさんの質問に答えてくれ、無事か？",
  ui_story_5080_50800301_22_dialog_content = "私は無事でございます！「心優しい姫様」！",
  ui_story_5080_50800301_23_dialog_content = "私も「怒号の火山」がゴオゴオいってるのを聞いたぞ。\n目覚めたのは間違いないな。",
  ui_story_5080_50800301_24_dialog_content = "<color=#FFB400>暗潮の危機</color>に噴火したきり、ずっと休眠してるって話じゃなかったか？\nいったい何が起こってんだ…",
  ui_story_5080_50800301_25_dialog_content = "<size=45>だまれっつってんだろ！！</size>",
  ui_story_5080_50800301_26_dialog_content = "クソッ、啓光のあいつはどこ行きやがった？",
  ui_story_5080_50800301_27_dialog_content = "ん？啓光のあいつ？それは俺のことかな？",
  ui_story_5080_50800301_28_dialog_content = "ふぅ――ふぅ――",
  ui_story_5080_50800301_29_dialog_content = "はぁ…こ、ここまで来れば…ふぅ…\nたぶん、だ、大丈夫だよね。",
  ui_story_5080_50800301_30_dialog_content = "ちょ、ちょっと待って…息を…整えさせて。",
  ui_story_5080_50800301_31_dialog_content = "危なかったわね。\nサメヤマと知り合いだとは言っても、なかなかうまくいかないものね。",
  ui_story_5080_50800301_32_dialog_content = "あなたのタイミングが良かったわね、おかげで逃げられたわ。",
  ui_story_5080_50800301_33_dialog_content = "…こうなるだろうとは思っていた。奴らに道理は通じない。",
  ui_story_5080_50800301_34_dialog_content = "逃亡兵の寄せ集めの賊にすぎないのだから。",
  ui_story_5080_50800301_35_dialog_content = "そんなことないよ！",
  ui_story_5080_50800301_36_dialog_content = "R・Wの皆は悪い人たちじゃない…\nちゃんと話せば、サメヤマだって道理の通じる相手なんだ。",
  ui_story_5080_50800301_37_dialog_content = "R・W砂漠で長い間暮らしてるんだし、\n「フリーバード」の情報も知ってるかもしれない…",
  ui_story_5080_50800301_38_dialog_content = "逃亡兵たちの信用いかんを話し合っても意味はない。\nその話はここまでとしよう。",
  ui_story_5080_50800301_39_dialog_content = "君たちが奴らのキャンプに向かっている間、\n今回の任務の調査対象の痕跡を発見した。ついて来い。",
  ui_story_5080_50800301_40_dialog_content = "話聞いてよ…",
  ui_story_5080_50800301_41_dialog_content = "見ろ、高温で焼かれた砂だ。それから、火山灰の痕も…",
  ui_story_5080_50800301_42_dialog_content = "間違いない。この先にいる。",
  ui_story_5080_50800301_43_dialog_content = "この痕跡…複数体いますよね。",
  ui_story_5080_50800301_44_dialog_content = "目標はすでに「増殖」している可能性が高い。気を付けろ。",
  ui_story_5080_50800301_45_dialog_content = "隊長、いました！",
  ui_story_5080_50800301_X45_dialog_content = "グガァ…ウガァア――",
  ui_story_5080_50800301_46_dialog_content = "これは…マグマ…いえ、暗鬼なの？",
  ui_story_5080_50800301_47_dialog_content = "今まで見て来た暗鬼とはまったく違う…\nまるで歩くマグマだ…",
  ui_story_5080_50800301_48_dialog_content = "この暗鬼…見た目がいびつだから、弱点も分かりにくい。",
  ui_story_5080_50800301_49_dialog_content = "これほどの高温エネルギーで守られているとなると、\n遠距離攻撃もおそらく効かないでしょうね。",
  ui_story_5080_50800301_50_dialog_content = "戦闘準備だ。",
  ui_story_5080_50800301_51_dialog_content = "でも…",
  ui_story_5080_50800301_52_dialog_content = "ホワイトランス、君の能力は奴らの力を制することができる。\nしかも君は正面突破に長けているから、先陣を頼もう。",
  ui_story_5080_50800301_53_dialog_content = "啓光の隊長さん、あなたに指示される筋合いはないわ。",
  ui_story_5080_50800301_54_dialog_content = "君は「天馬の力」を呼び出せるんだろう？向かい合った状況から\n天馬の力で飛び上がり、上から意表をついた攻撃をするといい。",
  ui_story_5080_50800301_55_dialog_content = "構造から推察するに、奴らも全身を完全に防御はできないはずだ。\nほころびが生じた隙をつけば、君の技は致命傷を与えられる。",
  ui_story_5080_50800301_56_dialog_content = "…",
  ui_story_5080_50800301_57_dialog_content = "ヤングドラゴン2号、君は自身の機動性を活かし、ホワイトランスが戦っている間、\n「速射感知」で暗鬼たちを攻撃するんだ。",
  ui_story_5080_50800301_58_dialog_content = "どんな暗鬼であろうと、攻撃時には必ず弱点を露呈するものだ。\nその時こそ君の力を発揮すべき時だ。",
  ui_story_5080_50800301_59_dialog_content = "弱点を突かれれば、奴らもバランスを失う。\nホワイトランス、そうなれば君にチャンスが回ってくる。奴らを斬れ。",
  ui_story_5080_50800301_60_dialog_content = "了解です！",
  ui_story_5080_50800301_61_dialog_content = "私はホークハンター1号、2号、3号と共に火力で奴らを抑え込み、\nホワイトランスのもとへ誘導する。",
  ui_story_5080_50800301_62_dialog_content = "火力が続く限り、奴らも協力し合えないはずだ。\nそうすれば…斬殺も容易だ。",
  ui_story_5080_50800301_63_dialog_content = "あなたの戦術で…行きましょう。",
  ui_story_5080_50800301_64_dialog_content = "（会ったばかりなのに、カレンとバイスの能力を正確につかんでる。\nしかも、それぞれの特性を生かした戦術を組み立てた…）",
  ui_story_5080_50800301_65_dialog_content = "空の末裔1号。",
  ui_story_5080_50800301_66_dialog_content = "はい！",
  ui_story_5080_50800301_67_dialog_content = "戦闘中の指揮は任せた。",
  ui_story_5080_50800301_68_dialog_content = "えっ？",
  ui_story_5080_50800301_69_dialog_content = "どんなに十分な準備をしていても、戦いは刻一刻と目まぐるしく変わるものだ。",
  ui_story_5080_50800301_70_dialog_content = "君には私たちに見えない「光」が見える。\n戦闘中は君の方が正確な指揮ができるだろう。",
  ui_story_5080_50800301_71_dialog_content = "…それに、君たちは息の合った仲間だから。",
  ui_story_5080_50800301_72_dialog_content = "私よりも…2人の「相棒」にふさわしい。",
  ui_story_5080_50800301_73_dialog_content = "レイチェル…",
  ui_story_5080_50800301_74_dialog_content = "隊長だ。",
  ui_story_5080_50800301_75_dialog_content = "行くぞ、空の末裔1号！",
  ui_story_5080_50800302_1_dialog_content = "隊長、あぶない！",
  ui_story_5080_50800302_2_dialog_content = "うっ…ホワイトランス、今だ！",
  ui_story_5080_50800302_3_dialog_content = "「魂貫ノ一撃」！",
  ui_story_5080_50800302_4_dialog_content = "まずい、隊長が攻撃を受けたわ！早く…",
  ui_story_5080_50800302_5_dialog_content = "ヤングドラゴン2号、何をしている！1匹そっちへ行ったぞ！",
  ui_story_5080_50800302_6_dialog_content = "ホークハンター1号、2号、急いで止めろ！",
  ui_story_5080_50800302_7_dialog_content = "グガァ――！",
  ui_story_5080_50800302_8_dialog_content = "…間に合ったか。",
  ui_story_5080_50800302_9_dialog_content = "全部、片付いたね…危なかった…",
  ui_story_5080_50800302_10_dialog_content = "ヤングドラゴン2号、何だあれは？",
  ui_story_5080_50800302_11_dialog_content = "私…",
  ui_story_5080_50800302_12_dialog_content = "君は兵士としては感情で動きすぎる。",
  ui_story_5080_50800302_13_dialog_content = "けがをしようと、君がまず気に掛けるべき相手は私ではない。\n任務こそ最優先事項だ。",
  ui_story_5080_50800302_14_dialog_content = "中規模の暗鬼の群れをせん滅したんだ。これしきのけが、\n効率の高い戦闘で払った最低限の代償に過ぎない。",
  ui_story_5080_50800302_15_dialog_content = "君は…彼らと長く一緒にいすぎたようだな。\n自分が啓光の兵士であることを忘れたか？",
  ui_story_5080_50800302_16_dialog_content = "いえ…そうではありません。",
  ui_story_5080_50800302_17_dialog_content = "そんなの言い過ぎだよ。バイスは君を心配しただけなのに…",
  ui_story_5080_50800302_18_dialog_content = "…戦闘中に気が散れば、思わぬ代償を払うことになる。\nさっきもヤングドラゴン2号までけがしていたらどうするのだ？",
  ui_story_5080_50800302_19_dialog_content = "私の指示に従って任務に失敗したのなら、責任はすべて私が負う。",
  ui_story_5080_50800302_20_dialog_content = "部下にも責任を持つ…君たちが私を信じる限りはな。",
  ui_story_5080_50800302_21_dialog_content = "確かにその通り。とても経験豊富なベテランの隊長ね。",
  ui_story_5080_50800302_22_dialog_content = "あなたの考え、理解したわ。",
  ui_story_5080_50800302_23_dialog_content = "カレン？",
  ui_story_5080_50800302_24_dialog_content = "まったく…バイス、大丈夫？",
  ui_story_5080_50800302_25_dialog_content = "ええ…",
  ui_story_5080_50800302_26_dialog_content = "この暗鬼どもの…しかばねの「姿」は…",
  ui_story_5080_50800302_27_dialog_content = "隊長、まだ血が…",
  ui_story_5080_50800302_28_dialog_content = "放っておきましょう。言っても無駄よ。",
  ui_story_5080_50800302_29_dialog_content = "あの人は、私たちには測り知れないほどの「重み」を背負っているのよ。",
  ui_story_5080_50800302_30_dialog_content = "あの眼差しを私は良く知っているわ。\n啓光の兵士も白夜城の者に似ることがあったのね…",
  ui_story_5080_50800302_31_dialog_content = "私は長い間前線で戦ってきた。\n目にしてきた暗鬼の数は枚挙にいとまがない。",
  ui_story_5080_50800302_32_dialog_content = "だが、こんなのは…初めてだ。",
  ui_story_5080_50800302_33_dialog_content = "頭部の構造からして、「暗面」を離れてだいぶ経つようだ。",
  ui_story_5080_50800302_34_dialog_content = "しかも、戦闘型に進化した暗鬼どもとは生体構造も少し違うようだ。",
  ui_story_5080_50800302_35_dialog_content = "皮膚には耐熱性があり、身体はエネルギーを貯蓄できる…\n環境に合わせて進化した結果だな。",
  ui_story_5080_50800302_36_dialog_content = "実に奇妙だ。しかばねの残留時間も長くなっている…",
  ui_story_5080_50800302_37_dialog_content = "…そして、どの死体も似てますね。",
  ui_story_5080_50800302_38_dialog_content = "気付いたか。鋭いな…感情が豊かなことを除けば、\n君は実に立派な偵察隊長だ。",
  ui_story_5080_50800302_39_dialog_content = "ごめん、「似てる」って何が？\n僕には、ほとんどの暗鬼が似て見えるけど？",
  ui_story_5080_50800302_40_dialog_content = "他の暗鬼は似てるというより、そっくりそのままよ。",
  ui_story_5080_50800302_41_dialog_content = "暗鬼は「繁殖」をしていないって推測する人もたくさんいるくらいなの。",
  ui_story_5080_50800302_42_dialog_content = "でも、こいつらは「子孫」で間違いない…\nよく似てはいるが、同じではないから。",
  ui_story_5080_50800302_43_dialog_content = "この暗鬼どもは「遺伝性」を持っていて、\n代々受け継いでいるんだ。",
  ui_story_5080_50800302_44_dialog_content = "資料には、前回この類の暗鬼を発見したのは、\n30年以上も前のことだとあった。",
  ui_story_5080_50800302_45_dialog_content = "ここにいる暗鬼は当時の報告書にあったものよりも身体が小さく、力も弱い。\nおそらく、何らかの形で「繁殖」して生き延びた子孫だろう…",
  ui_story_5080_50800302_46_dialog_content = "その通りね。",
  ui_story_5080_50800302_47_dialog_content = "<color=#FFB400>暗潮の危機</color>の時、R・Wにもこの暗鬼を見た者がいたの。\n当時と比べると、あなたたちの倒したヤツらはちっぽけねぇ。",
  ui_story_5080_50800302_48_dialog_content = "イェリア！？いつから神出鬼没キャラになったの！？",
  ui_story_5080_50800302_49_dialog_content = "あのねぇ、この砂漠は全部、アタシの管轄って言っていいのよ。",
  ui_story_5080_50800302_50_dialog_content = "なにっ…？ホークハンター3号の探知にかからなかったのか？",
  ui_story_5080_50800302_51_dialog_content = "あら、あのドローン、そんな名前だったのね。\n何だか故障してるみたいだったけど？",
  ui_story_5080_50800302_52_dialog_content = "何だって？ホークハンター3号、戻ってこい！",
  ui_story_5080_50800302_53_dialog_content = "まさか15年も経って、火山が騒ぎ出すのと一緒に\nこの暗鬼も再び現れるなんてね…",
  ui_story_5080_50800302_54_dialog_content = "イェリア、何か知ってるの？",
  ui_story_5080_50800302_55_dialog_content = "フフ、アタシもただ<color=#FFB400>答え</color>を追って来ただけよぉ。",
  ui_story_5080_50800302_56_dialog_content = "ホークハンター3号の「伝導モジュール」が破損している。\nしかも、奇妙な部品まで取り付けられているではないか…",
  ui_story_5080_50800302_57_dialog_content = "あ、あ、聞こえる？こんにちは――",
  ui_story_5080_50800302_58_dialog_content = "この声は…",
  ui_story_5080_50800302_59_dialog_content = "ゼタ？",
  ui_story_5080_50800302_60_dialog_content = "<color=#FFB400>武器マスター</color>の気遣いで、孤高のタカに、コレを…\nえっと、なんていうんだっけ？",
  ui_story_5080_50800302_61_dialog_content = "あ、そうそう！「裏口」…ってか、ヘンな名前だね！ま、いいや。\nとにかく、孤高のタカに通信装置をつけといたんだ。",
  ui_story_5080_50800302_62_dialog_content = "孤高のタカを<color=#FFB400>直して</color>欲しければ、\n「麗しのエルダー」イェリアのお家に来るんだね。",
  ui_story_5080_50800302_63_dialog_content = "…こっちを見ないでくれる？\nアタシが決めたんじゃないわ。",
  ui_story_5080_50800302_64_dialog_content = "ホークハンター3号が敵に改造されてしまった。\n早く修理しなくては…",
  ui_story_5080_50800302_65_dialog_content = "！！！",
  ui_story_5080_50800302_66_dialog_content = "道具袋が…いつの間に焦げてしまったんだ？",
  ui_story_5080_50800302_67_dialog_content = "自分の身の安全も顧みないほど没頭してたから気づいてなかったみたいだけど、\nその袋はさっきの戦闘中ダメになってたんだよ。",
  ui_story_5080_50800302_68_dialog_content = "そこのクーリエ、奴らがここにいるということは、\nお前も加担していたのか？",
  ui_story_5080_50800302_69_dialog_content = "アタシはただ、ある過去の答えを探しに来ただけよ。\n他には何も考えていやしないわぁ。",
  ui_story_5080_50800302_70_dialog_content = "でも、あなたを見てると、ある知り合いを思い出すわねぇ。",
  ui_story_5080_50800302_71_dialog_content = "アタシについて来な～い？\nそうすれば、お互い探してたモノが見つかるかもしれないわぁ。",
  ui_story_5080_50800302_72_dialog_content = "…",
  ui_story_5080_50800302_73_dialog_content = "イェリアはクーリエ隊のエルダーで、信用できる人だよ。",
  ui_story_5080_50800302_74_dialog_content = "行こう。",
  ui_story_5080_50800401_1_dialog_content = "ごめんね、僕たちまで乗せてもらっちゃって。",
  ui_story_5080_50800401_2_dialog_content = "別に初めてじゃないでしょ。しっかりつかまっててよぉ。",
  ui_story_5080_50800401_3_dialog_content = "うう…",
  ui_story_5080_50800401_4_dialog_content = "あ！R・Wのキャンプだよ、隠れて！",
  ui_story_5080_50800401_5_dialog_content = "大丈夫、忙しくてこっちに構ってる暇ないわよぉ。",
  ui_story_5080_50800401_6_dialog_content = "間に合わない、間に合わない！修理がぜんっぜん、追いつかないよ～！\nゼタのやつ、どこ行ったの？見つけたら、タダじゃおかないから！",
  ui_story_5080_50800401_7_dialog_content = "イェリアの車じゃないか？イェリア！メシできてるぞ。\n食べていかないか？",
  ui_story_5080_50800401_8_dialog_content = "また今度ね～。",
  ui_story_5080_50800401_9_dialog_content = "だったら、そん時はアズールも呼ぼうな！",
  ui_story_5080_50800401_10_dialog_content = "イェリアさん、スピードを落としてください。\nそっちには落とし穴がありますよ。",
  ui_story_5080_50800401_11_dialog_content = "ありがと～。",
  ui_story_5080_50800401_12_dialog_content = "おい、イェリア！見てくれ！これって『R・Wのボスの成り方』じゃねぇよな？\n字を読めねぇのをいいことに、みんな俺様をだましてんのか？",
  ui_story_5080_50800401_13_dialog_content = "そもそもそんな本ないのよ。だまされたに決まってるじゃな～い。",
  ui_story_5080_50800401_14_dialog_content = "イェリア、この間は工具の配送、ありがとう。\n今週は少し時間があるんだ。車を改造してあげるよ。",
  ui_story_5080_50800401_15_dialog_content = "そうね。",
  ui_story_5080_50800401_16_dialog_content = "イェリア…何だかちょっと変わったね。",
  ui_story_5080_50800401_17_dialog_content = "以前は見つけにくい所に住んでたのに、\n今はR・Wの皆ともうまくやってるみたいだ。",
  ui_story_5080_50800401_18_dialog_content = "フフ、空の末裔くんったら本当、鋭いわねぇ。",
  ui_story_5080_50800401_19_dialog_content = "人って、変わるものなのよ～。",
  ui_story_5080_50800401_20_dialog_content = "あなたのおかげで、アタシも他人と関わりを持つのが\n楽しくなってきたのかもしれないわね～。",
  ui_story_5080_50800401_21_dialog_content = "…ちょ、ちょっと狭いね。\nバイス、後部座席はそんなに広くないから…",
  ui_story_5080_50800401_22_dialog_content = "音楽ってのは、最大ボリュームで放ってこそ、\n自由の本質を突けるんだ！！",
  ui_story_5080_50800401_23_dialog_content = "あ～あ、おバカさんはいつでも騒がしいな～。",
  ui_story_5080_50800401_24_dialog_content = "失敗、挫折、恐怖は逃げることしか教えない！",
  ui_story_5080_50800401_25_dialog_content = "逃げれば、苦しみは増すだけだ！",
  ui_story_5080_50800401_26_dialog_content = "ゼタの運転って大したことないよね～。\nでも、友達だから、別に言ってもいいよね～。",
  ui_story_5080_50800401_27_dialog_content = "バイス、顔色が良くないわ。どうしたの？",
  ui_story_5080_50800401_28_dialog_content = "な、何でもないわ…隊長、だいぶ揺れているので、\n手当は後にした方がいいですよ。",
  ui_story_5080_50800401_29_dialog_content = "どこかに止まったら、私が手当します。",
  ui_story_5080_50800401_30_dialog_content = "構わない。1人には慣れているから。",
  ui_story_5080_50800401_31_dialog_content = "揺れもなんてことはない…それから、敬語は使うな。\n年上というほど歳も違わない。",
  ui_story_5080_50800401_32_dialog_content = "君は私の1つ下だろう？それなのに立派に隊長を務めている。\n私に敬意を払う必要などない。",
  ui_story_5080_50800401_33_dialog_content = "あなたって啓光の偵察兵よね？\nその制服を見る限り、精鋭部隊みたいねぇ。",
  ui_story_5080_50800401_34_dialog_content = "アタシにはわかるの。あなたは、他の小鳥ちゃんたちとは違う。\nホンモノの猛禽ちゃんよねぇ。",
  ui_story_5080_50800401_35_dialog_content = "そんなあなたが出てくるなんて、いったいどんな任務かしら～？",
  ui_story_5080_50800401_36_dialog_content = "啓光の機密事項だ。君とは関係ない。",
  ui_story_5080_50800401_37_dialog_content = "そうとも言い切れないんじゃな～い？\n運命って、わからないものよぉ。",
  ui_story_5080_50800401_38_dialog_content = "あなたみたいな猛禽ちゃんがここに来るなんて、\nきっと何か深い意味があるんでしょうねぇ。",
  ui_story_5080_50800401_39_dialog_content = "サメ坊、見てみろ。この<color=#FFB400>痕跡</color>だ。",
  ui_story_5080_50800401_40_dialog_content = "カフカの言ってたのと一緒だな。\nイェリアが前に話してた<color=#FFB400>痕跡</color>だ。",
  ui_story_5080_50800401_41_dialog_content = "サメ坊はやめねぇか…ってか、この痕跡、マグマだろ？",
  ui_story_5080_50800401_42_dialog_content = "なんだってマグマがこんな所にあんだ？",
  ui_story_5080_50800401_43_dialog_content = "んじゃ、この先も見てみるかねェ。他に何か分かるかもな。",
  ui_story_5080_50800401_44_dialog_content = "おい、ロイ ！これって暗鬼か？ボロボロにやられちゃいるが、\n間違いなく暗鬼の死骸だろ？",
  ui_story_5080_50800401_45_dialog_content = "誰かがやったんだねェ…つっても、こりゃ不思議だなァ。\nオッさんもこんなにのろのろ消滅する暗鬼は初めてみたぞ。",
  ui_story_5080_50800401_46_dialog_content = "ロイ 、よく見てみてくれ。\nコイツらは「当時」見た<color=#FFB400>あの暗鬼</color>か？",
  ui_story_5080_50800401_47_dialog_content = "15年前、俺たちが当時のキャンプを追われた時…\n殿を務めた<color=#FFB400>ボス</color>が出くわした<color=#FFB400>あの暗鬼</color>は…",
  ui_story_5080_50800401_48_dialog_content = "お前しか知らねぇ。",
  ui_story_5080_50800401_49_dialog_content = "確かに似てるな。けど<color=#FFB400>当時のアイツ</color>とは違うねェ。\nおそらく、<color=#FFB400>子孫</color>ってトコだろうな。",
  ui_story_5080_50800401_50_dialog_content = "クソッたれが。10年以上経ってるってのに、\nガキまで山ほど残してやがったのか。",
  ui_story_5080_50800401_51_dialog_content = "このまま追うぞ！痕跡をたどって、<color=#FFB400>ヤツら</color>の根城をぶっ潰す！",
  ui_story_5080_50800401_52_dialog_content = "ここはもう火山か。ずいぶん暑いな。\nどうやらイェリアの言った通り、マジで目覚めたみたいだねェ。",
  ui_story_5080_50800401_53_dialog_content = "なんだって、ここで痕跡が消えてやがんだ？",
  ui_story_5080_50800401_54_dialog_content = "これは他の暗鬼の足跡だ…痕跡を消したってことか。",
  ui_story_5080_50800401_55_dialog_content = "怒号の火山は地中深くに埋まった火山だ。\nこの下に何本も道が隠れてるのかもしれねえなァ。",
  ui_story_5080_50800401_56_dialog_content = "ハッキリした目標もなく、やみくもに地下に入るのは危険だぞ。",
  ui_story_5080_50800401_57_dialog_content = "チッ、隠れてねぇで出てこい！",
  ui_story_5080_50800401_58_dialog_content = "俺はもう鼻垂らしたガキじゃねえぞ！\n出て来て決着をつけやがれ！",
  ui_story_5080_50800401_59_dialog_content = "クソッ！！",
  ui_story_5080_50800401_60_dialog_content = "おいおい、それ以上山肌を攻撃すんなって。\nここは構造がもろいっつーの…うわああああ――",
  ui_story_5080_50800401_61_dialog_content = "<color=#e8d9bb>サメヤマの拳の先の山が揺れ出したかと思うと、洞窟の奥から反響が伝わってきた。\nザワザワと無数の暗鬼の声が暗闇から聞こえてくる。</color>",
  ui_story_5080_50800401_62_dialog_content = "おいおい、崩れるぞ！\nけど、ここの主もついにお出ましになるみたいだな。",
  ui_story_5080_50800401_63_dialog_content = "おい、ロイ ！アイツらで間違いねぇな？",
  ui_story_5080_50800401_64_dialog_content = "もうこらえきれなくなったか？\nアイツらの根城はこの近くみてえだ。",
  ui_story_5080_50800401_65_dialog_content = "サメ坊、気を付けろよ…それと、速攻で片付けろ。",
  ui_story_5080_50800401_66_dialog_content = "フン、俺のレンチを甘く見んじゃねえぞ。\n行くぞ、ロイ！",
  ui_story_5080_50800402_1_dialog_content = "さぁ入って。楽にしてちょうだい。\nどうせここには誰も――",
  ui_story_5080_50800402_2_dialog_content = "見るがいい！勇者ゼタの無敵の絵心を！",
  ui_story_5080_50800402_3_dialog_content = "おおお、まるで生きてるみたいだね！",
  ui_story_5080_50800402_4_dialog_content = "うむ。これしきのこと、勇者ゼタにとっては大したことではない！",
  ui_story_5080_50800402_5_dialog_content = "あなたたち、また勝手に入ってイタズラ書きしてたの？",
  ui_story_5080_50800402_6_dialog_content = "「麗しのエルダー」の家は面白味に欠けている！\n救世主自ら彩を添えてやったのだ、喜んで受け取るがいい！",
  ui_story_5080_50800402_7_dialog_content = "…モノを壊してなければ、まぁいいわぁ。",
  ui_story_5080_50800402_8_dialog_content = "それにアタシは「麗しのエルダー」なんかじゃないわよ～。\nナルセールにこそふさわしい呼び名だわ。",
  ui_story_5080_50800402_9_dialog_content = "その人には会ったことないよ。でも、いい名前だな。\nあ、そうだ。あたしたちで替わりに配達物を整理しといたよ。",
  ui_story_5080_50800402_10_dialog_content = "散らかってたのを整理整頓して、ゴミも捨てといたもんね。",
  ui_story_5080_50800402_11_dialog_content = "あら、すごいじゃな～い。",
  ui_story_5080_50800402_12_dialog_content = "へっへ～ん、「麗しのエルダー」からはずっと任務報酬もらってるし、\n勇者ゼタはタダで報酬をもらったりしないよ！",
  ui_story_5080_50800402_13_dialog_content = "そう。ただ顔料を配達物にこぼさないでちょうだい。\nそれから、あなたたち。突っ立ってないで座りなさいよ～。",
  ui_story_5080_50800402_14_dialog_content = "本当に変わったんだね、イェリア…\n他人と関わりを持つようになって、しかも楽しそうだ。",
  ui_story_5080_50800402_15_dialog_content = "本当に、よかった。",
  ui_story_5080_50800402_16_dialog_content = "そう？でも確かに、おチビちゃんたちがいると毎日飽きないわね～。",
  ui_story_5080_50800402_17_dialog_content = "これは偵察と攻撃両用の生物模倣ドローン、ホークハンター3号だ。\n啓光の先端技術を用いたものだが…君たちで本当に直せるのか？",
  ui_story_5080_50800402_18_dialog_content = "武器マスター、任せたよ！",
  ui_story_5080_50800402_19_dialog_content = "爪の把持テスト開始、左、右、左…\n「伝導モジュール」が壊れてる。たぶん衝突が原因だね。",
  ui_story_5080_50800402_20_dialog_content = "ふっふ～ん、我らが誇り、武器マスターに任せておけ！\nこやつにできぬことはない！",
  ui_story_5080_50800402_21_dialog_content = "武器マスター、助けてくれるよね？",
  ui_story_5080_50800402_22_dialog_content = "できる限りのことはしてみるよ。",
  ui_story_5080_50800402_23_dialog_content = "工具を貸してくれ。私も手伝おう。",
  ui_story_5080_50800402_24_dialog_content = "ホークハンターは私の戦友なんだ…他人任せにはできない。",
  ui_story_5080_50800402_25_dialog_content = "焦ることはない。「中立の英雄、飛鷹ハンター」よ！",
  ui_story_5080_50800402_26_dialog_content = "…",
  ui_story_5080_50800402_27_dialog_content = "気にしないで。ゼタはいつもこうなんだ。",
  ui_story_5080_50800402_28_dialog_content = "孤高のタカがおぬしの部下と知ったからには、\n勇者ゼタは二度とおぬしの仲間に手を出さないと約束しよう。",
  ui_story_5080_50800402_29_dialog_content = "孤高のタカが負傷したのは私の責任だ。\nよって、勇者ゼタが治療してやろう！",
  ui_story_5080_50800402_30_dialog_content = "治療はタイニーに任せてるよね…",
  ui_story_5080_50800402_31_dialog_content = "空の末裔よ！宿命のごとき再会が、\nおぬしにこれ程まで強力な仲間をもたらそうとは！",
  ui_story_5080_50800402_32_dialog_content = "普通に話そうよ…",
  ui_story_5080_50800402_33_dialog_content = "だが、勇者ゼタは決してあきらめはしない！",
  ui_story_5080_50800402_34_dialog_content = "おぬしが中立の英雄であろうとなかろうと、空の末裔の仲間となるのならば、\n必ずや勇者ゼタとも旅を共にすることができるだろう！",
  ui_story_5080_50800402_35_dialog_content = "たとえ魔道に落ちた者であろうと構わない。\n私はおぬしの強大な力を買っているのだ！",
  ui_story_5080_50800402_36_dialog_content = "私は…",
  ui_story_5080_50800402_37_dialog_content = "言わずともよい。すべて承知している！",
  ui_story_5080_50800402_38_dialog_content = "おぬしのように誇り高き者には、納得できまい。",
  ui_story_5080_50800402_39_dialog_content = "構わぬ。おぬしと公平に競うため、\n私は武器マスターに孤高のタカを直させたのだからな。",
  ui_story_5080_50800402_40_dialog_content = "必ずや屈服させてやろう…ふふっ、ふふふ…「飛鷹ハンター」のような強大な部下がいれば、\nあの「魔女」ごとき私の相手ではない。",
  ui_story_5080_50800402_41_dialog_content = "君の方がよっぽど悪者みたいだけど。",
  ui_story_5080_50800402_42_dialog_content = "レイチェル、気にしないでね。ゼタは…こういう話し方なんだ。",
  ui_story_5080_50800402_43_dialog_content = "そ、そうですよ、隊長。\nホークハンター3号が直ったら、ここを発ちましょう。",
  ui_story_5080_50800402_44_dialog_content = "構わない。",
  ui_story_5080_50800402_45_dialog_content = "聞いたでしょ、ゼタ。早く謝って…って、今なんて？",
  ui_story_5080_50800402_46_dialog_content = "君はR・Wの賊だが…その…",
  ui_story_5080_50800402_47_dialog_content = "事情を知らなかったんだ。今回は見逃してやる。",
  ui_story_5080_50800402_48_dialog_content = "君はまだ若い。他の奴らのように砂漠の悪党にはなるな。",
  ui_story_5080_50800402_49_dialog_content = "へっへ～ん、あんたには分かりやしないだろうけど、\nゼタの夢は伝説の英雄になることなんだ。砂漠の救世主だよ！",
  ui_story_5080_50800402_50_dialog_content = "それならいい。さっきの攻撃で、けがはしなかったか？",
  ui_story_5080_50800402_51_dialog_content = "え？ケガなんてしてないよ！勇者ゼタがあれくらいでケガするわけないじゃん。\n怖いとさえ思わなかったもん。泣いたりしてないよ！",
  ui_story_5080_50800402_52_dialog_content = "それでいい。君は勇敢だ。",
  ui_story_5080_50800402_53_dialog_content = "私の見間違いではないわよね…？",
  ui_story_5080_50800402_54_dialog_content = "ゼタがすっかり懐いてる…",
  ui_story_5080_50800402_55_dialog_content = "隊長に…こんな一面もあったのね？",
  ui_story_5080_50800402_56_dialog_content = "カレンが言ってたみたいに、レイチェルは経験豊富なベテランの隊長なんだろうね。\nだから、後輩たちの扱いも上手なんだ。",
  ui_story_5080_50800402_57_dialog_content = "でも…",
  ui_story_5080_50800402_58_dialog_content = "（あれが本当の隊長なのかな？僕たちには冷たいのに…）",
  ui_story_5080_50800402_59_dialog_content = "（任務には感情を持ち込まない主義なのか、それとも…\n何かもっと深いわけがあるのか…）",
  ui_story_5080_50800402_60_dialog_content = "本当に興味深いわぁ。砂漠の空には、色々な旅烏が飛んでくるけど、\n爪を収めることのできる猛禽ちゃんなんて、初めてよぉ。",
  ui_story_5080_50800402_61_dialog_content = "ゼタ、このドローン、筐体の隙間から砂が入っちゃったせいで、\n回路のケーブルが燃えちゃってるよ。",
  ui_story_5080_50800402_62_dialog_content = "ちょっと手間のかかる修理が必要なんだけど、\nあたし、そういう細かい作業は苦手なんだ。",
  ui_story_5080_50800402_63_dialog_content = "え、ええ？",
  ui_story_5080_50800402_64_dialog_content = "無理なら、工具を貸してくれ。私が自分で修理する。",
  ui_story_5080_50800402_65_dialog_content = "いやいやいや、待って！ちょっと待って！",
  ui_story_5080_50800402_66_dialog_content = "勇者ゼタは責任を取ると言ったはずだ。\n達人同士の戦いだ、誇りは捨てられん！",
  ui_story_5080_50800402_67_dialog_content = "これからだと言う時に、あきらめていいものか…\n武器マスター、本当に無理なのか？",
  ui_story_5080_50800402_68_dialog_content = "「機械モンスター」オティを思い出せ！ヤツは細かい作業が得意だぞ！\nおぬし、ヤツに後れを取ってもよいのか！？",
  ui_story_5080_50800402_69_dialog_content = "今…なんて言った？",
  ui_story_5080_50800402_70_dialog_content = "見てなよ！これくらい、あたしに出来ないワケないもん！",
  ui_story_5080_50800402_71_dialog_content = "なにが機械モンスターだよ。一緒にしないでくれる？\nすぐに直してみせるから！",
  ui_story_5080_50800402_72_dialog_content = "どうしてタイニーがいつもゼタの「言うこと聞いてる」か、\n分かった気がする…",
  ui_story_5080_50800402_73_dialog_content = "どうやら、すぐには終わりそうもないわねぇ。\nもう遅いし、みんなここで一晩過ごすといいわぁ。",
  ui_story_5080_50800402_74_dialog_content = "そんな…悪いよ。",
  ui_story_5080_50800402_75_dialog_content = "フフ、家に誰かいるのにも、慣れてきたわぁ。",
  ui_story_5080_50800402_76_dialog_content = "それに…猛禽ちゃん。\nあなたとは色々と、お話ができる気がするのよねぇ。",
  ui_story_5080_50800500_1_dialog_content = "<color=#e8d9bb>夜が深まるにつれ、砂漠は冷え込んできた。\n一見誰もいない砂の下では、暗流がうごめき、不気味な音を立て――</color>",
  ui_story_5080_50800500_2_dialog_content = "<color=#e8d9bb>黒い影が、地中から飛び出してきた！</color>",
  ui_story_5080_50800500_3_dialog_content = "ペッ――！",
  ui_story_5080_50800500_4_dialog_content = "ペッペッペッペッ！",
  ui_story_5080_50800500_5_dialog_content = "ペッ…ゲホゲホッ…ペッ！ロ、ロイ、大丈夫か？",
  ui_story_5080_50800500_6_dialog_content = "サメ坊よォ、次に洞窟を崩す時にゃ先に言っといてくんないかねェ。\nあちこちガタがきてるオッさんには、キツイんだなァ…",
  ui_story_5080_50800500_7_dialog_content = "ははっ――つっても、こんなに痛快なのは久しぶりだな！",
  ui_story_5080_50800500_8_dialog_content = "痛快は痛快だけどねェ、洞窟が崩れた今、根城はどこにあるのやら…\nしかも、あの数…面倒なことになりそうだなァ。",
  ui_story_5080_50800500_9_dialog_content = "構いやしねえよ。戻ったら他は何も言わずに、\nあの暗鬼の根城を片付けたって言えばいいさ。",
  ui_story_5080_50800500_10_dialog_content = "そんなんで本当にいいのか？\n俺たちが片付けたあの暗鬼たちは明らかにほんの一部だぞ？",
  ui_story_5080_50800500_11_dialog_content = "地下の通路はあちこちに通じてるみたいだったしな。\nもしかしたら、本当の根城は火山の中かもしれないねェ…",
  ui_story_5080_50800500_12_dialog_content = "だったら、中に突っ込むまでだ！",
  ui_story_5080_50800500_13_dialog_content = "大丈夫かねェ？",
  ui_story_5080_50800500_14_dialog_content = "あそこにゃ先代のお頭でさえやれなかった暗鬼がいるかもしれねえんだぞ。\n俺たちが見たのより、ずっとデカくて強いヤツがな。",
  ui_story_5080_50800500_15_dialog_content = "急いで全員に知らせて、\nこっちも固まって迎え撃たなきゃダメだろ。",
  ui_story_5080_50800500_16_dialog_content = "その時になりゃ、もちろん知らせるさ。だが、事は<color=#FFB400>あの野郎</color>と関係あんだぞ。\nガキどもを巻き込むワケにはいかねえ。",
  ui_story_5080_50800500_17_dialog_content = "何が違うってんだかねェ。\nサメ坊、お前だってまだガキんちょで頭になったんだろが。",
  ui_story_5080_50800500_18_dialog_content = "だから、言うんじゃねぇって言ってんだよ。\n俺たちと<color=#FFB400>あの野郎</color>との怨恨はガキどもとは関係ねぇだろ。",
  ui_story_5080_50800500_19_dialog_content = "今、このレンチを握ってんのは俺だ。俺がR・Wの頭だ。\n先代の仇は俺が打つ。兄弟たちの心残りを晴らしてやる。だから…",
  ui_story_5080_50800500_20_dialog_content = "今は言うな、ロイ。",
  ui_story_5080_50800500_21_dialog_content = "「俺が代わりに全部片づける」…ってか。\n先代もそう言ってたっけねェ。今のお前みたいに。",
  ui_story_5080_50800500_22_dialog_content = "その結果がこれよ。\n生き残った俺たちに尽きねぇ後悔ばっか残しやがって。",
  ui_story_5080_50800500_23_dialog_content = "ガキどもまで<color=#FFB400>あの野郎</color>とやり合わせて、\nあん時の俺たちと同じように何もできなかったら、その時にはあいつらも…",
  ui_story_5080_50800500_24_dialog_content = "そりゃ違ぇよ、サメ坊。こんだけ何だかんだと乗り越えて来て、\nお前まだガキんちょどもの成長に気づいてないのか？",
  ui_story_5080_50800500_25_dialog_content = "当時のことは知らないヤツも、覚えてないヤツもいるがな、\nみんな俺たちの力強い仲間だろが。",
  ui_story_5080_50800500_26_dialog_content = "ゼタの両親がやられちまった時、アイツはまだ2歳にもなってなかった。\n背だってタイヤの高さにも届かねぇくらいだったのが、今じゃ1人で砂漠を横断しやがる。",
  ui_story_5080_50800500_27_dialog_content = "あいつから、過去と向き合うチャンスを奪おうってのか？",
  ui_story_5080_50800500_28_dialog_content = "そういう意味じゃねぇよ、分かってんだろ、ロイ。",
  ui_story_5080_50800500_29_dialog_content = "分かってるさ。お前はまだガキんちょどもの手を放せないんだろ。\n横暴だなァ、サメ坊よォ。",
  ui_story_5080_50800500_30_dialog_content = "先代がよく言ってた言葉、覚えてるだろ？仲間の選択を尊重しろってさ。\n誰にでも自由でいる権利があるって、先代は信じてた。",
  ui_story_5080_50800500_31_dialog_content = "あいつらも成長したって認めなきゃなァ。\n俺たちオッさんどもは、そろそろ手を放すことも覚えねぇと。",
  ui_story_5080_50800500_32_dialog_content = "嵐が来るってなら、一緒に立ち向かってやりゃあいい。\nけど、ただ前に立って守ってやるだけじゃいけねぇよ。",
  ui_story_5080_50800500_33_dialog_content = "嵐、か…",
  ui_story_5080_50800500_34_dialog_content = "お兄ちゃん！ロイ！",
  ui_story_5080_50800500_35_dialog_content = "イブ？どうなってんだ？なんでここに？",
  ui_story_5080_50800500_36_dialog_content = "イブがすごく心配してたから、探しにきたの。",
  ui_story_5080_50800500_37_dialog_content = "お兄ちゃん、一緒に帰ろ！",
  ui_story_5080_50800500_38_dialog_content = "あの時…ロイ、嵐が襲ってきたあの時、俺はイブを放さなかった…\nだが、本当はイブを失うのが怖かっただけだ…",
  ui_story_5080_50800500_39_dialog_content = "結局、イブは自分で自分を救って、俺のことまで救ってくれた…",
  ui_story_5080_50800500_40_dialog_content = "家族を…俺はぜってぇに放す気はねぇ。だが…お前の言う通りかもな。\n皆、俺たちが思ってるよりずっと、強えのかもな…",
  ui_story_5080_50800500_41_dialog_content = "つっても、一緒に連れてくって意味じゃねぇ。\n家で仲間を守るのも手助けだ。",
  ui_story_5080_50800500_42_dialog_content = "とにかく、どう仕事を割り振るかはゆっくり考えるとして…\nおい…な、なんだ、その反応は？どっからハンカチなんか出しやがった？",
  ui_story_5080_50800500_43_dialog_content = "サメ坊、オッさんは本当に感動したよ…\n15年経って、お前も大人になったんだなァ…",
  ui_story_5080_50800500_44_dialog_content = "ふざけんな。俺だってこれでも長年頭やってんだ。\nガキ扱いすんじゃねえ！",
  ui_story_5080_50800500_45_dialog_content = "おっそいなぁ、いったいどこ行ってたんだ？まあ、いいや。\nメシの時間だ、止めないでくれ。ラビ、待ってろ！",
  ui_story_5080_50800500_46_dialog_content = "何があったんだ？2人とも、ずいぶん疲れ切った顔してんじゃないか。",
  ui_story_5080_50800500_47_dialog_content = "何でもねえよ。火山を調べに行っただけさ。",
  ui_story_5080_50800500_48_dialog_content = "へぇ。そういや、アズールが近いうち戻ってくるらしいから、\nまた出ることがあったら、酒を買ってきてくれよ、オッサン。",
  ui_story_5080_50800500_49_dialog_content = "さあ、食べましょ、食べましょう！\nいやいや、あやうく飢え死にするところでしたよ。",
  ui_story_5080_50800500_50_dialog_content = "あれ？ゼタとタイニーは？",
  ui_story_5080_50800500_51_dialog_content = "知らないよ。それより、このトカゲの干物おいしいね――\n悪さでもして、どっかの地下通路から逃げたんじゃない？",
  ui_story_5080_50800500_52_dialog_content = "こんな時間にまだ帰ってきてないか…\nちと心配になってきたねェ。",
  ui_story_5080_50800500_53_dialog_content = "おい、バーバラ！あんたも一緒になって面倒を起こしたんだろ？\nあいつら、どこ行ったんだ？",
  ui_story_5080_50800500_54_dialog_content = "うーん…あの時はドタバタしてたけど、\n確かイェリアについてどっか行ったみたいだったよ。",
  ui_story_5080_50800500_55_dialog_content = "「救世主ゼタの新たな仲間」を見つけるとか何とかって言って…\nまさか、あの女のとこ行ったのかな？",
  ui_story_5080_50800500_56_dialog_content = "イェリアが付いてるのか…\nあの啓光の小娘を探しに行ったってなら、ほっとけばいいさ。",
  ui_story_5080_50800500_57_dialog_content = "ちょっと、みんな！私たちはあのよそ者のこと、なにも知らないんだよ。\nそれに火山のこともあるし、あの子たちだけじゃ危ないよ…",
  ui_story_5080_50800500_58_dialog_content = "さっさと食べて、探しに行ってくるぜ！",
  ui_story_5080_50800500_59_dialog_content = "俺様の運転の方が速い、俺様が行く！",
  ui_story_5080_50800500_60_dialog_content = "私が思うに…",
  ui_story_5080_50800500_61_dialog_content = "あんたの運転じゃ夜道でひっくり返るよ。",
  ui_story_5080_50800500_62_dialog_content = "いやいや、オッさんが行くよ。メシは後でいい。",
  ui_story_5080_50800500_63_dialog_content = "いや、やっぱり…",
  ui_story_5080_50800500_64_dialog_content = "私に任せな！この情熱的な歌声で、道を見失った者の灯台になってやる！",
  ui_story_5080_50800500_65_dialog_content = "ええ～？ただのうるさい騒音でしょ～？",
  ui_story_5080_50800500_66_dialog_content = "なんだと！？",
  ui_story_5080_50800500_67_dialog_content = "静かにしやがれ！",
  ui_story_5080_50800500_68_dialog_content = "まったくバカどもばっかだな。\nお前らはおとなしくメシ食ってろ。俺が行く！",
  ui_story_5080_50800500_69_dialog_content = "さあ、ご飯だよ――あれ？なんで食べないの？",
  ui_story_5080_50800500_70_dialog_content = "失礼だとは重々承知してるけれど…この料理…\n本当に食べられるの…ええ！？",
  ui_story_5080_50800500_71_dialog_content = "わぁ～、このムシ焼き、前のよりパリパリしてるね。",
  ui_story_5080_50800500_72_dialog_content = "炭焼きスネークテールも肉質がよくて、おいしいわ！",
  ui_story_5080_50800500_73_dialog_content = "カレン、食べないの？心配いらないよ。\n僕も前は抵抗あったけど、R・Wの料理、本当においしいから！",
  ui_story_5080_50800500_74_dialog_content = "PlayerName…ごめんなさい。好意は嬉しいけれど…\nその類の串焼きを持って、私に近づかないでくれるかしら？",
  ui_story_5080_50800500_75_dialog_content = "この味…",
  ui_story_5080_50800500_76_dialog_content = "啓光の一級品の缶詰よりもおいしいではないか！",
  ui_story_5080_50800500_77_dialog_content = "啓光は兵士にいったいどんな待遇を与えているの…",
  ui_story_5080_50800500_78_dialog_content = "隊長もR・Wの料理を気に入るとは思いませんでした。",
  ui_story_5080_50800500_79_dialog_content = "食にこだわりは持っていないから。",
  ui_story_5080_50800500_80_dialog_content = "あ～、お腹いっぱい！あたしは修理に戻るから、ジャマしないでね！",
  ui_story_5080_50800500_81_dialog_content = "ゼタと同じ、スナネズミのハチミツ焼きが好きなんて、\nいい味の好みしてるね！",
  ui_story_5080_50800500_82_dialog_content = "啓光の邪悪な幹部兵士でも、正義の美食の味は分かるんだね！",
  ui_story_5080_50800500_83_dialog_content = "邪悪な者がいるとしたら、それはR・Wだ。\nお前たちのような賊と共通点があるとは…受け入れがたい！",
  ui_story_5080_50800500_84_dialog_content = "（ここまできて、また毒舌に戻った…）",
  ui_story_5080_50800500_85_dialog_content = "そうかな？あたしは受け入れられるよ！\n安心していいよ。いつか必ず救世主ゼタがあんたを組織から救い出してあげる！",
  ui_story_5080_50800500_86_dialog_content = "いつでも、あたしの車に乗せてあげるよ。\n席は取っておいてあげるから！",
  ui_story_5080_50800500_87_dialog_content = "どう？カッコいいでしょ？今の台詞、ずっと言ってみたかったんだぁ！",
  ui_story_5080_50800500_88_dialog_content = "R・Wは…啓光から逃げ出した堕落した兵士の集まりにすぎない。",
  ui_story_5080_50800500_89_dialog_content = "自身の出自と栄誉を忘れただけでなく、賊になりさがり、\n銃口をかつての同胞と平民に向けた。",
  ui_story_5080_50800500_90_dialog_content = "君のような…子どもでさえ、それを認めようとしない。",
  ui_story_5080_50800500_91_dialog_content = "あたしは子どもじゃないし、R・Wはそんな集団じゃないもん！\nあんたこそ、間違ってるよ！",
  ui_story_5080_50800500_92_dialog_content = "賊に養われたせいで、物の分別がつかない子どもに育ってしまったか。\nそれも私たち啓光の責任だ…必ずや解決に全力を尽くそう。",
  ui_story_5080_50800500_93_dialog_content = "解決って、<color=#FFB400>執行人</color>たちに逃亡兵を処罰させるのかしら？",
  ui_story_5080_50800500_94_dialog_content = "えっ！？そんなこと、今まで聞いたこともないわ…",
  ui_story_5080_50800500_95_dialog_content = "ここがまだ名もない砂漠で、<color=#FFB400>R・W</color>も存在しなかった頃、\n啓光からしょっちゅう兵士が逃げてきてたの。",
  ui_story_5080_50800500_96_dialog_content = "追跡から逃れるため、そして自由を求めて、\n逃亡兵たちは荒れ果てた人のいない砂漠の奥へ進んでいった。",
  ui_story_5080_50800500_97_dialog_content = "でも結局、啓光の<color=#FFB400>執行人</color>たちも砂漠へ追って入り、\n逃亡兵たちの処刑を完了したのよ。",
  ui_story_5080_50800500_98_dialog_content = "そんな…",
  ui_story_5080_50800500_99_dialog_content = "砂漠をさすらう人々が武器を持つようになったのも、\n人っ子1人いない場所で警戒してるのも全部、啓光のおかげってワケよ～。",
  ui_story_5080_50800500_100_dialog_content = "…すべて過去のことだ。今の大元帥はその手のことは好まない。\n新しい制度の構築を主張しているんだ。",
  ui_story_5080_50800500_101_dialog_content = "今や逃亡兵が処刑されることはない！R・Wの賊どもが自ら武器を捨て、\n啓光に戻りさえすれば、追究する者は誰一人として…",
  ui_story_5080_50800500_102_dialog_content = "暗潮の危機の時、サメヤマは仲間を率いてカナン城に応援に行ったわ…\nでも、なんの報いもなかったのよね。",
  ui_story_5080_50800500_103_dialog_content = "きっと何か誤解があったに違いない。\nきちんと話し合えば、双方の納得する方法が見つかるかもしれない。",
  ui_story_5080_50800500_104_dialog_content = "できることなら…君たちを傷つけたくはない。\nだが、外部の君たちに逃亡の重みなど分からないだろうな。",
  ui_story_5080_50800500_105_dialog_content = "たった1人の決断がそれと関わりのある多くの人を傷つける…\n一族の栄誉も一夜で消え去ってしまうんだ。",
  ui_story_5080_50800500_106_dialog_content = "（おかしい…激しい感情の波を感じる。レイチェルは…何を思い出してるんだ？）",
  ui_story_5080_50800500_107_dialog_content = "そう？啓光で生まれた鳥は、その翼を束縛されるのが定め――\n選択の権利なんてないんでしょ？",
  ui_story_5080_50800500_108_dialog_content = "アタシはR・Wで生まれたわ。うまく融け込んでる方じゃないけど、\nそれでもよく分かってるの。R・Wは自由奔放なおバカさんの集まりよ。",
  ui_story_5080_50800500_109_dialog_content = "アタシもR・Wを離れて、独りで生きたっていいワケだし、\n他のみんなも、それぞれ自分の考えがあるの。",
  ui_story_5080_50800500_110_dialog_content = "啓光に戻って、あなたみたいに啓光に管理されて、おそろいを強制されて、\n個性を奪われていく…あいつらのそんな姿、まったく想像できないわねぇ。",
  ui_story_5080_50800500_111_dialog_content = "そんなことないわ！私は別に悪くないと思うもの！",
  ui_story_5080_50800500_112_dialog_content = "啓光に行ったら、何もできないの？カーレースは？\nカーレースはできる？",
  ui_story_5080_50800500_113_dialog_content = "うーん…シェルターの設備や施設は、\nとても貴重なもので…基本的には…できないわね。",
  ui_story_5080_50800500_114_dialog_content = "わぁ、こわい！行きたくないな。",
  ui_story_5080_50800500_115_dialog_content = "いいえ、そんなにひどい所じゃないわ。\n啓光にもいろいろな試合があるし、輸送兵になればいいじゃない！",
  ui_story_5080_50800500_116_dialog_content = "啓光の理念はすべての光霊を守ることだ。\nそのために、個人の犠牲は避けられない。",
  ui_story_5080_50800500_117_dialog_content = "フフ、猛禽ちゃんらしいわね。あなたみたいな意志の固い軍人さんを育てるのに、\n啓光もかなり力を注いだんでしょうねぇ。",
  ui_story_5080_50800500_118_dialog_content = "当てこすりはよしてもらおうか。私の一族は代々英雄だ。\n私たちの啓光への信念は、君ごときが想像できるものではない。",
  ui_story_5080_50800500_119_dialog_content = "啓明の光のために、犠牲となったのが何だというんだ？\nこの世では栄誉こそが命よりも貴いんだ！",
  ui_story_5080_50800500_120_dialog_content = "でも、みんな犠牲になったら、誰が英雄を覚えててくれるのかしら？",
  ui_story_5080_50800500_121_dialog_content = "猛禽ちゃん、あなたは英雄の一族の出なのよね。\nじゃあ、おじいさんのおじいさんが何をしたか覚えてる？何が好きだったのかしら？",
  ui_story_5080_50800500_122_dialog_content = "きっと小さい頃からずっと、ご先祖様の栄光を聞かされてきたんでしょうねぇ…\nでも、ご先祖様のこと、どれだけ知ってるの？",
  ui_story_5080_50800500_123_dialog_content = "それは…",
  ui_story_5080_50800500_124_dialog_content = "…英雄の軌跡は時と共に埋もれてしまうかもしれない。\nけれど、彼らの功績は永遠に存在し続ける。",
  ui_story_5080_50800500_125_dialog_content = "世界には暗鬼がはびこっているけれど、それでも私たちは生まれ、育ち、命をつないでいる…\nそれは無数の英雄たちが命をかけて守ってきたからよ。",
  ui_story_5080_50800500_126_dialog_content = "たとえ犠牲となったすべての英雄を知ることはできなくても、\n彼らの功績は常に私たちの側にあり、アストラと共にある。",
  ui_story_5080_50800500_127_dialog_content = "その英雄たちが今、いくつもの障害を乗り越え、ゆるぎない決意と共に\n私をこの場に立たせてくれているのよ。私は決して…悔やんだりしないわ！",
  ui_story_5080_50800500_128_dialog_content = "英雄の存在も物語も消えはしないわ。\nその意義は永遠に受け継がれ、様々な形で人々を感化し続けるのよ。",
  ui_story_5080_50800500_129_dialog_content = "カレン…",
  ui_story_5080_50800500_130_dialog_content = "さすが白夜城のお姫様ね。素晴らしいことを言ってくれるわぁ。",
  ui_story_5080_50800500_131_dialog_content = "ホワイトランス、君の…言う通りだ。",
  ui_story_5080_50800500_132_dialog_content = "サメヤマさん、いつまで聞いてるつもりなの？\n入らないの？",
  ui_story_5080_50800500_133_dialog_content = "シーッ！デカい声だすな。もうちょっと…聞いてからだ。",
  ui_story_5080_50800500_134_dialog_content = "そうだ、ホワイトランスの言う通りだ！私にも…かつて正義のため犠牲となった戦友がいた。\n彼女らに助けられ、彼女らを誇りに思っていた。",
  ui_story_5080_50800500_135_dialog_content = "それは誰もが見習うべき価値のあるものだ。",
  ui_story_5080_50800500_136_dialog_content = "そう…きっとそうだ。価値があるんだ…でなければ、私は…",
  ui_story_5080_50800500_137_dialog_content = "隊長？どこへ…",
  ui_story_5080_50800500_138_dialog_content = "1人にしてあげよう。",
  ui_story_5080_50800500_139_dialog_content = "チッ…ゼタ、タイニー、帰るぞ。",
  ui_story_5080_50800500_140_dialog_content = "R・Wの頭か？いつの間に…",
  ui_story_5080_50800500_141_dialog_content = "直った、直ったよ！あたしが直したんだもんね～！\nオティに教えてやろ、オティが直したことないモノ直したんだから！",
  ui_story_5080_50800500_142_dialog_content = "<color=#FFB400>狂戦士</color>、あたし、まだ帰りたくない…うう…",
  ui_story_5080_50800500_143_dialog_content = "…勝手にしろ。お前ももうガキじゃねぇんだ。\nイェリア、うちのガキどもを頼んだぞ。",
  ui_story_5080_50800500_144_dialog_content = "待て！お前…あの暗鬼を知っているな？",
  ui_story_5080_50800500_145_dialog_content = "R・Wは砂漠で長い間暮らしてきた。知っているに違いない。\n奴らの根城を教えてくれないか？",
  ui_story_5080_50800500_146_dialog_content = "秘境を探しに行った啓光の兵士は嫌ってほど見てきたが、\n残念だが、誰1人として戻ってきたヤツはいねぇよ。",
  ui_story_5080_50800500_147_dialog_content = "あんたもそいつらと特に変わったとこがあるワケじゃねえし、\nあきらめるんだな。任務のために犬死することねぇよ。",
  ui_story_5080_50800500_148_dialog_content = "まったく、啓光ってのは何人犬死にさせたら気が済むんだかな。",
  ui_story_5080_50800500_149_dialog_content = "お前などに分かるはずがない！これは軍人の使命だ。\n秘境探索の収穫はお前の思うよりも大きい。犠牲になろうと、それは栄誉なんだ！",
  ui_story_5080_50800500_150_dialog_content = "ま、いいさ。あんたは犠牲、犠牲ってよく言うが、\n「犠牲」の意味、本当に分かってんのか？",
  ui_story_5080_50800500_151_dialog_content = "あんたにとって、「犠牲」ってなんだ？",
  ui_story_5080_50800500_152_dialog_content = "犠牲とは、大義のため、啓明の光のため、\n命を捧げることも恐れない貴い行いだ！",
  ui_story_5080_50800500_153_dialog_content = "命を捧げてでも…任務を達成しようとする覚悟だ！",
  ui_story_5080_50800500_154_dialog_content = "ははっ、はははは――",
  ui_story_5080_50800500_155_dialog_content = "何を笑う？何が言いたい？",
  ui_story_5080_50800500_156_dialog_content = "やっぱりな。あんたもちっとも違わねぇよ。\n帰れよ、お嬢ちゃん。この砂漠は数知れねえ命を呑み込んでんだ。",
  ui_story_5080_50800500_157_dialog_content = "行くぞ、タイニー。",
  ui_story_5080_50800500_158_dialog_content = "違う、私は違う…お前などに分かってたまるか…\n私がどんな「覚悟」でここに来たのか…",
  ui_story_5080_50800500_159_dialog_content = "これ以上、一族の名に泥を塗るわけにはいかない…必ず…\n屈辱を晴らしてやる…",
  ui_story_5080_50800601_1_dialog_content = "バイス、まだ寝ないの？",
  ui_story_5080_50800601_2_dialog_content = "今日の任務報告をまとめないといけないの。\n大丈夫よ…ふわぁ…あなたは先に寝てて。",
  ui_story_5080_50800601_3_dialog_content = "ずいぶん眠そうだよ？",
  ui_story_5080_50800601_4_dialog_content = "先輩と一緒に任務にあたるなんて…\nそう滅多にできる経験じゃないから…",
  ui_story_5080_50800601_5_dialog_content = "もうすぐ…書き終わるわ…",
  ui_story_5080_50800601_6_dialog_content = "ちょっといい？手伝ってあげるよ。",
  ui_story_5080_50800601_7_dialog_content = "ふぁ…そんな、悪いわ…すぅ…",
  ui_story_5080_50800601_8_dialog_content = "あとほんの少しだね。僕が完成させておくよ。",
  ui_story_5080_50800601_9_dialog_content = "ふふ、バイスと長く一緒にいて、\nPlayerNameまで同じ習慣が身に付いたようね。",
  ui_story_5080_50800601_10_dialog_content = "きっとバイスにあれこれ管理されてるせいだよ。いつの間にか習慣づいちゃって…\n何てことないよ。カレンは先に休んでて。",
  ui_story_5080_50800601_11_dialog_content = "少し困っているようだけれど…\nお言葉に甘えて休ませてもらうわ。おやすみなさい。",
  ui_story_5080_50800601_12_dialog_content = "（あとは最後の部分だけだね。すぐに終わる）",
  ui_story_5080_50800601_13_dialog_content = "それから、それから…ここがすっごく面白いんだ！",
  ui_story_5080_50800601_14_dialog_content = "（これは…ゼタの声だ。部屋まで聞こえてくるなんて、\nずいぶん興奮してしゃべってるんだね）",
  ui_story_5080_50800601_15_dialog_content = "救世主ゼタと邪悪な魔女とのカーレースだよ！",
  ui_story_5080_50800601_16_dialog_content = "（誰と話してるんだろう…まとめも書き終わったことだし、\n様子を見に行ってみようかな）",
  ui_story_5080_50800601_17_dialog_content = "あたしの車はサアーッと邪龍の手の中から飛び出すと、\n間髪おかずにキキーッ、バンバン！",
  ui_story_5080_50800601_18_dialog_content = "邪龍にぶつかって行って、いとも簡単にふっ飛ばしたんだ。\nあの魔女でさえ、あたしを崇め讃えたんだから！",
  ui_story_5080_50800601_19_dialog_content = "（これは…大げさにも程があるんじゃ…\n見張りをしてるレイチェルに絡んでるのかな？）",
  ui_story_5080_50800601_20_dialog_content = "それから、それからね、あんたはきっと知らないだろうけど、\n車がゴオオッて音を立てて走ってる時は、砂からよくトカゲがたくさん出てくるんだ。",
  ui_story_5080_50800601_21_dialog_content = "でね、そのトカゲが超～おいしいの！\n今日のご飯に出てきたのよりやわらかいんだよ。",
  ui_story_5080_50800601_22_dialog_content = "あたしたちはみんな、おいしいもの作るのが得意なの。\nあんたも、きっと興味湧くよ。",
  ui_story_5080_50800601_23_dialog_content = "…圧縮食糧を食べてみるか？",
  ui_story_5080_50800601_24_dialog_content = "いらない、見るからにおいしくなさそうだもん。",
  ui_story_5080_50800601_25_dialog_content = "そうだ、まだ言ってなかったね。\nあたしはラリーにも1人で出場するんだ！",
  ui_story_5080_50800601_26_dialog_content = "なのに、あの邪悪な魔女は、\nいつだって伝説の空の末裔をナビゲーターにするんだよ！",
  ui_story_5080_50800601_27_dialog_content = "でも、あたしはずっと1人で偉大な砂漠制覇の旅を続けてるんだ！",
  ui_story_5080_50800601_28_dialog_content = "立派なものだな。見た目からはまったく想像できないが。",
  ui_story_5080_50800601_29_dialog_content = "へっへ～ん、勇者ゼタを讃えたくなってきた？\nどうどう？心揺らいだ？邪悪な組織を抜けて、あたしについて来なよ！",
  ui_story_5080_50800601_30_dialog_content = "初めて来たのに砂漠を駆け抜けられるんだから、\nきっとすごいラリーのナビゲーターになれるよ。",
  ui_story_5080_50800601_31_dialog_content = "あたしと組めば、次の優勝の栄光は、\nきっとあたしとあんたのものだよ！",
  ui_story_5080_50800601_32_dialog_content = "栄光か…私は機械の類の方が得意なのだが、できるだろうか？",
  ui_story_5080_50800601_33_dialog_content = "それなら任せて！あたしが丁寧に最初から教えてあげる。\n伝説のカーレーサーの立派な助手に育ててあげるよ！",
  ui_story_5080_50800601_34_dialog_content = "えっと、なんていったかな…迷子にならないように見るやつ…そう、ガイドブック！\nどうやって作るか、教えてあげるね！",
  ui_story_5080_50800601_35_dialog_content = "面白そうだな。",
  ui_story_5080_50800601_36_dialog_content = "（ええっ…あの2人が仲良く話してる…）",
  ui_story_5080_50800601_37_dialog_content = "でしょでしょ！砂漠には面白いことがいっぱいなんだよ！\n仕方ないから、明日からさっそく教えてあげるね！",
  ui_story_5080_50800601_38_dialog_content = "自分で教えたあんたと一緒なら、きっと…\nきっと、あの魔女に勝てる…",
  ui_story_5080_50800601_39_dialog_content = "もう寝る時間だ。あたしはもう…寝るね…おやすみ…",
  ui_story_5080_50800601_40_dialog_content = "<color=#e8d9bb>ドンッ！</color>",
  ui_story_5080_50800601_41_dialog_content = "…まったく。痛くないんだろうか？",
  ui_story_5080_50800601_42_dialog_content = "ゆっくりと眠るがいい…おやすみ。",
  ui_story_5080_50800601_43_dialog_content = "（すごく冷たいかと思えば、すごく優しい時もある…\nいったいどれが本当の君なの…？）",
  ui_story_5080_50800601_44_dialog_content = "（今こそレイチェルと話すチャンスだね…あれ？これは…まただ。激しい感情の波…）",
  ui_story_5080_50800601_45_option_content = "レイチェルを感知する",
  ui_story_5080_50800601_46_dialog_content = "ターゲットを確保しました。任務完了です。\n隊長、成功しました。",
  ui_story_5080_50800601_47_dialog_content = "よくやった…だが、気を緩めるな。\n遺跡内にはまだ暗鬼が大量に残っている。すぐにここを離れるぞ。",
  ui_story_5080_50800601_48_dialog_content = "ブルーアウル、レッドペレグリン、「データコア」は確保した。\n潜入ルートを引き返す。",
  ui_story_5080_50800601_49_dialog_content = "隊長、重いので私が背負って持って行きましょう。",
  ui_story_5080_50800601_50_dialog_content = "構わない。君は周囲を警戒していてくれ。\nすぐに出口へ向かい、ブルーアウルたちと合流するぞ。",
  ui_story_5080_50800601_51_dialog_content = "隊長、暗鬼たちが騒ぎ出したようです。",
  ui_story_5080_50800601_52_dialog_content = "奴ら、動きを変えました…集まって、何をする気でしょうか？",
  ui_story_5080_50800601_53_dialog_content = "いや、私たちの方へ向かっているようだ。",
  ui_story_5080_50800601_54_dialog_content = "急ぎましょう！",
  ui_story_5080_50800601_55_dialog_content = "ブルーアウル、レッドペレグリン、応答しろ。\n出口の状況は？",
  ui_story_5080_50800601_56_dialog_content = "暗鬼の行動ルートが変わりました。どうやら同じ方向へ向かっているようです…\n大変です！隊長、暗鬼どもがそちらへ向かっています！",
  ui_story_5080_50800601_57_dialog_content = "慌てるな。計画通り、出口を確保しろ。\nすぐにそっちへ行く。",
  ui_story_5080_50800601_58_dialog_content = "ホワイトグース、暗鬼には構うな、急げ！",
  ui_story_5080_50800601_59_dialog_content = "グレーウィング、隊長を援護して先に行ってちょうだい！\n私がヤツらを引き付けるわ！",
  ui_story_5080_50800601_60_dialog_content = "バカなことを言うな。出る時は全員一緒だ！\n隊長、「コア」を急ぎ捨ててください！それを持っていたら、追いつかれます！",
  ui_story_5080_50800601_61_dialog_content = "なぜ、奴らは我々の位置が分かる？\nまるで「コア」の守護者じゃないか…",
  ui_story_5080_50800601_62_dialog_content = "ホワイトグース、しっかりついて来い、勝手な行動はするな。",
  ui_story_5080_50800601_63_dialog_content = "でも、隊長…このままでは、私たちは…",
  ui_story_5080_50800601_64_dialog_content = "<color=#e8d9bb>バンバンバンッ――</color>",
  ui_story_5080_50800601_65_dialog_content = "こちらです、隊長！",
  ui_story_5080_50800601_66_dialog_content = "ブルーアウルとレッドペレグリンよ！",
  ui_story_5080_50800601_67_dialog_content = "バカ者！なぜ命令に背く！？\n君たちが離れてしまったら、出口と通路はどうするんだ？",
  ui_story_5080_50800601_68_dialog_content = "しかし、私たちが来なければ、隊長たちも逃げられません。",
  ui_story_5080_50800601_69_dialog_content = "罵るのも罰するのも後だ、今は隊長を連れてここから出るんだ！",
  ui_story_5080_50800601_70_dialog_content = "バカ者が…",
  ui_story_5080_50800601_71_dialog_content = "どうりで遅かったわけですね。\nこんなに重い物を背負っていたとは。",
  ui_story_5080_50800601_72_dialog_content = "「コア」か…？隊長、これを持ち運ぶのは無理です。\nいっそのこと…",
  ui_story_5080_50800601_73_dialog_content = "ダメだ！任務こそ最優先事項だ。その「データ」は啓光を変えるもの…\n「ホークアイ小隊」が命を惜しむあまり、任務をあきらめることなどあってはならない！",
  ui_story_5080_50800601_74_dialog_content = "それに…任務を放棄すれば、私たちは逃亡兵だ…君たちを…\n君たちの一族にまで恥をかかせるわけにはいかない。",
  ui_story_5080_50800601_75_dialog_content = "出口はすぐそこだ、先に行け！「コア」を啓光に持ち帰るんだ！\n私が殿を務める。",
  ui_story_5080_50800601_76_dialog_content = "いけません！",
  ui_story_5080_50800601_77_dialog_content = "グレーウィング、命令に背くのか？",
  ui_story_5080_50800601_78_dialog_content = "啓光任務法第6章31条によれば、副隊長は投票で全隊員の同意を得て、\n小隊に指令を発出できることになっています。",
  ui_story_5080_50800601_79_dialog_content = "隊長、うちの隊に隊長よりも優れた偵察兵はいません。\n出口を通過したとしても、地上に戻れる保証はないんです。",
  ui_story_5080_50800601_80_dialog_content = "副隊長グレーウィングは、ここに投票の実施を申請する。\n全隊員、ホークアイ小隊長の地上への撤退を援護せよ。",
  ui_story_5080_50800601_81_dialog_content = "賛成！",
  ui_story_5080_50800601_82_dialog_content = "あたしたちも賛成。",
  ui_story_5080_50800601_83_dialog_content = "なぜ…",
  ui_story_5080_50800601_84_dialog_content = "「任務こそ最優先事項だ」…ホークハンター、任務変更です。",
  ui_story_5080_50800601_85_dialog_content = "「コア」を持って啓光に戻ってください。\n家族が待っているのでしょう？",
  ui_story_5080_50800601_86_dialog_content = "必ず追いつきます。心配しないでください。",
  ui_story_5080_50800601_87_dialog_content = "急いでください、隊長！",
  ui_story_5080_50800601_88_dialog_content = "なぜ、こんなことを…",
  ui_story_5080_50800601_89_dialog_content = "待っていてくれ。地上に出たら、すぐに応援を呼ぶから。",
  ui_story_5080_50800601_90_dialog_content = "暗鬼どもが来たぞ。皆、怖いか？",
  ui_story_5080_50800601_91_dialog_content = "隊長はもう無事に出口を過ぎたんだ。\n何を怖がることがある？",
  ui_story_5080_50800601_92_dialog_content = "出口を爆破しろ。奴らをこの先に行かせるな。",
  ui_story_5080_50800601_93_dialog_content = "なにっ！？グレーウィング！やめるんだ――！",
  ui_story_5080_50800601_94_dialog_content = "隊長、あなたはずっと重い責任を背負ってきた…\nすみません…1つ増えてしまいましたね。",
  ui_story_5080_50800601_95_dialog_content = "爆破しろ！！",
  ui_story_5080_50800602_1_dialog_content = "（今のはレイチェル…だから、1人だったの？それで、僕たちと…）",
  ui_story_5080_50800602_2_dialog_content = "（こんなことがあったから、あんなに冷たかったんだね。\n余計な感情を持ちたくなくて…また失うのが怖いのかな？）",
  ui_story_5080_50800602_3_dialog_content = "（また人の辛い過去を見ちゃった…レイチェルと、話すべきかな？）",
  ui_story_5080_50800602_4_dialog_content = "グレーウィング、ホワイトグース、ブルーアウル、レッドペレグリン…私の仲間…\n今も私を見てくれているか？",
  ui_story_5080_50800602_5_dialog_content = "<color=#e8d9bb>ドンッ！</color>",
  ui_story_5080_50800602_6_dialog_content = "誰だ？盗み見とは、姑息な…",
  ui_story_5080_50800602_7_dialog_content = "ニャ～！",
  ui_story_5080_50800602_8_dialog_content = "猫か？",
  ui_story_5080_50800602_9_dialog_content = "…おいで、猫ちゃん。",
  ui_story_5080_50800602_10_dialog_content = "ニボシはいるか？",
  ui_story_5080_50800602_11_dialog_content = "いい子だね～。君のご主人様はクーリエかな？",
  ui_story_5080_50800602_12_dialog_content = "柔らかい毛だ。可愛い子だね～。",
  ui_story_5080_50800602_13_dialog_content = "認識票の音が気になって来たのか？\n君も私の仲間と話がしたいのかな？",
  ui_story_5080_50800602_14_dialog_content = "そのネコちゃんはロイ が拾ってきたの～。\nずっとR・Wのキャンプで飼われてるから、性格も荒っぽいのよぉ。",
  ui_story_5080_50800602_15_dialog_content = "うっ！",
  ui_story_5080_50800602_16_dialog_content = "ミャオー！",
  ui_story_5080_50800602_17_dialog_content = "い、いつからそこに…な、何を見た？",
  ui_story_5080_50800602_18_dialog_content = "気にしないで。アタシはね、この大陸の色々な所を旅して、色々な人を見て来たの。\n他人の趣味をアレコレ言う気はないわぁ。",
  ui_story_5080_50800602_19_dialog_content = "それに、あなたが冷たい人じゃないってことくらい、\nとっくに知ってたしね～。",
  ui_story_5080_50800602_20_dialog_content = "ただ、猛禽ちゃん。お節介のようだけど、\nいつも冷淡な態度をとってると、仲間たちが悲しむわ。",
  ui_story_5080_50800602_21_dialog_content = "…君も似たようなものだろう。\nR・Wの者たちを拒んでいる。",
  ui_story_5080_50800602_22_dialog_content = "拒む？いいえ、アタシはあの騒がしい人たちの周りをうろついてるってだけよぉ。",
  ui_story_5080_50800602_23_dialog_content = "やっぱりねぇ。あなたと<color=#FFB400>あの人</color>はよく似てる。\nどうりで親しみが湧くワケねぇ。",
  ui_story_5080_50800602_24_dialog_content = "「あの人」？",
  ui_story_5080_50800602_25_dialog_content = "R・Wには、啓光の兵士だった人がたくさんいるのよ。\nでも、彼女は特別だった。",
  ui_story_5080_50800602_26_dialog_content = "あなたと同じように特殊任務に当たる精鋭で、\n若くして隊を率いて砂漠に入ったわ。",
  ui_story_5080_50800602_27_dialog_content = "その者は…秘境探索の任務で生き残ったというのか？",
  ui_story_5080_50800602_28_dialog_content = "その者の名を…もしくは隊の名前を覚えているか？\nもしかしたら、私の知る人物かもしれない。",
  ui_story_5080_50800602_29_dialog_content = "名前ねぇ…アタシが会った時には、彼女はもう過去を捨ててたの。\n本名かどうかは分からないわ。",
  ui_story_5080_50800602_30_dialog_content = "ただ、彼女の率いてた小隊の名前は覚えてるわ――「フリーバード」よ。\nこの名前を聞いて、アタシも空を自由に飛び回る鳥に憧れたのよねぇ。",
  ui_story_5080_50800602_31_dialog_content = "「フリーバード」だと！？",
  ui_story_5080_50800602_32_dialog_content = "（それって、レイチェルが探してた小隊じゃ！？）",
  ui_story_5080_50800602_33_dialog_content = "あ、あいつは…砂漠まで逃げてきたのか？\nそして寝返り…R・Wの一員に成り下がったか――",
  ui_story_5080_50800602_34_dialog_content = "君の言ったことは間違っている。似てなどいない！\n奴は恥ずべき逃亡兵だが、私は違う！",
  ui_story_5080_50800602_35_dialog_content = "あら、ごめんなさい、猛禽ちゃん。\n間違ってるのは、おそらくあなたの方よぉ。",
  ui_story_5080_50800602_36_dialog_content = "アタシの知ってるその人は逃亡兵じゃなかったばかりか、\n最後の最後まで、堂々と胸を張って前に立ち、みんなを守ったのよ。",
  ui_story_5080_50800602_37_dialog_content = "あの人の情熱に満ちた心は手に持ったレンチよりもずっと赤かった。\nだから、サメヤマの手に受け継がれた今もずっと、色褪せずにいるのよ。",
  ui_story_5080_50800602_38_dialog_content = "なら、私も…ある話を聞かせてやろう。",
  ui_story_5080_50800602_39_dialog_content = "その隊員だった<color=#FFB400>私のおば</color>から聞いた、\n「フリーバード」に関する、話だ――",
  ui_story_5080_50800602_40_dialog_content = "30年以上前、啓光はある特殊部隊を設立した。\nその名を「フリーバード」といった。",
  ui_story_5080_50800602_41_dialog_content = "隊員はすべて各地から選抜された精鋭で、\n通常なら遂行不可能な任務をもっぱら担当していた。",
  ui_story_5080_50800602_42_dialog_content = "この上なく困難な任務にあたりながら、フリーバードは100%の遂行率を誇り、\n誰もがその隊員になることを栄誉とした。",
  ui_story_5080_50800602_43_dialog_content = "今も隊があったら、あなたはまさにその隊に入るために生まれたようなものねぇ。",
  ui_story_5080_50800602_44_dialog_content = "フリーバードの最後の任務は極めて重大な秘密任務で、\n私のおばと他の隊員たちは命を賭して、任務にあたり…",
  ui_story_5080_50800602_45_dialog_content = "隊員たちは多大な犠牲を払ったというのに、隊長は彼女らを裏切った。\nその者は独断で任務を中止し、<color=#FFB400>逃亡兵</color>となって、生き残った者を連れ、啓光に戻った。",
  ui_story_5080_50800602_46_dialog_content = "いくらもしないうちに、その者は啓光を去り、\n私のおばはそのせいでひどい目にあったんだ！",
  ui_story_5080_50800602_47_dialog_content = "おばは逃亡兵とみなされ、反乱分子の嫌疑をかけられた。\n栄誉を失ったばかりでなく、人々から白い目で見られ、幾度となく侮辱された！",
  ui_story_5080_50800602_48_dialog_content = "一族を巻き込まないようにと、おばは家には戻ろうとせず、\n私の父との関係も悪化し――",
  ui_story_5080_50800602_49_dialog_content = "だが、おばが何をしようと、一族の名声は…",
  ui_story_5080_50800602_50_dialog_content = "（レイチェル…）",
  ui_story_5080_50800602_51_option_content = "レイチェルの記憶を感知する",
  ui_story_5080_50800602_52_dialog_content = "あ、逃亡兵の子どもが来たぞ。",
  ui_story_5080_50800602_53_dialog_content = "まさか、わざとらしく博物館に行く気かな？\nあそこは英雄を記念する所だ、逃亡兵の行く所じゃない！",
  ui_story_5080_50800602_54_dialog_content = "逃亡兵を出した一族じゃ、\nいったいどんな教育を受けたのか怪しいものだな。",
  ui_story_5080_50800602_55_dialog_content = "長官、逃亡兵の一族に背中を預けろっていうんですか？",
  ui_story_5080_50800602_56_dialog_content = "レイチェルのことか？見たところ、か弱そうな娘だ。\n精神的にもそう強くはないだろう…",
  ui_story_5080_50800602_57_dialog_content = "ダメだ、ダメだ。あいつはダメだ…",
  ui_story_5080_50800602_58_dialog_content = "違う、私は違う…絶対に証明してみせる！",
  ui_story_5080_50800602_59_dialog_content = "そうよ、レイチェルはすごい子よ。\n誰にも証明する必要なんてないの。もう十分立派な戦士だわ。",
  ui_story_5080_50800602_60_dialog_content = "おばさん…私は…今のはそういう意味で言ったわけじゃないんです…\nおばさんとは違うって意味じゃありません…",
  ui_story_5080_50800602_61_dialog_content = "いいのよ、レイチェル。他人の言う事なんて気にしてないから。\nあなたも何を言われても負けちゃダメよ。",
  ui_story_5080_50800602_62_dialog_content = "今みたいな威勢の良さで、皆にあなたはおばさんみたいに\n役立たずじゃないって言えばいいの。",
  ui_story_5080_50800602_63_dialog_content = "おばさん…ごめんなさい…",
  ui_story_5080_50800602_64_dialog_content = "レイチェル、背筋を伸ばしなさい。私を見て。\nあなたを責めてるわけじゃないわ。",
  ui_story_5080_50800602_65_dialog_content = "おばさんがいけないの。レイチェルにまで迷惑かけて…\nこれから先、あなたはきっと、もっと多くの人から非難されるわ。",
  ui_story_5080_50800602_66_dialog_content = "でも、負けちゃダメよ。屈服しちゃダメ。周りの言葉に納得しちゃダメ。\n大きな声で反論するのよ、今みたいにね。",
  ui_story_5080_50800602_67_dialog_content = "おばさん、知ってるんだから。\nレイチェルは私よりずっと強いって。",
  ui_story_5080_50800602_68_dialog_content = "自分を信じるのよ、レイチェル。どんな選択をしようとも、最後まで貫きなさい。\n他人の言う事に従ってちゃいけないわ！",
  ui_story_5080_50800602_69_dialog_content = "おばは家を離れ、1人で暮らしていたが、私を娘のように可愛がってくれた…\n私は許さない…あいつがおばを苦しめたんだ。",
  ui_story_5080_50800602_70_dialog_content = "だから、私は決めたんだ、必ず限界を越え、私たちを縛る枷を破ると…\n悲劇は二度と起こさない、と。",
  ui_story_5080_50800602_71_dialog_content = "どうせ、あいつは逃亡兵の一族なんだ。\nいつか必ずダメになるさ。",
  ui_story_5080_50800602_72_dialog_content = "そうか、カッコいいと思うけどな。\n彼女のことは皆意志が強いって言ってる。陰口は止した方がいいよ。",
  ui_story_5080_50800602_73_dialog_content = "ヒイロ、今期の後輩に満足のいく者はいるか？",
  ui_story_5080_50800602_74_dialog_content = "皆訓練についてこられません。\nこの程度では話になりません。",
  ui_story_5080_50800602_75_dialog_content = "厳しすぎるのもよくないぞ…そうだ。<color=#FFB400>あの者</color>はどうだ？\n<color=#FFB400>あの者</color>まで話にならんことはないだろう？",
  ui_story_5080_50800602_76_dialog_content = "<color=#FFB400>あの者</color>は…自分に厳しすぎます。\n同期よりも身体が弱く、無理はいつまでも続けられるわけではありません。",
  ui_story_5080_50800602_77_dialog_content = "取り返しのつかないケガをする前に、振り落としたいと思っているのですが、\nこれがまた粘り強く、いくら訓練強度を上げても付いてくるのです。",
  ui_story_5080_50800602_78_dialog_content = "見たところ、肉体的条件に恵まれているわけではありません。\nですが、いつも最後まで私についてきているのは、彼女1人なのです。",
  ui_story_5080_50800602_79_dialog_content = "校内で良くない噂が広まっていましたが、\n知らず知らず皆、あの者に感心し始めています。",
  ui_story_5080_50800602_80_dialog_content = "彼女を讃えるべきなのか、私自身も分かりかねます。",
  ui_story_5080_50800602_81_dialog_content = "倒されても立ち上がり、再び倒されてもまた立ち上がる。\nそうして立ち上がり続ける兵士がいたなら…ヒイロ、私はそやつは英雄だと思うぞ。",
  ui_story_5080_50800602_82_dialog_content = "その者の意志と精神を認めてやれ。気に掛けてやるがいい。\nお前も否定できまい――",
  ui_story_5080_50800602_83_dialog_content = "その者を振り落とすことはできない。",
  ui_story_5080_50800602_84_dialog_content = "レイチェル！第三軍団のヒイロ軍団長がお前の優秀な成績と、\n群を抜く精神力を認め、第三軍団への入団をお認めになった。",
  ui_story_5080_50800602_85_dialog_content = "（こうやってレイチェルは…少しずつ…誰もが認める精鋭部隊の隊長になったんだね）",
  ui_story_5080_50800602_86_dialog_content = "そう…猛禽になるのに、あなたもずいぶん苦労したのね。",
  ui_story_5080_50800602_87_dialog_content = "フフ。ま、「逃亡」したってことにしときましょ。\n何しろ、あの人はほんの少しの言葉だけを残して、消えちゃったんだから。",
  ui_story_5080_50800602_88_dialog_content = "ずる賢い人だったし、無事に逃げられたならいいけど…\nそうすれば、答えを教えてもらえるしね～。",
  ui_story_5080_50800602_89_dialog_content = "答え？",
  ui_story_5080_50800602_90_dialog_content = "この砂漠、すごく広いと思わな～い？見張ろうにも、こんな果てしない砂漠の夜に、\nどこをどうやって見張るっていうの？",
  ui_story_5080_50800602_91_dialog_content = "ここはね、広すぎるの。だから、とても虚しい。",
  ui_story_5080_50800602_92_dialog_content = "虚しい、か…それが奴らを受け入れない理由か？",
  ui_story_5080_50800602_93_dialog_content = "色々な所を旅したことがあると言ったな。結局、理想の地は見つからなかったのだろう？\nだから、ここへ戻って来た…",
  ui_story_5080_50800602_94_dialog_content = "その通りよ。アタシは幼い時から、この砂漠には妙な疎外感を持ってたの。\nあの騒がしい人たちのことが理解できないでいたのよぉ。",
  ui_story_5080_50800602_95_dialog_content = "毎日騒がしく過ごしてるけど、\n本気で生きる意味を探し求めたことはあるのかしらね。",
  ui_story_5080_50800602_96_dialog_content = "あんなふうに騒ぐだけで、人生を無駄にして、\nある時突然そのことに気づいたら…って考えると、空恐ろしいわぁ。",
  ui_story_5080_50800602_97_dialog_content = "人は誰でも最後は1人。出会いには別れがつきものよ。いくらにぎやかに過ごしてても、\nいつか必ず虚しさに襲われ、自分に問いかける時が来るの。これってスゴク恐ろしいコトじゃない？",
  ui_story_5080_50800602_98_dialog_content = "だから、砂漠をさまよっているのか。\nここは君の家でも、旅先でもないんだな。",
  ui_story_5080_50800602_99_dialog_content = "君もこの砂漠をさまよう孤独な鳥にすぎない。",
  ui_story_5080_50800602_100_dialog_content = "あなた、他人の気持ちをよく分かってるじゃな～い。\nいい隊長さんだって、褒められたことない？",
  ui_story_5080_50800602_101_dialog_content = "（バイスがまだ起きてたらよかったのにな。\n明日こっそり教えてあげよう）",
  ui_story_5080_50800602_102_dialog_content = "あの人が生きてた頃、アタシはまだ子どもだったのよ。\n色々な知識と世界がどれだけ広いのかを教えてくれたわ。",
  ui_story_5080_50800602_103_dialog_content = "あの人がいたから、アタシは自由な暮らしを追い求めて、\n自分の生きている意味を探そうって、果てしなく広がる未来に飛び出せたのよ。",
  ui_story_5080_50800602_104_dialog_content = "それなのに、あっけなく死んじゃったわ。\nあんなに大きかった後ろ姿も、だんだんと記憶が薄れていくの。",
  ui_story_5080_50800602_105_dialog_content = "両親からも、R・Wからも離れたアタシは、いったい何を得たのかしらねぇ。\nこの世界にアタシの居場所はない。",
  ui_story_5080_50800602_106_dialog_content = "はぁ。人の気も知らないで、おバカさんたちは相変わらず能天気にやってるのに、\nアタシは果てしない虚無の中…イヤになっちゃうわよねぇ。",
  ui_story_5080_50800602_107_dialog_content = "なぜ、私にそんな話をする？",
  ui_story_5080_50800602_108_dialog_content = "あなた以外に、話せる人はいないでしょう。",
  ui_story_5080_50800602_109_dialog_content = "でも、それもそうねぇ。アタシったら、どうしてあなたにこんな話をしてるのかしら？\nあなたがあの人に似てるから？それとも…私に似てるから？",
  ui_story_5080_50800602_110_dialog_content = "猛禽ちゃん、あなたも…間違って、この砂漠に迷い込んだ鳥みたいなモノでしょ？",
  ui_story_5080_50800602_111_dialog_content = "あなたが逃亡兵を捕まえに来たんだったらいいのにねぇ。\n姿を消したあの人をつまみ出して、思いっきり懲らしめてくれたらいいのに。",
  ui_story_5080_50800602_112_dialog_content = "彼女がいなかったら、アタシもこんなに悩まずに済んだかもしれない。彼女のおかげで、\n品のないおバカさんの集まりだったR・Wが能天気なおバカさんの集まりに変わったのに…",
  ui_story_5080_50800602_113_dialog_content = "どうしてアタシ1人、取り残されてるのかしら？",
  ui_story_5080_50800602_114_dialog_content = "エルダー、君は…",
  ui_story_5080_50800602_115_dialog_content = "ゼタは連れて行くわねぇ。あなたも降りてきて、休むといいわ。",
  ui_story_5080_50800602_116_dialog_content = "何もかも虚しいと言いながら…\n君はその子を抱っこして寝床まで運び、気に掛けている。",
  ui_story_5080_50800602_117_dialog_content = "仕方ないじゃな～い。\nこの子たちのイタズラ書きは存在感ありすぎなんだもの。",
  ui_story_5080_50800602_118_dialog_content = "夜の砂漠は冷えるわ。\n見張りは言霊にさせるから、安心して休むといいわぁ。",
  ui_story_5080_50800602_119_dialog_content = "それに…あなたがさっさと寝なきゃ、\n下にいる空の末裔くんがアイスキャンディーになっちゃうわよ～。",
  ui_story_5080_50800602_120_dialog_content = "（あ、知ってたの！？）",
  ui_story_5080_50800602_121_dialog_content = "（急いで…うわっ！）",
  ui_story_5080_50800602_122_dialog_content = "どうしてこんなとこにバケツがあるの！？",
  ui_story_5080_50800701_1_dialog_content = "起きるんだ。任務はまだ終わっていない。",
  ui_story_5080_50800701_2_dialog_content = "隊長…おはようございます。",
  ui_story_5080_50800701_3_dialog_content = "…おはよう。顔を洗って目を覚ましてこい！",
  ui_story_5080_50800701_4_dialog_content = "了解です！",
  ui_story_5080_50800701_5_dialog_content = "今日も偵察任務を続行しなければならない。\n全員起きろ、10分後に集合だ！",
  ui_story_5080_50800701_6_dialog_content = "アタシも入れてちょうだい。",
  ui_story_5080_50800701_7_dialog_content = "あの特殊な暗鬼を探すなら、アタシも情報を持ってるのよぉ。",
  ui_story_5080_50800701_8_dialog_content = "なぜだ？君にはまだ好奇心が残っているのか？",
  ui_story_5080_50800701_9_dialog_content = "すべては虚無に帰るとしても、今回は結末を知りたいのよ。",
  ui_story_5080_50800701_10_dialog_content = "猛禽ちゃん、空の末裔くん。まさか、断るつもり～？",
  ui_story_5080_50800701_11_dialog_content = "それに、「あの人」の死に場所が見つかるかもしれないし。",
  ui_story_5080_50800701_12_dialog_content = "…身支度はできたか？出発するぞ！",
  ui_story_5080_50800701_13_dialog_content = "ゼタがまだ、ぐっすり眠ってるんだけど…",
  ui_story_5080_50800701_14_dialog_content = "眠らせてやれ。私たちだけで行く。",
  ui_story_5080_50800701_15_dialog_content = "R・Wのエルダー、これが今回の調査用の地図だ。",
  ui_story_5080_50800701_16_dialog_content = "昨日の状況からすると、\n奴らの洞窟はおそらく近くの火山の地脈に通じている。",
  ui_story_5080_50800701_17_dialog_content = "そうした地脈には印をつけておいた。\n間違いがないか、見てくれないか？",
  ui_story_5080_50800701_18_dialog_content = "猛禽ちゃんの努力がムダになっちゃったみたいね～。\nこの地図に記されている中に、正しい答えはないわぁ。",
  ui_story_5080_50800701_19_dialog_content = "砂漠の地中には、眠っている火山があるの。\nよそから来た人は知らない情報よ～。",
  ui_story_5080_50800701_20_dialog_content = "眠っている火山？",
  ui_story_5080_50800701_21_dialog_content = "あ、今はこの表現もおかしいわねぇ。\nというのも、まさに昨日その火山が目を覚ましたのを確認してきたの。",
  ui_story_5080_50800701_22_dialog_content = "あの特殊な暗鬼は地脈に沿って砂漠のあちこちに出現してるのは確かだけど、\n根城はおそらくあそこしかないと思うわ。",
  ui_story_5080_50800701_23_dialog_content = "だって、そこ以外の場所は、\nほとんどR・Wが足を踏み入れたことのある場所だからね～。",
  ui_story_5080_50800701_24_dialog_content = "どういう意味だ？",
  ui_story_5080_50800701_25_dialog_content = "地下火山よ。暗潮の危機に1度噴火したっきりだけどね。\n当時たくさんの暗鬼が噴火の合間から湧いて出て、R・Wを襲ったの。",
  ui_story_5080_50800701_26_dialog_content = "当時のR・Wの頭も、ゼタの両親も、その時に亡くなったのよ。",
  ui_story_5080_50800701_27_dialog_content = "それから何年もの間、R・Wは砂漠のあちこちにキャンプを張って本拠地としてきたけど、\n意識してか無意識にか、あそこをずっと避けてきた。",
  ui_story_5080_50800701_28_dialog_content = "でも、暗鬼がそこから現れたって分かってるのに、\nどうして長い間調査しに行こうとしなかったの？",
  ui_story_5080_50800701_29_dialog_content = "調査したわよぉ。ただ、収穫ナシだったけどね。",
  ui_story_5080_50800701_30_dialog_content = "あの火山は噴火後数年もすると、完全に休眠して、\n中には普通の暗鬼が巣くうようになった。",
  ui_story_5080_50800701_31_dialog_content = "R・Wが何度か出向いて「掃除」したけど、大して効果もないし、\nあの暗鬼も見つからなかったのよ。",
  ui_story_5080_50800701_32_dialog_content = "だから、あの暗鬼はおそらくたった1匹しかいなくて、\n先代の頭たちと道連れになったんだって考えてたのよ。",
  ui_story_5080_50800701_33_dialog_content = "「掃除」した後は、普通の暗鬼も少なくなってたしね。",
  ui_story_5080_50800701_34_dialog_content = "人ってツラい記憶を避けようとするでしょ。\nそうやって、だんだんと誰もあそこには行かなくなったの。",
  ui_story_5080_50800701_35_dialog_content = "だとしても、昔は家だった所でしょ…\nどうして、放っておけるの…",
  ui_story_5080_50800701_36_dialog_content = "PlayerName、落ち込むことないわ！私たちは天空ノ谷をきれいに建て直したじゃない。\nあとは一族の人を見つけるだけよ。",
  ui_story_5080_50800701_37_dialog_content = "フフ、バイスちゃんの言う通りよ。\n空の末裔の中にも、旅烏になって自由を楽しんでる人がいるかもしれないわぁ。",
  ui_story_5080_50800701_38_dialog_content = "いつの日か、その旅烏も…故郷の木に止まりにくるかもねぇ。",
  ui_story_5080_50800701_39_dialog_content = "…",
  ui_story_5080_50800701_40_dialog_content = "ま、とにかく、アタシくらいかしらね。\n今も時々あそこに様子を見に行ってるのは。",
  ui_story_5080_50800701_41_dialog_content = "何も収穫はなかったけど、何度も地下を探索してるから、\n近道は知ってるわよぉ。",
  ui_story_5080_50800701_42_dialog_content = "地図だ。頼んだぞ、R・Wのクーリエのエルダーよ。",
  ui_story_5080_50800701_43_dialog_content = "さ、行きましょ。",
  ui_story_5080_50800701_44_dialog_content = "じ、地震よ！",
  ui_story_5080_50800701_45_dialog_content = "見て、噴火したわ！",
  ui_story_5080_50800701_46_dialog_content = "そんな驚くことじゃないわよ。とにかく急ぎましょ。",
  ui_story_5080_50800701_47_dialog_content = "R・W砂漠の地脈は安定してないから、よく火山が噴火するの。\nでも、あれはアタシたちの探してる火山じゃないわ。",
  ui_story_5080_50800701_48_dialog_content = "目的の火山はもう長いコト休眠してて、\n火口の縁まで行って見たけど、目を覚ました痕跡はなかったのよね。",
  ui_story_5080_50800701_49_dialog_content = "でも…今また轟音を発し始めてる。中にいる暗鬼の声でしょうね。",
  ui_story_5080_50800701_50_dialog_content = "あの暗鬼が火山の地脈に戻ったせいで、\nきっと何かしらの異常が起こってるんだと思うわ。",
  ui_story_5080_50800701_51_dialog_content = "急ごう！",
  ui_story_5080_50800701_52_dialog_content = "ここよ。ここから下へ行けば、地脈の奥よ。\n火口の洞窟に通じてる。",
  ui_story_5080_50800701_53_dialog_content = "思った通り…マグマの燃えた痕がたくさんあるわ。",
  ui_story_5080_50800701_54_dialog_content = "この痕跡は暗鬼の残したものなの？\nそれともマグマが地脈を通り過ぎた痕なのかしら？",
  ui_story_5080_50800701_55_dialog_content = "分からないわ…昨日は慌ただしくて、奥まで行ってないの。",
  ui_story_5080_50800701_56_dialog_content = "確かなのは、火山が目を覚まし始めてるってコトね。",
  ui_story_5080_50800701_57_dialog_content = "待って。全員下りたら危ないよ。",
  ui_story_5080_50800701_58_dialog_content = "カレン、ここで車と入口を見ててくれる？",
  ui_story_5080_50800701_59_dialog_content = "分かったわ。任せて。",
  ui_story_5080_50800701_60_dialog_content = "地面がかすかに揺れている。\nこの下に大きな力が存在しているようだ。",
  ui_story_5080_50800701_61_dialog_content = "死火山ではなさそうだな。",
  ui_story_5080_50800701_62_dialog_content = "この不規則な足跡は…暗鬼が残したものでしょうか？",
  ui_story_5080_50800701_63_dialog_content = "奥へと続いている…足跡だ。急ぐぞ。",
  ui_story_5080_50800701_64_dialog_content = "待って、レイチェル！",
  ui_story_5080_50800701_65_dialog_content = "こ、これは…！？",
  ui_story_5080_50800701_66_dialog_content = "掘った痕が新しいな…ここは掘られたばかりの地下回廊だ。",
  ui_story_5080_50800701_67_dialog_content = "見て！火口よ！",
  ui_story_5080_50800701_68_dialog_content = "できたばかりの回廊が、どうしてこんなに大きいんだろう？\nしかも、火口にここまで近いなんて…",
  ui_story_5080_50800701_69_dialog_content = "空の末裔くん、そっちの壁を見て。",
  ui_story_5080_50800701_70_dialog_content = "爪痕？しかも深くて、ものすごく大きい…",
  ui_story_5080_50800701_71_dialog_content = "間違いないわ、邪龍が残した痕よ。",
  ui_story_5080_50800701_72_dialog_content = "この場所はかつて邪龍の巣穴か、狩場だったみたいね。",
  ui_story_5080_50800701_73_dialog_content = "どうりで、あのアズールちゃんもずっと見つけられなかったワケねぇ。",
  ui_story_5080_50800701_74_dialog_content = "巣穴は1つじゃなくて、\nしかもR・Wの皆が行きたがらない所に隠れてたんだね…",
  ui_story_5080_50800701_75_dialog_content = "イェリア…どうしてアズールが邪龍を探してたことを知ってるの？",
  ui_story_5080_50800701_76_dialog_content = "フフ。言ったじゃな～い。\nここもアタシの管轄内だって。",
  ui_story_5080_50800701_77_dialog_content = "（それは違うよね…本当はずっと…\nR・Wの皆のこと気に掛けて、見てきたからだよね）",
  ui_story_5080_50800701_78_dialog_content = "あら、そういえば、邪龍っていつも噴火がらみで出てきたわね。",
  ui_story_5080_50800701_79_dialog_content = "もしかして、噴火から逃げるために仕方なく、\n巣穴を離れて表に出てきたのかしら？",
  ui_story_5080_50800701_80_dialog_content = "マグマを恐れているのなら、なぜ巣穴を火山近くに造るんだ？",
  ui_story_5080_50800701_81_dialog_content = "理に適っていない。",
  ui_story_5080_50800701_82_dialog_content = "ある人物を避けるためでしょ。",
  ui_story_5080_50800701_83_dialog_content = "当時あの人は砂漠じゅうを回って、脅威となる目標を見つけては排除してたの。\n邪龍も彼女を避けるために、火山の近くに身を隠すしか…",
  ui_story_5080_50800701_84_dialog_content = "また地震だ！",
  ui_story_5080_50800701_85_dialog_content = "おかしいわ…震源は真下みたい！\nということは…もしかして、もうすぐ噴火するの！？",
  ui_story_5080_50800701_86_dialog_content = "隊長、不可抗力の事態です。\nまずはここを離れましょう！",
  ui_story_5080_50800701_87_dialog_content = "…君たちは先に戻れ。私は残って任務を続行する。",
  ui_story_5080_50800701_88_dialog_content = "しかし、隊長…危険すぎます。",
  ui_story_5080_50800701_89_dialog_content = "任務こそ最優先事項だ。",
  ui_story_5080_50800701_90_dialog_content = "狩りはいつでも命がけってコトね。\nまったく、猛禽ちゃんは困るわねぇ。",
  ui_story_5080_50800701_91_dialog_content = "けど、猛禽ちゃん。教えてちょうだい。そんな実のないモノに命を賭けるなんて、\nあなた、現実が見えてないの？それとも情熱を持て余してるのかしらぁ？",
  ui_story_5080_50800701_92_dialog_content = "レイチェル、こんな時に命を賭ける必要はないよ。\n今度また来ればいい。",
  ui_story_5080_50800701_93_dialog_content = "ダメだ。火山が噴火すれば、ここはすべて埋まり、\nマグマが冷え固まった時には、何もかも…",
  ui_story_5080_50800701_94_dialog_content = "君たちは戻れ！",
  ui_story_5080_50800701_95_dialog_content = "戻る時は全員一緒です！",
  ui_story_5080_50800701_96_dialog_content = "ヤングドラゴン2号…なぜ、またそんなことを…",
  ui_story_5080_50800701_97_dialog_content = "また？",
  ui_story_5080_50800701_98_dialog_content = "（あの時だ…レイチェルの仲間の言った言葉だね…）",
  ui_story_5080_50800701_99_dialog_content = "私は…私は逃げるわけにはいかない…",
  ui_story_5080_50800701_100_dialog_content = "気を付けて！暗鬼が近づいてくるのを感知したよ！",
  ui_story_5080_50800701_101_dialog_content = "逃げる逃げないは後にして、皆、戦闘準備だよ！",
  ui_story_5080_50800702_1_dialog_content = "お、終わった…",
  ui_story_5080_50800702_2_dialog_content = "震動もなくなったわ…山も落ち着いたの？",
  ui_story_5080_50800702_3_dialog_content = "どうして暗鬼がこんなに強くなってるのかしら？\nここは何度も調査に来てるけど、こんな変わったヤツらは見たことないわ。",
  ui_story_5080_50800702_4_dialog_content = "構造に…異変があったのかしら？",
  ui_story_5080_50800702_5_dialog_content = "また始まった！",
  ui_story_5080_50800702_6_dialog_content = "ここは危険すぎます。隊長、とにかくまずはさっきの通路まで戻りませんか？",
  ui_story_5080_50800702_7_dialog_content = "ここは火口に近すぎるよ。",
  ui_story_5080_50800702_8_dialog_content = "ううむ…ヤングドラゴン2号の言うように、別の道を――",
  ui_story_5080_50800702_9_dialog_content = "何事だ？この揺れは火山性のものではないぞ。",
  ui_story_5080_50800702_10_dialog_content = "気を付けて！通路が崩れるわ――",
  ui_story_5080_50800702_11_dialog_content = "R・Wって、いつもにぎやかよね。",
  ui_story_5080_50800702_12_dialog_content = "お～い、イェリア――！こっちに来て一緒に車を組み立てようよ。\n今日はぜったい完成するよ！",
  ui_story_5080_50800702_13_dialog_content = "そうそう、そのあと一緒にトカゲを捕まえに行くの。",
  ui_story_5080_50800702_14_dialog_content = "アタシはよしとくわ。",
  ui_story_5080_50800702_15_dialog_content = "な～んだ、イェリアはまた一緒に遊ばないのか。",
  ui_story_5080_50800702_16_dialog_content = "明日また来るね～！",
  ui_story_5080_50800702_17_dialog_content = "いくら断ってもムダだった。\nでもアタシは、あの手の人たちは苦手だった。",
  ui_story_5080_50800702_18_dialog_content = "み～つけた。",
  ui_story_5080_50800702_19_dialog_content = "かくれんぼしてた覚えはないけど。",
  ui_story_5080_50800702_20_dialog_content = "だったらイェリアは私を待っててくれたのね？",
  ui_story_5080_50800702_21_dialog_content = "図星ね、顔が赤くなってるわよ～。",
  ui_story_5080_50800702_22_dialog_content = "そうじゃないわよ。",
  ui_story_5080_50800702_23_dialog_content = "これ、啓光の教材よ。苦労して手に入れたんだから。",
  ui_story_5080_50800702_24_dialog_content = "また砂漠を出たの？",
  ui_story_5080_50800702_25_dialog_content = "ええ。影ノ街に行って、闇市の商人とちょっと商売をね。",
  ui_story_5080_50800702_26_dialog_content = "知ってる？影ノ街の郊外にカッコいい地下遺跡があるの。\n中は全部古代建築なんだけど、材料はどれもこれも私たちの常識をはるかに超えてるのよ。",
  ui_story_5080_50800702_27_dialog_content = "今は回廊迷宮のように改造されて、闇組織と商人がはびこり――",
  ui_story_5080_50800702_28_dialog_content = "猫も杓子も金目の物を探し回ってるけど、\nあの遺跡自体が最も価値のあるモノだって知らないのよね。",
  ui_story_5080_50800702_29_dialog_content = "遺跡にどんな価値があるの？\n古くなった廃墟を残しておいて、何の役に立つっていうの？",
  ui_story_5080_50800702_30_dialog_content = "もちろん、価値があるに決まってるじゃない！",
  ui_story_5080_50800702_31_dialog_content = "建物はどんな材料で造られてるのか？いつどんな状況で建てられたのか？\nどんな人物が創り出したのか？",
  ui_story_5080_50800702_32_dialog_content = "遺跡内に科学技術製品は残っているか？\nその技術が今の私たちに何をもたらすか？",
  ui_story_5080_50800702_33_dialog_content = "その背景にある文明はどんなもので、人々はどんな世界を創り、\nまた、なぜ消えてしまったのか――",
  ui_story_5080_50800702_34_dialog_content = "その答えは全部、遺跡が「教えてくれる」のよ。",
  ui_story_5080_50800702_35_dialog_content = "回廊が答えを教えてくれるっていうの？",
  ui_story_5080_50800702_36_dialog_content = "そうよ。時間をかければ、遺跡から知ることができるの。",
  ui_story_5080_50800702_37_dialog_content = "前に…話してくれた時みたいに？",
  ui_story_5080_50800702_38_dialog_content = "いつのこと？",
  ui_story_5080_50800702_39_dialog_content = "北境近くの秘境で偵察をした時のコトよ。",
  ui_story_5080_50800702_40_dialog_content = "あ、凧揚げを教えてあげた時のことね。",
  ui_story_5080_50800702_41_dialog_content = "その通りよ。あの遺跡は「飛行機」について教えてくれたの。\n調査の後、啓光は研究を始めたわ。",
  ui_story_5080_50800702_42_dialog_content = "ただ、私が教えてあげられるのは凧揚げだけだけど。",
  ui_story_5080_50800702_43_dialog_content = "回廊には何があるの？",
  ui_story_5080_50800702_44_dialog_content = "あまりにも多すぎて、今はまだ研究できないわ。",
  ui_story_5080_50800702_45_dialog_content = "チャンスがあれば、また行って色々探してみるわ。",
  ui_story_5080_50800702_46_dialog_content = "イェリアにも何か持ってきてあげられるかも。",
  ui_story_5080_50800702_47_dialog_content = "…1つ聞いてもいい？",
  ui_story_5080_50800702_48_dialog_content = "え？いいわよ。",
  ui_story_5080_50800702_49_dialog_content = "アストラについて、もう十分知ってるでしょ？\nなのに、どうしてまだ、そんな情熱が有り余ってるの？",
  ui_story_5080_50800702_50_dialog_content = "この世界は、もうまったく知らない世界じゃない。\nだったら、退屈で仕方ないんじゃ…",
  ui_story_5080_50800702_51_dialog_content = "イェリア、私が持ってきた本は全部読んだ？",
  ui_story_5080_50800702_52_dialog_content = "ええ。5683冊、1冊残らず読んだわよ。",
  ui_story_5080_50800702_53_dialog_content = "でも残念なことに、\nその5683冊の本じゃアストラは語り尽くせないの。",
  ui_story_5080_50800702_54_dialog_content = "それに、このアストラの他にも、まだ大陸があるんじゃないかしら？\nそこはどんな所で、どんな人たちが住んでるのかしら？",
  ui_story_5080_50800702_55_dialog_content = "まったく知らないから、ずっと興味があるのよ。",
  ui_story_5080_50800702_56_dialog_content = "アストラのほとんどは行ったことがある。\nでも、そのすべての道や場所を覚えてるわけじゃない。",
  ui_story_5080_50800702_57_dialog_content = "イェリア、自分ではきっとまだ気づいてないだけよ。\nあなたもこの世界を知りたいって思ってるはず。",
  ui_story_5080_50800702_58_dialog_content = "あなたは、私みたいな目の前を一瞬通り過ぎた「旅烏」とは違うのよ。\nきっと詳しく、もっと深く、この世界を知れるはずよ。",
  ui_story_5080_50800702_59_dialog_content = "頭をなでないでくれる…？",
  ui_story_5080_50800702_60_dialog_content = "分かったわ。じゃ、質問に答えてあげる。答えはね――\n私はあまりにもたくさんの風景を見過ぎて、思い出が少なくなっちゃったの。",
  ui_story_5080_50800702_61_dialog_content = "夜、この果てしない砂漠を前にしてると、\nこの心に残った美しさがあまりにも少ないことに気づくの。",
  ui_story_5080_50800702_62_dialog_content = "それは…啓光の人があなたにばかり任務をさせるからでしょ？",
  ui_story_5080_50800702_63_dialog_content = "そうかもね、ハハハ。",
  ui_story_5080_50800702_64_dialog_content = "イェリア、あなたは賢い子よ。知りたいことが多すぎて、\n答えを見つけられない自分を不安に思うかもしれないわ。",
  ui_story_5080_50800702_65_dialog_content = "でも、それも仕方ないのよね。\nだって、イェリアはまだ子どもだもの。",
  ui_story_5080_50800702_66_dialog_content = "頑張って大人になりなさい、イェリア。\n未来のあなたはきっと、すべての謎をきちんと探れる人になってるわ。",
  ui_story_5080_50800702_67_dialog_content = "私みたいに生き急いで、やみくもに旅するだけで終わっちゃダメよ。",
  ui_story_5080_50800702_68_dialog_content = "あなたならきっと、「人生」の旅に意味を見つけ、\nそして数えきれない思い出を作れるわ。",
  ui_story_5080_50800702_69_dialog_content = "自由に生きなさい。翼を思う存分に広げるの。そうすれば、きっと…\n今悩んでる問いの答えが見つかるはずよ。",
  ui_story_5080_50800702_70_dialog_content = "アタシには分からなかった。",
  ui_story_5080_50800702_71_dialog_content = "<color=#FFB400>彼女</color>はアタシと同じはず。\n選択肢はなく、合わない環境に生まれてしまった。",
  ui_story_5080_50800702_72_dialog_content = "砂漠を離れて、世界のあちこちに足跡を残したい――アタシはそう思ってた。\nでも、彼女は自らを縛りつけていた啓光を離れたにも関わらず、この砂漠に留まった。",
  ui_story_5080_50800702_73_dialog_content = "どうして…どうして、ここに留まったの？",
  ui_story_5080_50800702_74_dialog_content = "前に話した、<color=#FFB400>あの物語</color>を覚えてる？",
  ui_story_5080_50800702_75_dialog_content = "ええ。",
  ui_story_5080_50800702_76_dialog_content = "物語の続きは、たった1人になったあなたが砂漠で<color=#FFB400>このレンチ</color>と、\n頼ってくれるたくさんの人たちを得たんでしょ。",
  ui_story_5080_50800702_77_dialog_content = "その人たちのために、砂漠にたどり着いた流れ者たちを全員まとめて、\n今の「R・W」ができた。",
  ui_story_5080_50800702_78_dialog_content = "でも、別に責任があるわけじゃないでしょ？\nなのに、どうして残る必要があったのよ…もう、旅は…",
  ui_story_5080_50800702_79_dialog_content = "私はこの砂漠で生まれたのよ。故郷に戻ることの何がいけないの？\nそれに、私は皆に自由になってもらいたいの。",
  ui_story_5080_50800702_80_dialog_content = "自分らしく生きられないなら、暗鬼と何も変わりやしないわ。\n私は皆の魂にかけられた枷をはずして、選択することの自由を知ってもらいたいのよ。",
  ui_story_5080_50800702_81_dialog_content = "私みたいに無為な日々を過ごしてほしくない…",
  ui_story_5080_50800702_82_dialog_content = "だから、他の皆には自分の旅するべき道があることを知って、\n自由な暮らしを楽しんでほしいのよ。",
  ui_story_5080_50800702_83_dialog_content = "今だけ楽しければよくて、ただ騒ぎ立てるのが「自由」だっていうの？",
  ui_story_5080_50800702_84_dialog_content = "アタシには理解できないわ…",
  ui_story_5080_50800702_85_dialog_content = "あなたのおかげで、この世界にはまだ、たくさん知らないモノがあるって知った。",
  ui_story_5080_50800702_86_dialog_content = "あの頃はアタシもこの世界を探索することに夢中だった。",
  ui_story_5080_50800702_87_dialog_content = "あら、すごいじゃない、イェリア。",
  ui_story_5080_50800702_88_dialog_content = "世界はあなたの言うほど素晴らしくなかったわ。\nウソばっかりじゃない。",
  ui_story_5080_50800702_89_dialog_content = "白夜城貴族は傲慢極まりないし、啓光はタイクツで仕方ない。\n北境は北境で、おとぎ話の中で生きてるし――",
  ui_story_5080_50800702_90_dialog_content = "影ノ街のささやきの回廊もイスタバンの保管庫に成り果ててる。\n物語の詰まった遺跡とやらも、あの男には無意味なただのハコにすぎない。",
  ui_story_5080_50800702_91_dialog_content = "全部、虚しいわ…",
  ui_story_5080_50800702_92_dialog_content = "たくさんの奇跡を成し遂げた空の末裔一族も、\n結局忘れ去られて、誰も知らない過去になった。",
  ui_story_5080_50800702_93_dialog_content = "暗鬼に襲われ、暗鬼に反撃し、この世に生きる者はみな、\n生きる苦しみから抜け出せてないじゃない。",
  ui_story_5080_50800702_94_dialog_content = "何もかも結局は虚無よ。",
  ui_story_5080_50800702_95_dialog_content = "イェリアも大人になったのね。\nただ、ちょっと悩み過ぎじゃないの？",
  ui_story_5080_50800702_96_dialog_content = "どういう意味よ…アタシに考えることを止めろっていうの？",
  ui_story_5080_50800702_97_dialog_content = "考えることが孤独な虚しさをもたすだけなら、\nあの騒がしいおバカさんたちに交じった方がいいっていうの？",
  ui_story_5080_50800702_98_dialog_content = "でもイェリア、「空の末裔」に会ったんでしょ？",
  ui_story_5080_50800702_99_dialog_content = "あなたには分かってるはずよ。空の末裔が現れて、天空ノ谷はもう忘れ去られた\n過去なんかじゃない。継承者ができた今、物語が再びつむがれようとしてるのよ。",
  ui_story_5080_50800702_100_dialog_content = "いつまでも変わらない世の中なんてあると思う？",
  ui_story_5080_50800702_101_dialog_content = "運命なんて分からないものよ。\nタイクツや苦しみばかりをもたらすわけじゃないわ。",
  ui_story_5080_50800702_102_dialog_content = "つながりはいつだって、糸のようにイェリアっていう「凧」を\nつなぎとめててくれるの…",
  ui_story_5080_50800702_103_dialog_content = "待って！どこへ行くの？行かないでよ！",
  ui_story_5080_50800702_104_dialog_content = "感じるでしょ？皆があなたを「呼んでる」わ。",
  ui_story_5080_50800702_105_dialog_content = "私はいい先生じゃなかったかもしれないけど…イェリア。\n私は、あなたに会えて、よかったわ。",
  ui_story_5080_50800702_106_dialog_content = "待ってよ！戻ってきて、行かないで！\n行かないでって言ってるでしょ――<color=#FFB400>アタル</color>！！",
  ui_story_5080_50800702_107_dialog_content = "イェリア！",
  ui_story_5080_50800702_108_dialog_content = "…？",
  ui_story_5080_50800702_109_dialog_content = "よかった、目が覚めたんだね。",
  ui_story_5080_50800702_110_dialog_content = "小僧がたいそう心配してな。\nお前にずいぶん長いコト「特技」を使ってたぜ。",
  ui_story_5080_50800702_111_dialog_content = "サメヤマ…？",
  ui_story_5080_50800702_112_dialog_content = "俺たちもいるぞォ。",
  ui_story_5080_50800702_113_dialog_content = "…どうして、R・Wまで来てるのよ。",
  ui_story_5080_50800702_114_dialog_content = "「麗しのエルダー」、やっと目が覚めたか！\nよかった！ケガはないか！？",
  ui_story_5080_50800702_115_dialog_content = "なぜ勇者ゼタを置いていったのだ？\n勇者ゼタはお前の車の音を聞き、すぐに目を覚ましたぞ。",
  ui_story_5080_50800702_116_dialog_content = "暗鬼と戦っている時、ゼタが慌てた様子で車で追ってきたのよ。\nおかげで包囲も解けたわ。",
  ui_story_5080_50800702_117_dialog_content = "ただ、ずいぶん慌てて、まったく言う事を聞いてくれなくて、\nそれで、あなたたちの所まで連れて来るしかなかったの…",
  ui_story_5080_50800702_118_dialog_content = "そこに洞窟が急に崩れてきたんだよ。\nなんだか探険物語の主人公みたいじゃない？",
  ui_story_5080_50800702_119_dialog_content = "洞窟が崩れたことについてだが、\n私の感覚では、火山性の揺れとは違った…",
  ui_story_5080_50800702_120_dialog_content = "そりゃサメヤマのせいだよ。あの怪力でレンチを振り回しやがって。\n言ったじゃねえか。この洞窟はモロいってよ。",
  ui_story_5080_50800702_121_dialog_content = "お前には、来いとは言ってねぇんだがな。",
  ui_story_5080_50800702_122_dialog_content = "おお、俺様が言いたいのはそこだ！こんだけ集めといて、\nなんだって俺様だけ呼ばねぇんだ？ワザとか？",
  ui_story_5080_50800702_123_dialog_content = "サメ坊を責めないでやってくれよ。\n助っ人の頭数そろえるのが目的だったんだからねェ。",
  ui_story_5080_50800702_124_dialog_content = "お？なら、俺よりジョナがよかったんじゃないかな？",
  ui_story_5080_50800702_125_dialog_content = "外も危ないからなァ。ジョナには家を守ってもらわねえと。",
  ui_story_5080_50800702_126_dialog_content = "安心して。アズールが戻れば、ジョナも来るわ。",
  ui_story_5080_50800702_127_dialog_content = "ドーンは感覚が鋭いからな、暗鬼を追跡できる。\nそんで、お前は…卑下するこたァねえよ。オッさんは期待してるんだからねェ。",
  ui_story_5080_50800702_128_dialog_content = "おいっ、役割分担はきっちりしたはずだぞ。口軽はどいつだ！？\nなんだってイブとお前まで来てんだよ！？",
  ui_story_5080_50800702_129_dialog_content = "ごめんね、お兄ちゃん…お兄ちゃんもドーンもいないから、\nみんなにどこ行ったのか聞こうと思って…",
  ui_story_5080_50800702_130_dialog_content = "ううっ、ああもうっ――！\nあいつら、イブに隠し事一つもできねぇのかよ？",
  ui_story_5080_50800702_131_dialog_content = "俺様とイブを置いていこうなんざ、ムリってもんだぜ。\n俺様の全知識を駆使して、追ってきたんだからな！",
  ui_story_5080_50800702_132_dialog_content = "ヘール、キミはイブを連れて帰った方がいいね。\nここは危険だ。",
  ui_story_5080_50800702_133_dialog_content = "洞窟が崩れちまったんじゃ、今から別の道を探して戻るのは危険だねェ。\nオッさんはここに残る方がいいと思うぞ。",
  ui_story_5080_50800702_134_dialog_content = "お前ら全員、静かにしろ！はぁ…なんだってこうなるんだよ…",
  ui_story_5080_50800702_135_dialog_content = "来ちまったもんは仕方ねえ。イブ、ヘール、お前たちも残れ。\nイブ、兄ちゃんにしっかりついてくんだぞ！",
  ui_story_5080_50800702_136_dialog_content = "うん！",
  ui_story_5080_50800702_137_dialog_content = "一致団結して、みんなで一緒に未知に立ち向かおう！",
  ui_story_5080_50800702_138_dialog_content = "終わったら祝賀会だからな！誰一人逃げんじゃねえぞ！",
  ui_story_5080_50800702_139_dialog_content = "いいか、お前ら強がるんじゃねえぞ！なにかあったら俺の後ろに回れ！\nPlayerName、お前らもだ。",
  ui_story_5080_50800702_140_dialog_content = "R・W…ここまで来たんだ、仕方ない。",
  ui_story_5080_50800702_141_dialog_content = "「キャンディーガール」、君は私の後ろにいるんだ。私が…",
  ui_story_5080_50800702_142_dialog_content = "守ってやる。",
  ui_story_5080_50800802_1_dialog_content = "こうなったからには、これ以上隠し事はしねぇ。",
  ui_story_5080_50800802_2_dialog_content = "ロイ 、こいつらにも話そうと思う。\n道がどんどん深くなってきてやがる。「大当たり」が出るかもしんねぇからな。",
  ui_story_5080_50800802_3_dialog_content = "オッさんに異論はないよ。\nお前の知らないことは俺が代わりに説明してやる。",
  ui_story_5080_50800802_4_dialog_content = "急にかしこまったね…",
  ui_story_5080_50800802_5_dialog_content = "15年も前のことだ。あん時はもうアストラで暗潮の危機が勃発しててな。\n俺たちも必死で抵抗し続けてた。",
  ui_story_5080_50800802_6_dialog_content = "だが、キャンプの下に火山があったんだ。\nその火山が突然噴火して、裂け目から大量の暗鬼が湧き出てきやがった。",
  ui_story_5080_50800802_7_dialog_content = "俺たちは打つ手もなく、戦いながらキャンプを捨てて撤退するしかなかった。",
  ui_story_5080_50800802_8_dialog_content = "俺がまだ16だった頃の話だよ。当時のボスに撤退だって言われてな。\n弱かった俺はイブと他のやつらを連れて逃げるしかなかった。",
  ui_story_5080_50800802_9_dialog_content = "そん時オッさんはお頭と一緒に殿を務めてたんだがな…\n結局、先に行けって命令されちまってね。",
  ui_story_5080_50800802_10_dialog_content = "お頭たちだけが残って、最後の戦闘で犠牲になった。",
  ui_story_5080_50800802_11_dialog_content = "あの邪龍もいてな。最初はお頭たちもまだ余裕があったんだが――",
  ui_story_5080_50800802_12_dialog_content = "噴火がどんどん激しくなってな。\nマグマをかぶった暗鬼が中から1匹出てきやがったんだ。",
  ui_story_5080_50800802_13_dialog_content = "マグマをかぶった暗鬼だと？\n私たちの目標で間違いない。",
  ui_story_5080_50800802_14_dialog_content = "お頭はそいつと何か因縁でもあるみてェでな。\nそりャ驚いてただけじゃなく…ひどく恐ろしがってた。",
  ui_story_5080_50800802_15_dialog_content = "そいつがどんなに強いか知ってるっつって、\n俺たちを先に逃がしたんだ。",
  ui_story_5080_50800802_16_dialog_content = "逆らいようのねえ、ひどく威厳のこもった命令でな。俺は逃げるしかなかった。\nお頭は最後の最後に、年長の仲間数人を率いて突っ込んでったんだ。",
  ui_story_5080_50800802_17_dialog_content = "うっ…",
  ui_story_5080_50800802_18_dialog_content = "（激しい感情の波が伝わってくる…これは…レイチェルの感情？）",
  ui_story_5080_50800802_19_option_content = "（動揺してるの？）",
  ui_story_5080_50800802_20_dialog_content = "（そうか…ロイの言うお頭はレイチェルからしたら、\nおばさんをひどい目に遭わせた逃亡兵なんだね）",
  ui_story_5080_50800802_21_option_content = "（信じたくないのかな？）",
  ui_story_5080_50800802_22_dialog_content = "（当時のお頭が自己犠牲っていう貴い精神を持ってたなんて、\nレイチェルには信じたくない事実だよね…）",
  ui_story_5080_50800802_23_dialog_content = "（レイチェルの中のその人はずっと、死を恐れる逃亡兵でしかなかった。\nでも、R・Wの皆にとっては、まぎれもない英雄なんだ！）",
  ui_story_5080_50800802_24_dialog_content = "その後のこたぁ、特に話すことはねぇよ。",
  ui_story_5080_50800802_25_dialog_content = "いやいや、その後は全部サメ坊のおかげだ。若いってのに指揮は明確だったしなァ。\n何よりも、お頭としての覚悟と胆力があったからねェ。",
  ui_story_5080_50800802_26_dialog_content = "サメ坊の指揮の下、俺たちは遊撃を始めて、\n最終的にトラベラーを見つけたんだからなァ。",
  ui_story_5080_50800802_27_dialog_content = "R・Wを建て直せたばかりか、\n砂漠の流れ者も助けて、かえって人数が増えたくらいだ。",
  ui_story_5080_50800802_28_dialog_content = "ボスが犠牲になって、みんなメソメソしてたが、危険がなくなったワケじゃねえ。\nお前らをなんとか奮い立たせねぇといけなかったってだけだよ。",
  ui_story_5080_50800802_29_dialog_content = "俺もイブもよそ者だ。ボスには恩がある。\n仲間どもにも助けられてきた。",
  ui_story_5080_50800802_30_dialog_content = "悪役を買ってでるヤツがいねぇなら俺がやりゃあいい。\nボスは死んじまった。それ以上誰も死なせるワケにゃいかねえよ。",
  ui_story_5080_50800802_31_dialog_content = "乱暴だの、道理が通じないだの、言いたいヤツには言わせておきゃあいい。\n仲間さえ全員生きてりゃ、俺はボスに顔向けできるってもんよ。",
  ui_story_5080_50800802_32_dialog_content = "それ以上のことは、何も考えちゃいなかったさ。",
  ui_story_5080_50800802_33_dialog_content = "デカい図体して謙遜かァ？",
  ui_story_5080_50800802_34_dialog_content = "少し黙ってろ！余計なことばっか話しやがって…",
  ui_story_5080_50800802_35_dialog_content = "噴火がおさまった後、地上の暗鬼は俺たちが少しずつ片付けた。",
  ui_story_5080_50800802_36_dialog_content = "マグマが冷えきって、元のキャンプは影も形もなくなっちまった。\n唯一見つかったのが、あのレンチさ。",
  ui_story_5080_50800802_37_dialog_content = "邪龍も、ボスも、それにあの暗鬼も、何の痕跡も見つけられやしなかった。",
  ui_story_5080_50800802_38_dialog_content = "誰も口にゃあしなかったが、ボスはヤツらを道連れにして、\nマグマん中で死んだんだって思ったよ。",
  ui_story_5080_50800802_39_dialog_content = "邪龍がまた出てくるまではな…",
  ui_story_5080_50800802_40_dialog_content = "んで結局、その特殊な暗鬼も出てきたってワケか。\nだったら、お頭も奴らに食われただけってことか？",
  ui_story_5080_50800802_41_dialog_content = "んなワケねえだろが！あのボスだぞ！！",
  ui_story_5080_50800802_42_dialog_content = "まぁいい。とにかく仇を討つ機会ができたんだからな。\nにしてもまさか、こんな通路があったとはな…",
  ui_story_5080_50800802_43_dialog_content = "今までもこの火山から咆哮がよく聞こえてきてたんだがな。",
  ui_story_5080_50800802_44_dialog_content = "暗鬼の声だっつーことも分かってたが、いくら片付けてもキリがねェし、\n俺たちの知らない通路があるんだろうとは思ってた。",
  ui_story_5080_50800802_45_dialog_content = "フン、やっと見つけたぜ。だが結局…\n来たくねぇとこに来るハメになったか。",
  ui_story_5080_50800802_46_dialog_content = "アタシ…子どもの頃、よく彼女に付いて回ってたのよ。",
  ui_story_5080_50800802_47_dialog_content = "だから、その強さは知ってるわ。サメヤマ、あなたにも負けない驚異的な力の持ち主だった。\nあの龍に負けるなんて、あり得ないわね。",
  ui_story_5080_50800802_48_dialog_content = "それに、いつも何かに耐えてる気がした。",
  ui_story_5080_50800802_49_dialog_content = "ある秘密を命がけで守って、自分を抑え込んでるみたいだったわ。",
  ui_story_5080_50800802_50_dialog_content = "そう言われてみりゃ、確かにそうだな…\n俺も先代も啓光の出身で、お頭の名前はよく聞いてたんだが…",
  ui_story_5080_50800802_51_dialog_content = "実際に会ってみると、想像とは違う感じがしたなァ。",
  ui_story_5080_50800802_52_dialog_content = "オッさんもずっと感じてたもんよ。お頭は「真の姿」を隠してるってな。\n戦ってる時も、何だかいつも力を抑えてる気がしてねェ。",
  ui_story_5080_50800802_53_dialog_content = "それが最後の最後で、「封印」を解いた。\n俺も初めて見たよ、あんなに勢いのある、狂暴なお頭は…",
  ui_story_5080_50800802_54_dialog_content = "怒り狂った時のサメ坊より恐ろしかったな。",
  ui_story_5080_50800802_55_dialog_content = "そのたとえは、おかしくないかな？",
  ui_story_5080_50800802_56_dialog_content = "その彼女が<color=#FFB400>あの暗鬼</color>に殺されたんだとしたら…\nアタシたちで勝てるのかしら？",
  ui_story_5080_50800802_57_dialog_content = "「怒号の火山」も噴火しそうだし、暗潮がまた来るかもしれないわ。\n今のR・Wで対抗できるの？",
  ui_story_5080_50800802_58_dialog_content = "そんなもん、決まってんだろ。",
  ui_story_5080_50800802_59_dialog_content = "受けて立ってやるさ！",
  ui_story_5080_50800802_60_dialog_content = "どんな暗鬼だろうが、俺がこのレンチでフッ飛ばしてやるさ！",
  ui_story_5080_50800802_61_dialog_content = "俺の前に出てくる勇気があるってんなら大歓迎だ！\nこれ以上、好き勝手はさせねぇ！絶対にな！",
  ui_story_5080_50800802_62_dialog_content = "空の末裔1号、ヤングドラゴン2号、よく聞け。",
  ui_story_5080_50800802_63_dialog_content = "どうしたの？急に小声で…",
  ui_story_5080_50800802_64_dialog_content = "私たちの任務は…できるかぎり、あの暗鬼を生け捕りにすることだ。",
  ui_story_5080_50800802_65_dialog_content = "必要とあれば、サメヤマを止めるんだ。",
  ui_story_5080_50800901_1_dialog_content = "また新しい道だよ。いったいどうなってるんだろう？",
  ui_story_5080_50800901_2_dialog_content = "広くなってきているわ。正しい道を来ている証拠よ。",
  ui_story_5080_50800901_3_dialog_content = "砂漠の地下は通常とても複雑よ。\n構造から見て、ここはもともと地脈が造った回廊の壁だったのかもしれないわ。",
  ui_story_5080_50800901_4_dialog_content = "火山が噴火して、その壁にマグマで穴ができて、\nさらに暗鬼たちが穴を掘ってつなげたから、この道ができたんじゃないかしら？",
  ui_story_5080_50800901_5_dialog_content = "岩壁には確かに掘られた痕があるわね。\nでも、工具を使った痕よ。",
  ui_story_5080_50800901_6_dialog_content = "ってことは、暗鬼が掘ったんじゃねえのか？",
  ui_story_5080_50800901_7_dialog_content = "砂漠にはずいぶんと昔から人が住んでたわ。\nおそらく、その人たちが地脈の回廊を拓いたんでしょうね。",
  ui_story_5080_50800901_8_dialog_content = "これは…下を見ろ。強い震動で地層が裂けている。",
  ui_story_5080_50800901_9_dialog_content = "これは切り出された石材だ。つまり床面ということだ。\nここはかつて人工の建物だったんだ。",
  ui_story_5080_50800901_10_dialog_content = "何だって？ここは地下の火口近くだぞ！？",
  ui_story_5080_50800901_11_dialog_content = "そういうことだったの。だから岩壁に工具の痕が残ってたのね。\nただ地脈を拓いたってワケじゃなく、人工物も建てたのね。",
  ui_story_5080_50800901_12_dialog_content = "おい、啓光のよそ者、あんた何してんだ？\nこんな時に泥遊びか？",
  ui_story_5080_50800901_13_dialog_content = "落ち着いて。建材の隙間の奥に残ってる物を掘り出してるのよ。\nそれを見れば、わかることがたくさんあるの。",
  ui_story_5080_50800901_14_dialog_content = "この石材には目立った凹みが3カ所ある。\n隙間には物を燃やした後の灰が残っている。",
  ui_story_5080_50800901_15_dialog_content = "間違いない。かつて人がここで火を起こし、\n煮炊きをしていたんだ。",
  ui_story_5080_50800901_16_dialog_content = "ここからさっきの入口まで、ちょうど1部屋分の距離がある。\nここは地下避難所だったんだろう。",
  ui_story_5080_50800901_17_dialog_content = "遠い昔、ここには暗鬼はおらず、\n何者かの避難所だったらしい。",
  ui_story_5080_50800901_18_dialog_content = "噴火がすべてを埋め尽くしてしまうまで、\nここに隠れていたんだろう。",
  ui_story_5080_50800901_19_dialog_content = "さすがは猛禽ちゃんねぇ。\nたったそれだけの情報で、この地の昔話を掘り起こすなんて。",
  ui_story_5080_50800901_20_dialog_content = "オッさんも感心しちゃったなァ。\nどうりでその若さで偵察隊長さんやってるわけだねェ。",
  ui_story_5080_50800901_21_dialog_content = "サメヤマ、君たちは、昔地下で暮らしてた人がいたって知らなかったの？",
  ui_story_5080_50800901_22_dialog_content = "俺もイブもよそから来たからな。\n古い話は知らねぇよ。",
  ui_story_5080_50800901_23_dialog_content = "俺もロイのオッサンも啓光出身で、オッサンは古いことも色々知ってる方だが、\nおそらくこのことは知らなかっただろうね。",
  ui_story_5080_50800901_24_dialog_content = "なにを見てやがんだ？俺様はまだ若ぇんだぞ。\nそれにサメヤマも知らねぇことを俺様が知ってるワケねぇだろ。",
  ui_story_5080_50800901_25_dialog_content = "もし昔ここで暮らしてた人がいたなら、\nどうして君たちは一切そのことを知らなかったのかな？",
  ui_story_5080_50800901_26_dialog_content = "勇者ゼタも聞いたことないよ。まさか超太古の遺跡ってこと？\n何か強大な力が埋まってたりするのかな？光の巨人とか？",
  ui_story_5080_50800901_27_dialog_content = "すまないねェ。オッさんが勉強をよ～く見てやんなかったせいで、\n歴史を知らねえまま育っちまったな。",
  ui_story_5080_50800901_28_dialog_content = "毎月本を持ってくるよう言っておいて、結局読んでなかったってワケね？",
  ui_story_5080_50800901_29_dialog_content = "すまないねェ、イェリア。",
  ui_story_5080_50800901_30_dialog_content = "そんなモン、うち等が一番に考えることじゃねえだろが。",
  ui_story_5080_50800901_31_dialog_content = "そうそう、勇者ゼタには過去なんて気にしてるヒマないもん。",
  ui_story_5080_50800901_32_dialog_content = "まったくもう…予想はしてたけど、\n実際にそんなこと言われちゃうと…やるせないわねぇ。",
  ui_story_5080_50800901_33_dialog_content = "あなたたちって本当、目の前のコトしか見てないのねぇ。\n足下の土地で昔何が起こって、先人たちが何を託したか、考えようともしないなんて。",
  ui_story_5080_50800901_34_dialog_content = "イェリアさんはきっと知ってるんでしょ？教えて。",
  ui_story_5080_50800901_35_dialog_content = "アタシもそう詳しく知ってるワケじゃないけど、\nただ避難所については、ある言い伝えを知ってるわ。",
  ui_story_5080_50800901_36_dialog_content = "「R・W」の起源とも関係のある話よ。",
  ui_story_5080_50800901_37_dialog_content = "先代が砂漠の流れ者を取り込んでできた\n「R・W」じゃなかったのか？",
  ui_story_5080_50800901_38_dialog_content = "それよりも前に、砂漠にはまとまりのない流れ者が住んでいて、中には罪人もいたのよ。",
  ui_story_5080_50800901_39_dialog_content = "ある者は外の世界を恐れ、また、ある者は外の世界に疲れ果て、\n劣悪な環境にも関わらず、砂漠での暮らしを選んだ。",
  ui_story_5080_50800901_40_dialog_content = "ここでなら「自由」に暮らせるって信じてたのねぇ。",
  ui_story_5080_50800901_41_dialog_content = "自由か…",
  ui_story_5080_50800901_42_dialog_content = "ある日、迫害を受けた白夜城のお嬢様が、\n侍女に連れられて砂漠にやってきた。",
  ui_story_5080_50800901_43_dialog_content = "侍女は自分の故郷にお嬢様を連れて行って、\n一切の争いから逃れようとしたの。",
  ui_story_5080_50800901_44_dialog_content = "「一切の争い」…「白夜城での争い」ね。",
  ui_story_5080_50800901_45_dialog_content = "でも、白夜城の衛兵が2人を追ってきた。\n衛兵は信じていたの、騎士の栄光こそがこの世のすべてだと。",
  ui_story_5080_50800901_46_dialog_content = "興味深いのは、その時ちょうど啓光の軍人も逃亡兵を探すため、\n砂漠の村落を調査しに来ていたのよ。",
  ui_story_5080_50800901_47_dialog_content = "軍人が追っていたのは、挫折して志も信念も失った工兵だった。",
  ui_story_5080_50800901_48_dialog_content = "志と信念を失った啓光の軍人…",
  ui_story_5080_50800901_49_dialog_content = "追跡の途中、啓光の執行人はひょんなすれ違いから、\n白夜城の衛兵が自分と同じ人物を探してるとカン違いしたの。",
  ui_story_5080_50800901_50_dialog_content = "一方、白夜城のお嬢様と侍女は偶然啓光の工兵に出くわし、\n賞金稼ぎだとカン違いした。",
  ui_story_5080_50800901_51_dialog_content = "互いに相手を恐れ、互いに追跡し合い、\n同時に運命のイタズラで互いに強く結びついていった。",
  ui_story_5080_50800901_52_dialog_content = "工兵の手助けのおかげで、白夜城のお嬢様と侍女は無事騎士の手から逃れられた。",
  ui_story_5080_50800901_53_dialog_content = "騎士の邪魔が入ったせいで、啓光の執行人は逃亡兵を捕らえられず、\nソルトロック村に向かうしかなかった。",
  ui_story_5080_50800901_54_dialog_content = "ようするに、バカどもの話ってワケか。",
  ui_story_5080_50800901_55_dialog_content = "その通りよ。「バカども」だったおかげで、殺し合わずに済んだの。",
  ui_story_5080_50800901_56_dialog_content = "彼らは皆、信念をもっていた。それでもチャンスを目の前にしても、\n相手を傷つけようとしなかった。",
  ui_story_5080_50800901_57_dialog_content = "うーん、私はその物語好きだな。",
  ui_story_5080_50800901_58_dialog_content = "そして最後の最後に、彼らはめったに起こらないような激しい砂嵐に遭うの。\nそれまでのすべてが荒れ狂う砂と風に飲み込まれ――",
  ui_story_5080_50800901_59_dialog_content = "危機の中、追われる者は追う者に手を差し伸べ、\n追う者も自らの任務をあきらめた。",
  ui_story_5080_50800901_60_dialog_content = "色々なコトがあって、任務はすでに期限切れとなり、\n追う者たちにも「逃亡兵」となる運命が待っていたの。",
  ui_story_5080_50800901_61_dialog_content = "似たような境遇と助け合う中で生まれた情が、\nついに互いの理解と信頼につながったのね。",
  ui_story_5080_50800901_62_dialog_content = "そうして彼らは共にソルトロック村へ向かい、\nそこで穏やかに暮らすことにしたの。",
  ui_story_5080_50800901_63_dialog_content = "おとぎ話は、それで終わり？",
  ui_story_5080_50800901_64_dialog_content = "いいえ。彼らが侍女の故郷、つまり伝説のオアシス、ソルトロック村に着いた時、\nそこはもう火山の噴火で壊滅してた。",
  ui_story_5080_50800901_65_dialog_content = "しかも生存者は、賊の略奪に遭い、まさに苦痛をきわめてた。",
  ui_story_5080_50800901_66_dialog_content = "オアシスがなければ、穏やかな暮らしなんて到底ムリよね。",
  ui_story_5080_50800901_67_dialog_content = "彼らは、ここも外の世界と変わりはないと希望を失った。",
  ui_story_5080_50800901_68_dialog_content = "…",
  ui_story_5080_50800901_69_dialog_content = "一方、生存者たちは村の聖女について村の出口へと向かうところで、彼らと出くわした。",
  ui_story_5080_50800901_70_dialog_content = "拠り所を求めてやってきた者たちが、突如他の者たちの拠り所となったワケね。",
  ui_story_5080_50800901_71_dialog_content = "強い意志を持った騎士も、固い信念を持った軍人も、\nとっさに頭の切り換えができなかったけど――",
  ui_story_5080_50800901_72_dialog_content = "もうダメかと思ったその時、あの啓光の工兵が持っていたレンチを振り上げて、\n賊たちに飛び掛かって行ったのよ。",
  ui_story_5080_50800901_73_dialog_content = "その勇敢な姿はその場にいた者たちを鼓舞し、\nついに賊たちを追い払うことができた。",
  ui_story_5080_50800901_74_dialog_content = "英雄物語だね！あたし、分かったよ。\nそのレンチがR・Wのレンチでしょ！？",
  ui_story_5080_50800901_75_dialog_content = "フフ。そう慌てないで。話はまだ終わってないのよ～。",
  ui_story_5080_50800901_76_dialog_content = "工兵のおかげで、希望を取り戻した一行は、\n砂漠で新しいオアシスを探す旅に出たの。",
  ui_story_5080_50800901_77_dialog_content = "その途中、たくさんの流れ者を吸収して、\n知らぬ間に強大な勢力になっていった彼らは――",
  ui_story_5080_50800901_78_dialog_content = "最後には「レディーゼルオイル」の豊かな小さなオアシスを見つけて、\nそこに根拠地を置くことになった。",
  ui_story_5080_50800901_79_dialog_content = "これがアタル…いえ、R・Wの先代の頭が話してくれた言い伝えよ。",
  ui_story_5080_50800901_80_dialog_content = "そんな話が残ってるということは、\nかなり昔からこの砂漠に光霊が住んでいたのは確かね。",
  ui_story_5080_50800901_81_dialog_content = "そいつらも俺たちと同じで、\n自分たちの暮らしを探し続けてたってコトだな。",
  ui_story_5080_50800901_82_dialog_content = "地下の避難所は、おそらく追跡を逃れるための場所か、\nもしくは賊から逃れる場所だったのね？",
  ui_story_5080_50800901_83_dialog_content = "そうね。ただ火山の噴火で埋もれたのか、\nそれとも通路の先に火山を見つけて去ったのかは…わからないわ。",
  ui_story_5080_50800901_84_dialog_content = "チッ、ヤケてくるぜ…不公平だろ！？なんだってボスはお前を特別扱いしたんだ？\n俺には一度もそんな話しなかったぞ。",
  ui_story_5080_50800901_85_dialog_content = "それは、あなたたちが興味もたなかったからでしょ。",
  ui_story_5080_50800901_86_dialog_content = "あの頃のアタシは知識欲旺盛で、彼女の話にものすごく興味があった。\nいつもしつこく話を聞かせてって迫ってたわ。",
  ui_story_5080_50800901_87_dialog_content = "でも、こうやってすべてを目にして、過去を知れば知るほど、\n何事もいつかは消えるっていう虚無感に襲われるばかり…",
  ui_story_5080_50800901_88_dialog_content = "それにサメ坊よ。お前はあん頃R・Wに入ったばかりで、\nイブの面倒で忙しかったろ。",
  ui_story_5080_50800901_89_dialog_content = "あん頃は今みてぇに余裕があったワケじゃねえしな。\n毎日メシ食うだけで精一杯だった。",
  ui_story_5080_50800901_90_dialog_content = "お前もそうだ、アズールに車の運転やらなんやら教えてたろ。",
  ui_story_5080_50800901_91_dialog_content = "オッさんはな、生きてるだけで十分…そう思ってたんだよ。\n今を生きられりゃ、それでいいってなァ。",
  ui_story_5080_50800901_92_dialog_content = "あん時はみんな、それ以外のことをアレコレ考える余裕はなかったよ。",
  ui_story_5080_50800901_93_dialog_content = "それがどうした、今は違ぇだろ！",
  ui_story_5080_50800901_94_dialog_content = "今のR・Wの暮らしは苦しくねぇんだ。\n俺様がR・W初の博学者になってやるぜ！",
  ui_story_5080_50800901_95_dialog_content = "サメヤマ、見てろよ。帰ったら死に物狂いで勉強して、\nお前よりもりっぱなボスになってやる！",
  ui_story_5080_50800901_96_dialog_content = "お前なぁ…今の暮らしが苦しくねぇのは、\n誰のおかげだと思ってやがんだ？",
  ui_story_5080_50800901_97_dialog_content = "つまり…今の話に出てきた、最初にレンチを振り上げた者が\n君たちの精神の象徴になったというのか？",
  ui_story_5080_50800901_98_dialog_content = "だが、啓光のエンジニアの持っているレンチは武器ではないし、\nそんなバカ気た大きさのものはない。",
  ui_story_5080_50800901_99_dialog_content = "R・Wの頭が持つレンチは、おそらくトン級の重さだろう？",
  ui_story_5080_50800901_100_dialog_content = "ああ、その通りだ。俺以外にコレを振り回せるヤツはいくらといねぇよ。",
  ui_story_5080_50800901_101_dialog_content = "いったいどんな工兵が、そんなレンチを持ち歩いているというんだ？",
  ui_story_5080_50800901_102_dialog_content = "猛禽ちゃんは、言い伝えがウソだって言いたいのかしら～？",
  ui_story_5080_50800901_103_dialog_content = "その「言い伝え」は、君たちの頭がR・Wの過去を美化するために\n生み出した作り話かもしれない。",
  ui_story_5080_50800901_104_dialog_content = "啓光の資料には、この砂漠には常に賊がはびこり、\nありとあらゆる悪事を働き、逃亡を扇動していたとある。",
  ui_story_5080_50800901_105_dialog_content = "その者たちは「R・W」と自称し、他の光霊を脅かし続けていた。",
  ui_story_5080_50800901_106_dialog_content = "あの者も…私のおばを連れて逃亡し、\nこの砂漠まで来るとR・Wの仲間となって、後に頭となった。",
  ui_story_5080_50800901_107_dialog_content = "流れ者を無理やり仲間にして自身の勢力を拡大し、徐々にこの砂漠を支配していった。\nそうやって今の「R・W」ができたんだ。",
  ui_story_5080_50800901_108_dialog_content = "君の話した物語は、その者がR・Wの歴史を美化するために作ったものにすぎない。",
  ui_story_5080_50800901_109_dialog_content = "おい、啓光のお嬢ちゃんよ。\n他人が崇める相手をデタラメ言って、けすなって教わんなかったのか？",
  ui_story_5080_50800901_110_dialog_content = "今は手を組んでるからって、\nなんでも好き勝手言っていいってワケじゃねぇぞ！",
  ui_story_5080_50800901_111_dialog_content = "ちょっと待ってよ、レイチェル。もしそうなら道理が通らないよ？\n君の言う通り、砂漠を制したなら、どうして過去を美化する必要があるの？",
  ui_story_5080_50800901_112_dialog_content = "僕にはサメヤマたちが信じてるお頭さんが、\nそんな人だとは思えない。",
  ui_story_5080_50800901_113_dialog_content = "まさか…本当に守ろうとしたのか？",
  ui_story_5080_50800901_114_dialog_content = "だから…君たちの心や志も守ろうとしたっていうのか…",
  ui_story_5080_50800901_115_dialog_content = "…",
  ui_story_5080_50800901_116_dialog_content = "チッ、お前…なんでも分かんじゃねえのかよ？",
  ui_story_5080_50800901_117_dialog_content = "待って、また地震？",
  ui_story_5080_50800901_118_dialog_content = "違うわ、暗鬼の群れが動いてるのよ。",
  ui_story_5080_50800901_119_dialog_content = "よく見てろ、啓光の「働きアリ」さんよ。\nR・Wの生きる道は、R・Wっつー家族を守る決意だ！",
  ui_story_5080_50800901_120_dialog_content = "その気迫と力を今見せてやる！",
  ui_story_5080_50801000_1_dialog_content = "もう、お兄ちゃんったら、はりきり過ぎだよ。\n火傷だらけじゃない。",
  ui_story_5080_50801000_2_dialog_content = "これしきのこと、なんてことないさ！",
  ui_story_5080_50801000_3_dialog_content = "おい、ロイ 。メシの時間じゃねえのか？\nみんな腹空かしてるぞ！",
  ui_story_5080_50801000_4_dialog_content = "今日はどんなご馳走だい？",
  ui_story_5080_50801000_5_dialog_content = "そういやそうだな。よ～し、メシだメシだ！\nガキんちょども、鍋を用意しろォ。",
  ui_story_5080_50801000_6_dialog_content = "ドーン、火口の「野生のごちそう」を捕まえに行くぞ～！",
  ui_story_5080_50801000_7_dialog_content = "何をしているんだ？",
  ui_story_5080_50801000_8_dialog_content = "「働くには休憩も必要」だろ、啓光のお嬢ちゃん。",
  ui_story_5080_50801000_9_dialog_content = "驚くことないよ。R・Wはいつもこうなんだ。\n食事くらい任務に影響もないでしょ？",
  ui_story_5080_50801000_10_dialog_content = "R・Wの「変わった料理」が苦手なら、\n他の食糧も持ってきてるしね。",
  ui_story_5080_50801000_11_dialog_content = "任務中だぞ！",
  ui_story_5080_50801000_12_dialog_content = "腹が空いたからといって…万が一不意打ちに遭ったらどうする？",
  ui_story_5080_50801000_13_dialog_content = "ヤングドラゴン2号、空の末裔1号、ホワイトランス。\n任務を続行する。",
  ui_story_5080_50801000_14_dialog_content = "はい、隊長！",
  ui_story_5080_50801000_15_dialog_content = "<color=#e8d9bb>グゥ――</color>",
  ui_story_5080_50801000_16_dialog_content = "あ、ええっと…申し訳ありません…朝ご飯を食べていなくて…",
  ui_story_5080_50801000_17_dialog_content = "…",
  ui_story_5080_50801000_18_dialog_content = "レイチェル、知り合いの啓光の古参兵が以前、僕にこう言ったんだ。\n「腹いっぱい食え！腹いっぱい食ってこそ力も出るってもんだ」って。",
  ui_story_5080_50801000_19_dialog_content = "本人が名言だって自慢してたけど、\n皆もその通りだって納得してるんだ。",
  ui_story_5080_50801000_20_dialog_content = "レイチェル、ゼタもバイスも朝から\n移動やら、戦闘やら、ずっと動きっぱなしだったんだ…",
  ui_story_5080_50801000_21_dialog_content = "啓光の古参兵は皆、ご飯も食べず戦い続けることが\nどんなに大変かよく知ってるんだよね？",
  ui_story_5080_50801000_22_dialog_content = "彼らはそれでも戦い続ける。",
  ui_story_5080_50801000_23_dialog_content = "だからこそ、後輩たちにはちゃんとご飯を食べさせたいって思ってるんだよ。",
  ui_story_5080_50801000_24_dialog_content = "…エネルギーを補給しなければ前進も難しい。\n任務遂行のためにも、ここで休むことを特別に許可する。",
  ui_story_5080_50801000_25_dialog_content = "私が見張っていよう。全員が気を抜くわけにはいかないからな…",
  ui_story_5080_50801000_26_dialog_content = "隊長も圧縮食糧くらい食べてください！隊長！",
  ui_story_5080_50801000_27_dialog_content = "行かせてあげましょ。ただ任務をきちんとやり遂げたいだけよ。",
  ui_story_5080_50801000_28_dialog_content = "今戻ったぞ～…って、なに先に食ってんだァ！",
  ui_story_5080_50801000_29_dialog_content = "勇者ゼタは何をするにも効率第一なんだ！\nあたしも見張りを手伝いに行ってくるね！",
  ui_story_5080_50801000_30_dialog_content = "…食べるのが速いな。訓練すれば、いい軍人になれる。",
  ui_story_5080_50801000_31_dialog_content = "啓光の兵士になる気はないよ。\nだって、あたしは世界の救世主になる定めなんだから！",
  ui_story_5080_50801000_32_dialog_content = "あんたもちょっとは食べて。このムシの干物おいしいんだから！\nわざわざ勇者様が持ってきたあげたよ。",
  ui_story_5080_50801000_33_dialog_content = "ありがとう…「キャンディーガール」。",
  ui_story_5080_50801000_34_dialog_content = "あたしは「勇者」で「救世主」なんだよ！\n「キャンディーガール」なんて、そんな「通行人A」みたいな存在じゃないんだから！",
  ui_story_5080_50801000_35_dialog_content = "あんたってカッコいいのに趣味がイマイチだね。\nきっと子どもの頃にさらわれて、「魔王軍」にでも入れられちゃったんでしょ？",
  ui_story_5080_50801000_36_dialog_content = "ホント大変だったね。「今や宿敵に与した救世主の生き別れた姉上」！",
  ui_story_5080_50801000_37_dialog_content = "「姉上」…？",
  ui_story_5080_50801000_38_dialog_content = "そうだよ、あたしは「勇者となった妹」なの。\n安心して。あたしがきっとその心の鎖を解いてあげるから！",
  ui_story_5080_50801000_39_dialog_content = "あれれ～？もしかして笑った？笑ったとこ、初めて見たよ…\nやっぱり家族のキズナってスゴイね！",
  ui_story_5080_50801000_40_dialog_content = "気にしないでちょうだい。その子はオママゴトが好きなの。\nいつも勝手に色々設定して…",
  ui_story_5080_50801000_41_dialog_content = "姉上か…フッ…",
  ui_story_5080_50801000_42_dialog_content = "何か思い出したみたいね。あなた、妹がいるのね？",
  ui_story_5080_50801000_43_dialog_content = "ああ…とても賢く、私よりもずっとたくましくて…可愛らしい子だ。",
  ui_story_5080_50801000_44_dialog_content = "学業を修め終えたら、きっと模範的な軍人となり――",
  ui_story_5080_50801000_45_dialog_content = "自慢の妹になるだろう。",
  ui_story_5080_50801000_46_dialog_content = "なんだ…ふんっ…",
  ui_story_5080_50801000_47_dialog_content = "あらあら、ゼタ。納得いかないって顔してるじゃな～い？",
  ui_story_5080_50801000_48_dialog_content = "うらやまし…いや、違うよ！嫉妬とかじゃないもん！ただ…",
  ui_story_5080_50801000_49_dialog_content = "こんなお姉ちゃんがいたら、きっと幸せだろうなって。",
  ui_story_5080_50801000_50_dialog_content = "だって「飛鷹ハンター」はあの魔女よりずっとやさしいもん。",
  ui_story_5080_50801000_51_dialog_content = "ダメだ。私はまだまだだ。",
  ui_story_5080_50801000_52_dialog_content = "もっと努力が必要だ…もっと努力して…\n家族にこれ以上迷惑をかけないようにしなければ。",
  ui_story_5080_50801000_53_dialog_content = "ウォオオ、オオ～♪",
  ui_story_5080_50801000_54_dialog_content = "急に歌い出して、どうした？うるせぇぞ！",
  ui_story_5080_50801000_55_dialog_content = "そういや言ってなかったな。バーバラのやつがヘールはお前より素質があるって言ってなァ。\nんで、ここんとこ練習に励んでるってわけだ。",
  ui_story_5080_50801000_56_dialog_content = "なにぃっ！？",
  ui_story_5080_50801000_57_dialog_content = "「サメヤマさんよりスゴイR・Wで一番のテノール」ってバーバラが言ってたよ。",
  ui_story_5080_50801000_58_dialog_content = "てなわけで、練習に励んでるのさ。\n聞くところによると、歌で人の心をつかむ準備はできてるらしいぞォ。",
  ui_story_5080_50801000_59_dialog_content = "じゃ、俺も練習しないとな。\n楽隊に入る約束をしちゃったからね。",
  ui_story_5080_50801000_60_dialog_content = "ええと、ドラムスティックはどこにやったかな…？これは、違う…\nこれも、違う…あ、あった！",
  ui_story_5080_50801000_61_dialog_content = "よ～し、じゃオッさんがリズムをとってやろう。\nさあ、練習始めるぞォ！",
  ui_story_5080_50801000_62_dialog_content = "何なんだ、こいつらは…",
  ui_story_5080_50801000_63_dialog_content = "フェラール、もっと激しくだ！\nお前の情熱を全部スティックに込めろ！",
  ui_story_5080_50801000_64_dialog_content = "俺様の歌について来い――！おい、付いてきてるか？",
  ui_story_5080_50801000_65_dialog_content = "それ以上うるさくすると、暗鬼が出てくるぞ。",
  ui_story_5080_50801000_66_dialog_content = "おい、フェラール、壁を叩くんじゃねえ！\n暗鬼が寄ってくるだろ！",
  ui_story_5080_50801000_67_dialog_content = "サメヤマは常識があってよかったわ。R・Wときたら…",
  ui_story_5080_50801000_68_dialog_content = "レンチを貸してやる。練習してぇなら、これを叩け。\n思いっきりやって構わねえ！",
  ui_story_5080_50801000_69_dialog_content = "暗鬼が寄って来たら、どうするんだ？",
  ui_story_5080_50801000_70_dialog_content = "構わねえよ。ちょうど見つけられねぇで困ってたとこだ。\nもっと上げていけ、もっとだ！",
  ui_story_5080_50801000_71_dialog_content = "やれやれ…救いようがないわね。",
  ui_story_5080_50801000_72_dialog_content = "こんなに広い砂漠の中で暮らしてるっていうのに、\n探求心も持たず、ただ毎日騒いでるだけなんて…",
  ui_story_5080_50801000_73_dialog_content = "でも、イェリア…探求心って何だろう？",
  ui_story_5080_50801000_74_dialog_content = "あら、空の末裔くんまで迷いが出てきちゃった？",
  ui_story_5080_50801000_75_dialog_content = "そうじゃなくて、ただ…こんな厳しい環境の中で暮らしてるのに、\nサメヤマたちは一度もそれを嘆いたことはないでしょ。",
  ui_story_5080_50801000_76_dialog_content = "ずっと、楽しく暮らせる方法を探し続けて、\nすごく楽しそうに暮らしてる。",
  ui_story_5080_50801000_77_dialog_content = "だから僕には、サメヤマたちはもう十分、\n自分の人生に対する探究心を持ってるように思えるんだ。",
  ui_story_5080_50801000_78_dialog_content = "そうよ、イェリアさん。あなたは知識豊富なのに、人生や生きることになると、\n何だかいつも消極的になってる気がするわ…",
  ui_story_5080_50801000_79_dialog_content = "本当にそれでいいの？",
  ui_story_5080_50801000_80_dialog_content = "啓光で暮らしてるバイスちゃんにそんなふうに言われちゃ、\n何て答えたらいいか、わからなくなっちゃうわねぇ。",
  ui_story_5080_50801000_81_dialog_content = "啓光の者に、生活や自由を語る資格はないって思うかもしれないけど…",
  ui_story_5080_50801000_82_dialog_content = "私は啓光で育ったから、分かるの。\n啓光の信念は自らが防衛線となり、背後にいるすべての人々を守ること。",
  ui_story_5080_50801000_83_dialog_content = "私たちは多くの犠牲を払うかもしれない。\nでも、そうやって守った防衛線の中の人たちは幸せに暮らせるってことは知ってるわ。",
  ui_story_5080_50801000_84_dialog_content = "その人たちの笑顔こそ、私が守りたいものなの。",
  ui_story_5080_50801000_85_dialog_content = "みんなが頑張って生きてるところを見られて、私は嬉しい。\nこんなふうに自由に生きてる姿を見られるだけで十分なの。",
  ui_story_5080_50801000_86_dialog_content = "守ることの…意義…！？",
  ui_story_5080_50801000_87_dialog_content = "そう、あなたたちの考え方も変わってるわね。",
  ui_story_5080_50801000_88_dialog_content = "誰かのために生きる…アタシには自由な生き方には思えないけど、\nそれはそれで、立派な生き方よね。",
  ui_story_5080_50801000_89_dialog_content = "うーん、ちょっと想像できないわね。自分で努力して人生の道を探すべきなのに、\n他の人と深くつながってしまう…",
  ui_story_5080_50801000_90_dialog_content = "僕はやっぱり、人と人とのつながりは切れるものじゃないと思うな。",
  ui_story_5080_50801000_91_dialog_content = "イェリアだって、能天気なおバカさんに仲間入りしたくないと思ってても、\n今はもう皆とのつながりを断つことはできないでしょ？",
  ui_story_5080_50801000_92_dialog_content = "…そうね。今じゃ家の中はイタズラ書きだらけだし、\n子どもたちに渡すプレゼントや本が山積みよ。",
  ui_story_5080_50801000_93_dialog_content = "神出鬼没なんて言われてるけど、あの子たちにはいつも見つかっちゃうし、\n車まで勝手に乗って行かれちゃうわ。",
  ui_story_5080_50801000_94_dialog_content = "ぶつけて壊しちゃったこともあるけど、ちゃんと直したよ！",
  ui_story_5080_50801000_95_dialog_content = "特別な当て板をしておいてあげたよ。",
  ui_story_5080_50801000_96_dialog_content = "今でもイェリアはまだ、自分は他の皆とつながってないって思う？",
  ui_story_5080_50801000_97_dialog_content = "あら、どうしたの？空の末裔くんったら、\nアタシの人間関係なんか気にしちゃって、心配してくれてるのぉ？",
  ui_story_5080_50801000_98_dialog_content = "この人たちと打ち解けたからって、迷いが減るワケじゃないわ。",
  ui_story_5080_50801000_99_dialog_content = "よし、いいぞ、このリズムだ！",
  ui_story_5080_50801000_100_dialog_content = "お前たちの熱意も気持ちも伝わってきたぞ！\nさあ、声を合わせて歌え！",
  ui_story_5080_50801000_101_dialog_content = "<color=#e8d9bb>サメヤマの指揮の下、R・Wのメンバーたちは「懸命」に声を上げて歌った。</color>",
  ui_story_5080_50801000_102_dialog_content = "<color=#e8d9bb>まったく揃っていなかったが、誰もが全力で歌い、誰一人として歌声を止めない。\nそれはとても「息の合った」合唱だった。</color>",
  ui_story_5080_50801000_103_dialog_content = "個性が強すぎるのよ。\nとてもじゃないけど、打ち解けられる連中じゃないわぁ。",
  ui_story_5080_50801000_104_dialog_content = "なのに何を間違ったか、これがアタシの「家族」なのよねぇ。",
  ui_story_5080_50801000_105_dialog_content = "歌うのはいいが、鍋を倒すんじゃないぞォ。",
  ui_story_5080_50801000_106_dialog_content = "あ、そうだ！イェリア、ちょっと前に龍州に行ってきたんだ。\n龍州には「火鍋」っていう面白い料理があるんだよ。",
  ui_story_5080_50801000_107_dialog_content = "辛いスープを鍋で煮立てたら、そこに色々な食材を入れて、\nすくい出して食べるんだ。",
  ui_story_5080_50801000_108_dialog_content = "どんな食材を入れてもいいんだよ。\n辛いスープの中では、味が移ることもないんだ。",
  ui_story_5080_50801000_109_dialog_content = "今砂漠で暮らしてる君たちは、火鍋そっくりだね。",
  ui_story_5080_50801000_110_dialog_content = "R・Wって本当にいいなぁ。砂漠は大きくて、どんな人も受け入れてくれる。\nその一人一人が自分の人生を豊かにしようと頑張るのを見守ってくれる…",
  ui_story_5080_50801000_111_dialog_content = "「火鍋」ねぇ…",
  ui_story_5080_50801000_112_dialog_content = "イェリア、聞いて――聞こえた？あのタカ、歌を歌ってるわ。",
  ui_story_5080_50801000_113_dialog_content = "鳥が鳴いてるだけじゃない。",
  ui_story_5080_50801000_114_dialog_content = "アハハ。でも、イェリア。\nあの鳥は本当に今、旅の喜びを歌ってるかもしれないじゃない？",
  ui_story_5080_50801000_115_dialog_content = "…どうして、あの言い伝えを話してくれたの？",
  ui_story_5080_50801000_116_dialog_content = "だって、すごいと思わない？それぞれR・W、白夜城、啓光で生まれ、\n身分もまったく違う見知らぬ人たちが最後には仲間になったのよ。",
  ui_story_5080_50801000_117_dialog_content = "災難の絶えないこの世界で、\n孤独だった人たちが互いに情を持つようになった。",
  ui_story_5080_50801000_118_dialog_content = "他人を守るためにレンチを振り上げ、リーダーになった人も、\nそんな人に付いて、一緒に努力する人もいた。",
  ui_story_5080_50801000_119_dialog_content = "そうやって、砂漠は私たちの家になった。",
  ui_story_5080_50801000_120_dialog_content = "旅の途中でたまたま同じ空をかすめた鳥たちが\n群れとなって自分たちのオアシスを見つけたのよ。",
  ui_story_5080_50801000_121_dialog_content = "イェリア、自分の人生を豊かにしてくれるものを探しにいきない。\n力いっぱい飛んで、力いっぱい歌うのよ！",
  ui_story_5080_50801000_122_dialog_content = "あなたがさまよい続けることはないわ。\nだって、ここにはずっと前からあなたの居場所があるんだから。",
  ui_story_5080_50801101_1_dialog_content = "<color=#e8d9bb>燃え盛る太陽よりも情熱的なギターの音が響き、砂漠の熱気を突き破る。\n地面から伝わる震動さえも圧倒していく。</color>",
  ui_story_5080_50801101_2_dialog_content = "進め、前へ！私の心は永遠に止まらない！",
  ui_story_5080_50801101_3_dialog_content = "こんなに暑いのに、よくまぁこんな所で\n新曲のリハーサルなんてできますね。",
  ui_story_5080_50801101_4_dialog_content = "バーバラも遅れをとるわけにはいかないよ。\nタイニー、私たちも行くよ～！",
  ui_story_5080_50801101_5_dialog_content = "「ステージ」はもう直ってるよ。\nあたしは他にも用があるから、1人で行ってきて。",
  ui_story_5080_50801101_6_dialog_content = "あ、あ。こちらR・W…",
  ui_story_5080_50801101_7_dialog_content = "バップ、ジョナから早く帰ってこいって言われたんだけど、\n何かあったの？",
  ui_story_5080_50801101_8_dialog_content = "こっちよ～、永遠に輝き続けるアイドル、R・Wハニー！バーバラだよ～！",
  ui_story_5080_50801101_9_dialog_content = "応答願います。こちらR・W…アズール？アズールなの？",
  ui_story_5080_50801101_10_dialog_content = "あら、ずいぶんにぎやかみたいねぇ。",
  ui_story_5080_50801101_11_dialog_content = "ほえろ、灼熱の太陽！もっとほえるんだ！",
  ui_story_5080_50801101_12_dialog_content = "あ、あ。こちらR・W…",
  ui_story_5080_50801101_13_dialog_content = "あ、あ…もしもし？ぜんぜん聞えなんだけど。\nまぁいいわ。今から戻るから待ってて。",
  ui_story_5080_50801101_14_dialog_content = "ねぇ、マギー。地雷はちゃんと埋めた？",
  ui_story_5080_50801101_15_dialog_content = "暑い…分かってますよ。すぐにちゃんと埋めます！",
  ui_story_5080_50801101_16_dialog_content = "日が落ちる前に、キャンプの周りを地雷で囲んじゃお～！",
  ui_story_5080_50801101_17_dialog_content = "本当にそこまでやる必要があるんでしょうか？",
  ui_story_5080_50801101_18_dialog_content = "<color=#e8d9bb>砂漠では震動がいまだに続いていた。\n遠くの火山は咆哮をあげ、怒りを吹き出し続けていた。</color>",
  ui_story_5080_50801101_19_dialog_content = "ボスたちがあっちに行って、だいぶ経つね…",
  ui_story_5080_50801101_20_dialog_content = "通信にも応答ないし。",
  ui_story_5080_50801101_21_dialog_content = "タイニーとフェラールがいないから、\n車は私が修理するわ。",
  ui_story_5080_50801101_22_dialog_content = "ふん、勝負しようっての？あたしの方がすごいってまだ認めないワケ？",
  ui_story_5080_50801101_23_dialog_content = "何ですって！？",
  ui_story_5080_50801101_24_dialog_content = "トラベラーで動き始めた方がいいんじゃないかな？",
  ui_story_5080_50801101_25_dialog_content = "おい、バップ。さっきの通信はアズールからか？",
  ui_story_5080_50801101_26_dialog_content = "わかんないよ…",
  ui_story_5080_50801101_27_dialog_content = "あんたが受けたのに、なんで分からないんだ？",
  ui_story_5080_50801101_28_dialog_content = "パトロールに戻って。このあと…",
  ui_story_5080_50801101_29_dialog_content = "まあいい。アズール以外にいないだろうからな。",
  ui_story_5080_50801101_30_dialog_content = "せっかくの機会だからな。\n事が済んだら、大いに付き合ってもらうとするか。",
  ui_story_5080_50801101_31_dialog_content = "…話、聞いてよ。",
  ui_story_5080_50801101_32_dialog_content = "着いたぞ。ここが火口に一番近いとこだ。",
  ui_story_5080_50801101_33_dialog_content = "ここから飛び降りれば、すぐ火口の中だ――",
  ui_story_5080_50801101_34_dialog_content = "この火山の活発度は…ホークハンター1号、探知モード起動！",
  ui_story_5080_50801101_35_dialog_content = "…やはり、この火山は今非常に活発な状態にある。",
  ui_story_5080_50801101_36_dialog_content = "それなのに、なぜまだ噴火の臨界点に達しないんだ？",
  ui_story_5080_50801101_37_dialog_content = "これは死火山が目覚めた程度の話ではない。\nこの山にはずっと力が満ちていたはずだ。",
  ui_story_5080_50801101_38_dialog_content = "でも、ここ10数年の間、1度も噴火してないわ。",
  ui_story_5080_50801101_39_dialog_content = "おかしいわね…",
  ui_story_5080_50801101_40_dialog_content = "おいおいおい、冗談だよなァ？火口から暗鬼がはい出てきたぞ。",
  ui_story_5080_50801101_41_dialog_content = "あの暗鬼だな…アイツらのマグマのエネルギーは、ここが源らしい。",
  ui_story_5080_50801101_42_dialog_content = "行くぞ、飛び降りろ！",
  ui_story_5080_50801101_43_dialog_content = "バイス…カレン…待ってよ！高すぎるってぇ！",
  ui_story_5080_50801102_1_dialog_content = "暗鬼も一応、「生物」だよな？",
  ui_story_5080_50801102_2_dialog_content = "暗鬼が火口の中で生息してるのか？\nマグマのエネルギーを使うだけじゃなく、マグマに耐性があるってことか？",
  ui_story_5080_50801102_3_dialog_content = "フェラール、計算しろ。\nどうしたらこの火口を爆破できるか。",
  ui_story_5080_50801102_4_dialog_content = "この暗鬼どもがマグマさえ恐れねぇっつーなら、\n火口を爆破してヤツらを閉じ込めるしかねえ。",
  ui_story_5080_50801102_5_dialog_content = "それはダメだ。あのお嬢さんが言った通り、この山は活火山だよ。\nやみくもに爆破なんかしたら、噴火を誘発する恐れがある。",
  ui_story_5080_50801102_6_dialog_content = "揺れが続いてるよ。ってことは、暗鬼はまだまだ奥から\n出て来るってことだよね…",
  ui_story_5080_50801102_7_dialog_content = "外の状況も分からないし、速攻即決で行かなきゃダメだ。",
  ui_story_5080_50801102_8_dialog_content = "この火山はなぜ活火山でありながら、\n長い間休眠しているように見えていたのだ？",
  ui_story_5080_50801102_9_dialog_content = "いったい何が原因なんだ？",
  ui_story_5080_50801102_10_dialog_content = "火山の怒りは地脈のエネルギーが不安定なせいかもしれないわね。",
  ui_story_5080_50801102_11_dialog_content = "原因がわかれば、危機の解決につながるかも。",
  ui_story_5080_50801102_12_dialog_content = "いずれにせよ、急がねぇとな。",
  ui_story_5080_50801102_13_dialog_content = "揺れがこのまま続けば、暗鬼どもが地上に出て行っちまう。",
  ui_story_5080_50801102_14_dialog_content = "R・Wのヤツらはいいとしても、村の平民はどうする？",
  ui_story_5080_50801102_15_dialog_content = "確かにその通りだね。何かいい考えでもあるの？",
  ui_story_5080_50801102_16_dialog_content = "ねぇよ、そんなもん。ヤツらはこの中から出て来てんだ。\nだったら、俺が中に入って見てくりゃいいことだ。",
  ui_story_5080_50801102_17_dialog_content = "<size=45>えぇっ！？</size>",
  ui_story_5080_50801102_18_dialog_content = "サメヤマ、何を言ってるのかわかってるの？\nここは火山なのよ？",
  ui_story_5080_50801102_19_dialog_content = "分かってるさ。だからこそ放っとけねぇんだろ。",
  ui_story_5080_50801102_20_dialog_content = "一日中ゴオオゴオオうるさくって敵わねぇ。\n新しい仇も古い仇も一気に討っちまうんだよ。",
  ui_story_5080_50801102_21_dialog_content = "なぜ…そこまでするんだ？",
  ui_story_5080_50801102_22_dialog_content = "ケッ。あんたからそんな言葉を聞くなんておかしな話だな。",
  ui_story_5080_50801102_23_dialog_content = "R・Wは「逃亡兵」ではないか。君もその組織の者だ。",
  ui_story_5080_50801102_24_dialog_content = "君たちはずっと他人の物を奪うことを生業としてきた。\nその場その場に適応して高い志もなく、生きているんだろう？",
  ui_story_5080_50801102_25_dialog_content = "そんな君がなぜ命を賭けてそこまでする？",
  ui_story_5080_50801102_26_dialog_content = "だったら、こっちも聞くが、あんたは啓光で何してたんだ？\nなんだって、こんな遠くの火山まで来たんだ？",
  ui_story_5080_50801102_27_dialog_content = "私は「ホークアイ小隊」の隊長だ！\n隊を率い40数回もの高難易度の特殊任務を遂行した者だ！",
  ui_story_5080_50801102_28_dialog_content = "私以外の者には、この任務は危険だ。",
  ui_story_5080_50801102_29_dialog_content = "私は栄誉のためにここに来た。君たちとは違う。",
  ui_story_5080_50801102_30_dialog_content = "あんた、知ってっか？そこのフェラールとこのオッサンは2人とも\nカナン城で生まれたんだぜ。",
  ui_story_5080_50801102_31_dialog_content = "そこじゃ栄誉もなんも感じられねぇばかりか、息が詰まっちまうから、\n砂漠まで来るしかなかったんだよ。",
  ui_story_5080_50801102_32_dialog_content = "あんたのいう栄誉ってなんだ？",
  ui_story_5080_50801102_33_dialog_content = "栄誉とは――",
  ui_story_5080_50801102_34_dialog_content = "啓光のお嬢ちゃんよ。あんた、ほんとに「犠牲」の意味分かってんのか？",
  ui_story_5080_50801102_35_dialog_content = "啓明の光のために、すべての光霊を解放するという大義のために、\n命もいかなる代償も惜しまない！",
  ui_story_5080_50801102_36_dialog_content = "私はいつでも、その大業のため犠牲になる覚悟ができている！",
  ui_story_5080_50801102_37_dialog_content = "…",
  ui_story_5080_50801102_38_dialog_content = "なぜ、そんな顔をしている？",
  ui_story_5080_50801102_39_dialog_content = "そうやって自分をだましてきたワケか？",
  ui_story_5080_50801102_40_dialog_content = "まぁいい。今何を言ったところでムダだろうよ。",
  ui_story_5080_50801102_41_dialog_content = "ロイ 、このお嬢ちゃんはまだ夢から覚めてねぇみてえだ。",
  ui_story_5080_50801102_42_dialog_content = "なにっ…！",
  ui_story_5080_50801102_43_dialog_content = "さあ、どいたどいた。家にすくったムシの巣を払わなきゃいけねぇんだ。\nおせっかいはよしてくれ。",
  ui_story_5080_50801102_44_dialog_content = "おいおい、サメ坊。誰が1人でやれっつった？\n俺たちを忘れんじゃねえよ。",
  ui_story_5080_50801102_45_dialog_content = "お前たち、なに一緒になって立ち上がってんだよ。\n危ねぇじぇねえか。",
  ui_story_5080_50801102_46_dialog_content = "そりゃお前も一緒だろが、バカもんが！",
  ui_story_5080_50801102_47_dialog_content = "全員で火山に飛び込むっていうの？\nどう考えても利口なやり方じゃないわね。",
  ui_story_5080_50801102_48_dialog_content = "準備はいいか、みんな…うわあっ！",
  ui_story_5080_50801102_49_dialog_content = "地震よ、気を付けて！",
  ui_story_5080_50801102_50_dialog_content = "<color=#e8d9bb>突如起こった地震が火口の縁に立っていた僕たちを\n火口の中へと引き落とした</color>",
  ui_story_5080_50801102_51_dialog_content = "お兄ちゃん！",
  ui_story_5080_50801102_52_dialog_content = "イブ！！みんな！今行くぞ！！",
  ui_story_5080_50801102_53_dialog_content = "俺の目の前から…誰一人として奪えると思うなよ！",
  ui_story_5080_50801102_54_dialog_content = "<color=#e8d9bb>サメヤマは、まるで砲弾かのように飛び降りると、\nその怪力で全員を安全な場所へと放り投げた</color>",
  ui_story_5080_50801102_55_dialog_content = "<color=#e8d9bb>サメヤマが飛び降り、どんどんと近づいてくるのが見えた――\nそれを見て僕はなぜか、すごく安心した</color>",
  ui_story_5080_50801102_56_dialog_content = "PlayerName、つかまれ――！",
  ui_story_5080_50801102_57_dialog_content = "待ってよ、下はマグマだよ！君はどうするの！？",
  ui_story_5080_50801102_58_dialog_content = "知るか、そんなもん！行け！",
  ui_story_5080_50801102_59_dialog_content = "小僧――くたばんじゃねえぞ！",
  ui_story_5080_50801102_60_dialog_content = "<size=50>サメヤマ！！</size>",
  ui_story_5080_50801201_1_dialog_content = "任務は無事完遂だ。「ホークアイ」は大きな貢献をしたぞ！",
  ui_story_5080_50801201_2_dialog_content = "レイチェル、よくやった。\n啓光はお前たちの払った犠牲を深く胸に刻むことだろう。",
  ui_story_5080_50801201_3_dialog_content = "兵士よ、一歩前へ。大元帥直々に栄誉勲章をお授けになる！",
  ui_story_5080_50801201_4_dialog_content = "全力で救援に努めたのだが…すまない、レイチェル。\n私にはこれをこの手で渡すことしかできない。お前たちの犠牲に心から感謝する。",
  ui_story_5080_50801201_5_dialog_content = "あ…ぁ…！",
  ui_story_5080_50801201_6_dialog_content = "重たい…",
  ui_story_5080_50801201_7_dialog_content = "何だ？",
  ui_story_5080_50801201_8_dialog_content = "全員、ここにいます…私の手の上に…重たい…",
  ui_story_5080_50801201_9_dialog_content = "私1人のために…隊員は全員…全員、犠牲になりました…",
  ui_story_5080_50801201_10_dialog_content = "誰か！急げ！レイチェルが倒れた！",
  ui_story_5080_50801201_11_dialog_content = "胸が痛い…けがなどしていないのに、痛みが止まらない…おばさん…",
  ui_story_5080_50801201_12_dialog_content = "ありがとうございます、隊長…全力で任務を完遂してくださって…",
  ui_story_5080_50801201_13_dialog_content = "これで、私たちの子も「失敗者」ではなくなりました。",
  ui_story_5080_50801201_14_dialog_content = "ようやく英雄として安らかに眠れます。",
  ui_story_5080_50801201_15_dialog_content = "違う――",
  ui_story_5080_50801201_16_dialog_content = "おばさん、私は…すごく辛い…\n任務を完遂したのに、本当に…すごく辛い…",
  ui_story_5080_50801201_17_dialog_content = "レイチェル、私の大切なレイチェル。\n泣かないで…泣いちゃダメ…",
  ui_story_5080_50801201_18_dialog_content = "私のせいだ。私のせいなのに、なぜ私に感謝するんだ…",
  ui_story_5080_50801201_19_dialog_content = "あなたは、彼女たちの最後の尊厳を守ったからよ。",
  ui_story_5080_50801201_20_dialog_content = "でも…生きて帰って来られるはずだった。\n両親とまた会えるはずだったんだ。",
  ui_story_5080_50801201_21_dialog_content = "レイチェル、私を見て。あなたに責任がもてる？\nただ無事に帰るためだけに、仲間たちを逃亡兵にできる？",
  ui_story_5080_50801201_22_dialog_content = "私は…私は…私には…分からない…",
  ui_story_5080_50801201_23_dialog_content = "レイチェル、いったいどうしたのですか？\n任務に失敗するのはこれで6度目です。",
  ui_story_5080_50801201_24_dialog_content = "十分に休んだはずでしょう？どうしてまた失敗を？",
  ui_story_5080_50801201_25_dialog_content = "申し訳ありません。すべて私の責任です。\n隊員たちを責めないでください。",
  ui_story_5080_50801201_26_dialog_content = "隊員たちから苦情が来ています。\n名前も顔も覚えないそうですね。いったいどうしたのですか？",
  ui_story_5080_50801201_27_dialog_content = "私は…申し訳ありません…本当に申し訳ありません…",
  ui_story_5080_50801201_28_dialog_content = "ひとまず任務に出ることは控えましょう。\n休暇を手配します。",
  ui_story_5080_50801201_29_dialog_content = "本当に申し訳ありません…軍団長…",
  ui_story_5080_50801201_30_dialog_content = "グレーウィングの名は「ルイ」といった。\n北方の生まれで、ずっと砂漠に行きたがっていた。",
  ui_story_5080_50801201_31_dialog_content = "北境に行って、ヒノキの木を削り、笛にして、\nホワイトグースに贈りたいと言っていた。",
  ui_story_5080_50801201_32_dialog_content = "ホワイトグースの名は「マリー」といった。\nずっと楽器を習いたがっていたが、そう言うだけで本当に習ったことはなかった。",
  ui_story_5080_50801201_33_dialog_content = "私の誕生日に曲を演奏してくれると言っていたが、\nもう何年も先延ばしになっていた。",
  ui_story_5080_50801201_34_dialog_content = "そうだ、それからブルーアウルとレッドペレグリンも、全員…",
  ui_story_5080_50801201_35_dialog_content = "全員今はこのネックレスになって、永遠に私のそばにいる。",
  ui_story_5080_50801201_36_dialog_content = "「あなたに責任がもてる？\nただ無事に帰るためだけに、仲間たちを逃亡兵にできる？」",
  ui_story_5080_50801201_37_dialog_content = "PlayerName！",
  ui_story_5080_50801201_38_dialog_content = "…！",
  ui_story_5080_50801201_39_dialog_content = "バイス、ここだよ！レイチェル、フェラール、ゼタ！\n皆大丈夫？",
  ui_story_5080_50801201_40_dialog_content = "私は大丈夫だ。",
  ui_story_5080_50801201_41_dialog_content = "よかったわ、PlayerNameも無事みたいね。",
  ui_story_5080_50801201_42_dialog_content = "火口が崩れたみたいだな。他の皆は？",
  ui_story_5080_50801201_43_dialog_content = "同じ所に投げられたんじゃないみたいだね。\nふっふ～ん、まさに典型的な魔王城入城前の展開だよ！",
  ui_story_5080_50801201_44_dialog_content = "あのR・Wの頭が…私たちを救うために、マグマに飛び込むとは…",
  ui_story_5080_50801201_45_dialog_content = "下へ行こう。サメヤマを探さなきゃ。",
  ui_story_5080_50801201_46_dialog_content = "ここは全部マグマね…仕方ないわ、回り道しましょ。",
  ui_story_5080_50801201_47_dialog_content = "任務優先だ。必要もなく、危険なエリアに入るべきではない。",
  ui_story_5080_50801201_48_dialog_content = "サメヤマが僕たちを助けてくれたんだ。僕はサメヤマたちを探す。\n付いてきて。僕なら感知できるはずだよ。",
  ui_story_5080_50801201_49_dialog_content = "空の末裔、今の台詞カッコよすぎるよ！\n勇者はあたしだからね、あたしも行く！",
  ui_story_5080_50801201_50_dialog_content = "隊長、私も皆を助けに行きたいです。",
  ui_story_5080_50801201_51_dialog_content = "…腕をけがしているな。さっき転んだ時か？",
  ui_story_5080_50801201_52_dialog_content = "え？あ、本当に…血が出てるわ。",
  ui_story_5080_50801201_53_dialog_content = "これで手当てし、止血するんだ。君はもう前列で護衛をするにはふさわしくない。\n探しに行く時は私の後ろを歩くんだ。",
  ui_story_5080_50801201_54_dialog_content = "探しに行く？",
  ui_story_5080_50801201_55_dialog_content = "下に降りる。「ターゲット」も下にいるかもしれない。",
  ui_story_5080_50801201_56_dialog_content = "了解です！",
  ui_story_5080_50801201_57_dialog_content = "暗鬼だらけだな…活火山の中で、なんで生きてられるんだ？",
  ui_story_5080_50801201_58_dialog_content = "暗鬼も生き物だから、こういう危険な場所は避けるはずなのに…",
  ui_story_5080_50801201_59_dialog_content = "士官学校で習ったのとまったく違うわ。",
  ui_story_5080_50801201_60_dialog_content = "…この暗鬼は、ずいぶんと前に啓光が発見している。",
  ui_story_5080_50801201_61_dialog_content = "何だって？だったら、なんで俺は聞いたことがないんだ？",
  ui_story_5080_50801201_62_dialog_content = "当時、委員会は私のおばの所属する隊を派遣し、\n今の私たちと同じ調査任務に当たらせた。",
  ui_story_5080_50801201_63_dialog_content = "その隊長が今の「R・W」を作った人物だ。",
  ui_story_5080_50801201_64_dialog_content = "お前も知っているだろう？\nお前のおばはかつて「フリーバード」に所属していた。",
  ui_story_5080_50801201_65_dialog_content = "彼女が最後に当たった任務は委員会が直接使命、派遣した重要な任務だった。\nしかし任務は失敗に終わり、隊長はその後啓光に背いた。",
  ui_story_5080_50801201_66_dialog_content = "多くの者は「フリーバードは生き残るために、身勝手にも任務をあきらめた」と言っているが、\nお前はどう思っているのだ？",
  ui_story_5080_50801201_67_dialog_content = "大元帥、私は大変恥ずかしく思っております。\nおばの失敗を私は…恥ずかしく思います。",
  ui_story_5080_50801201_68_dialog_content = "しかし、おば本人は忠誠心が深く、\nあの隊長の巻き添えになっただけなのです！",
  ui_story_5080_50801201_69_dialog_content = "どうか私にチャンスをお与えください。\n我が一族の栄誉を取り戻して見せます。",
  ui_story_5080_50801201_70_dialog_content = "だが、この「醜事」がなければ、\nお前のおばは英雄として命を落としていたかもしれないのだぞ。",
  ui_story_5080_50801201_71_dialog_content = "お前にとっては、その方がずっと辛いことではないのか？",
  ui_story_5080_50801201_72_dialog_content = "それは…私は…",
  ui_story_5080_50801201_73_dialog_content = "ハハハ、ただ聞いてみただけのことだ。",
  ui_story_5080_50801201_74_dialog_content = "これから、お前を呼んだ理由を話そう。\nお前にある任務を受けてもらいたい。",
  ui_story_5080_50801201_75_dialog_content = "おばの最後の任務――それが今回お前に受けてほしい任務だ。",
  ui_story_5080_50801201_76_dialog_content = "大元帥？",
  ui_story_5080_50801201_77_dialog_content = "当時委員会は、観測した暗鬼を必ずや生け捕りにして持ち帰れとフリーバードに命じた。",
  ui_story_5080_50801201_78_dialog_content = "生きた暗鬼を入手し、実験に供するためだ。",
  ui_story_5080_50801201_79_dialog_content = "そのような実験がいいか悪いか、私はまだ疑念を持っている。\nよって、生け捕りを強制はしない。",
  ui_story_5080_50801201_80_dialog_content = "私は…",
  ui_story_5080_50801201_81_dialog_content = "もちろん、生け捕りに出来れば、おばの無念を晴らすことはできるだろう。",
  ui_story_5080_50801201_82_dialog_content = "だが、レイチェル。どうするかはお前自身が決めろ。",
  ui_story_5080_50801201_83_dialog_content = "この任務のために特別な隊員を手配しておいた。\n「バイス」という名は聞いたことがあるだろう？",
  ui_story_5080_50801201_84_dialog_content = "噂では…空の末裔と親しい、まだ若い隊長だと聞いています。\nしかし、彼女は空の末裔と長い間一緒にいるのでは――",
  ui_story_5080_50801201_85_dialog_content = "その通りだ。バイスが行くならば、\nその仲間たる空の末裔が付いていかないということがあるか？",
  ui_story_5080_50801201_86_dialog_content = "実に不思議な者たちだ。\n今回の任務で、お前もきっと何らかの答えを見つけられることだろう。",
  ui_story_5080_50801201_87_dialog_content = "これもヒイロからの要請だ。\nお前はいい上官を持ったな、レイチェル。",
  ui_story_5080_50801201_88_dialog_content = "大元帥、ヒイロ長官、心から感謝いたします。\n私を信じ、この機会を与えてくださったことに感謝いたします。",
  ui_story_5080_50801201_89_dialog_content = "すぐに出発の準備をいたします！",
  ui_story_5080_50801201_90_dialog_content = "待て、レイチェル。",
  ui_story_5080_50801201_91_dialog_content = "どうかご安心ください。必ず任務を完遂します！",
  ui_story_5080_50801201_92_dialog_content = "一言聞いておきたいだけだ――",
  ui_story_5080_50801201_93_dialog_content = "今、お前の心の中に啓明の光はあるか？",
  ui_story_5080_50801201_94_dialog_content = "大元帥…何を心配なさっているのか、分かっています。",
  ui_story_5080_50801201_95_dialog_content = "私は確かに指揮を誤り、隊を失くしました。\nその後はずっと新しい隊員とうまく関係を築けませんでした…",
  ui_story_5080_50801201_96_dialog_content = "ですが、ご安心ください。もう二度と失敗はいたしません。",
  ui_story_5080_50801201_97_dialog_content = "そのことではない。だが、いいだろう。行くがいい。",
  ui_story_5080_50801201_98_dialog_content = "彼らに会えば、お前の考えも変わるだろう。",
  ui_story_5080_50801201_99_dialog_content = "噂になっているほどの2人だ。相応の力を持っているはず…きっと強いだろうな。",
  ui_story_5080_50801201_100_dialog_content = "これまで以上に注意しながら、これまでと同様…\nどの隊員とも関わりを持たず、誰も巻き添えにしないように…",
  ui_story_5080_50801201_101_dialog_content = "おばさん、いい知らせです。",
  ui_story_5080_50801201_102_dialog_content = "また任務に行くことになりました。",
  ui_story_5080_50801201_103_dialog_content = "本当に？それはよかったわ。でも、大丈夫？無理しちゃダメよ。",
  ui_story_5080_50801201_104_dialog_content = "私は大丈夫です。しかも今度の任務では、\n当時のことを調査できるチャンスがあるかもしれないんです。",
  ui_story_5080_50801201_105_dialog_content = "必ずおばさんの冤罪を晴らしてみせます。",
  ui_story_5080_50801201_106_dialog_content = "違うわ、レイチェル。",
  ui_story_5080_50801201_107_dialog_content = "当時のことを私は一度も後悔したことはないの。\n生き残れたんだもの。隊長には心から感謝してるわ。",
  ui_story_5080_50801201_108_dialog_content = "隊長がいなかったら、私はあなたに会えなかった。",
  ui_story_5080_50801201_109_dialog_content = "なぜ今でもあの者をかばうんですか…\nあいつは、啓光から逃げたんですよ？",
  ui_story_5080_50801201_110_dialog_content = "隊長は逃亡兵なんかじゃないわ。ましてや反逆者じゃない！",
  ui_story_5080_50801201_111_dialog_content = "きっと私たちには分からない事情があるのよ。\n私は隊長を信じてるわ！",
  ui_story_5080_50801201_112_dialog_content = "その隊長がおばさんたちを「反逆者」にしたんですよ！\nもう何年も経つのに戻ってこない…なのになぜ、まだ信じているんですか！？",
  ui_story_5080_50801201_113_dialog_content = "私の命も、友人たちの命も、隊長が1人で背負って、\nあの「溶岩地獄」から救い出してくれたの。",
  ui_story_5080_50801201_114_dialog_content = "隊長こそ本物の英雄だわ！",
  ui_story_5080_50801201_115_dialog_content = "私はただおばさんの濡れ衣を晴らしたいだけ…",
  ui_story_5080_50801201_116_dialog_content = "一族には何も罪もないのに…",
  ui_story_5080_50801201_117_dialog_content = "レイチェル？どこへ行くの？",
  ui_story_5080_50801201_118_dialog_content = "戻りなさい、レイチェル！あそこには絶対に行っちゃいけないわ！",
  ui_story_5080_50801201_119_dialog_content = "レイチェル――",
  ui_story_5080_50801201_120_dialog_content = "フリーバードは任務には失敗したが、多くの情報を得ていた。",
  ui_story_5080_50801201_121_dialog_content = "残された資料に、当時の「あの暗鬼」は地脈のエネルギーを吸収し、\n生命を維持する変異種だと書かれていた。",
  ui_story_5080_50801201_122_dialog_content = "そして、この火山については、その変異種の暗鬼が生息し、\n活火山にも関わらず、終始噴火の臨界点に達しなかったとある。",
  ui_story_5080_50801201_123_dialog_content = "暗鬼どもが火山のエネルギーを吸収していることが原因である可能性が高い。",
  ui_story_5080_50801201_124_dialog_content = "R・W砂漠の火山が不安定なのは、地脈のエネルギーが不安定だからだ。",
  ui_story_5080_50801201_125_dialog_content = "その原因も変異種の活動が地脈エネルギーのバランスを崩しているからだろうが、\n暗鬼のエネルギー吸収が同時に火山の噴火を抑えていたんだ。",
  ui_story_5080_50801201_126_dialog_content = "そうすると、あの暗鬼たちはずっと地下で「増殖」していた可能性が高いね。",
  ui_story_5080_50801201_127_dialog_content = "だから当時は1匹しか観測できなかったのが、\n今は群れになって現れてるんだ。",
  ui_story_5080_50801201_128_dialog_content = "しかも、恐ろしい特性も遺伝で受け継がれてる可能性が高いのね。",
  ui_story_5080_50801201_129_dialog_content = "ちょっと待て。おかしくないか？\nそれじゃあ俺たちは感謝しなきゃいけないのかい？",
  ui_story_5080_50801201_130_dialog_content = "「キミたちのおかげで、火山が噴火せずに済んだ」って。\nそんな腹立たしい話あるか。",
  ui_story_5080_50801201_131_dialog_content = "でも、あの暗鬼たちがいなかったら、地脈のエネルギーは安定してたはずで、\nこんな劣悪な環境じゃなかったはずだよ。",
  ui_story_5080_50801201_132_dialog_content = "車を走らせてる時だって、しょっちゅう地震に遭うことなんてなかったよ！",
  ui_story_5080_50801201_133_dialog_content = "もっと言えば、砂漠の荒廃も関係あるってことになるんじゃないかしら？",
  ui_story_5080_50801201_134_dialog_content = "いずれにしろ、火山の力を<color=#FFB400>吸収</color>できるなんて、信じられないよ。",
  ui_story_5080_50801201_135_dialog_content = "もし、当時の<color=#FFB400>その暗鬼</color>がまだ生きてるとしたら、\nいったいどのくらい生きてて、どのくらい強大な力を持ってるんだろう？",
  ui_story_5080_50801201_136_dialog_content = "これ以上活かしておくわけにはいかない…",
  ui_story_5080_50801201_137_dialog_content = "絶対にこれ以上活かしておくわけにはいかない…",
  ui_story_5080_50801201_138_dialog_content = "じゃあ、このまま前進しよう！もっと奥へ！サメヤマのいる所へ！",
  ui_story_5080_50801202_1_dialog_content = "困ったな…ここは狭すぎる。",
  ui_story_5080_50801202_2_dialog_content = "しかも横にはマグマが流れてる、気を付けろ！",
  ui_story_5080_50801202_3_dialog_content = "ヤングドラゴン2号、キャンディーガール、\n私の後ろへ回れ！",
  ui_story_5080_50801202_4_dialog_content = "ホークハンター1、2、3号、火力全開！",
  ui_story_5080_50801202_5_dialog_content = "隊長、無理はいけません。暗鬼たちの防御力が高すぎます！",
  ui_story_5080_50801202_6_dialog_content = "黙って攻撃に集中しろ！",
  ui_story_5080_50801202_7_dialog_content = "怖がることないよ！\nあたしのハニー爆弾があれば、こんなのすぐに終わるから！",
  ui_story_5080_50801202_8_dialog_content = "グォォ――！",
  ui_story_5080_50801202_9_dialog_content = "隊長！",
  ui_story_5080_50801202_10_dialog_content = "大したけがではない。後ろで大人しくしていろ。",
  ui_story_5080_50801202_11_dialog_content = "まだ攻撃が来るよ！",
  ui_story_5080_50801202_12_dialog_content = "ホークハンター1号、戻って防御だ！",
  ui_story_5080_50801202_13_dialog_content = "まずい、間に合わない…",
  ui_story_5080_50801202_14_dialog_content = "勇者の奇襲を食らえ！",
  ui_story_5080_50801202_15_dialog_content = "グォォ――！",
  ui_story_5080_50801202_16_dialog_content = "ゼタ！？",
  ui_story_5080_50801202_17_dialog_content = "キャンディーガール！！",
  ui_story_5080_50801202_18_dialog_content = "フェラール、強制感知でヤツを抑え込んだよ、今だ！",
  ui_story_5080_50801202_19_dialog_content = "消えろ――！",
  ui_story_5080_50801202_20_dialog_content = "マグマに当たったか？",
  ui_story_5080_50801202_21_dialog_content = "グワァ！！",
  ui_story_5080_50801202_22_dialog_content = "マグマに飲み込まれたわ…\n変異種の暗鬼はマグマに耐えられるんじゃなかったの…？",
  ui_story_5080_50801202_23_dialog_content = "キャンディーガール、無事か！？",
  ui_story_5080_50801202_24_dialog_content = "へっへ～ん、飛鷹ハンター、見たでしょ…？\nR・Wもなかなかやるんだから…",
  ui_story_5080_50801202_25_dialog_content = "なぜだ。私なんかのために…",
  ui_story_5080_50801202_26_dialog_content = "だって、あんたは勇者の「道を誤った、何年も前に生き別れた姉上」だもん…",
  ui_story_5080_50801202_27_dialog_content = "キャンディーガール？キャンディーガール！！",
  ui_story_5080_50801202_28_dialog_content = "（大変だ、救急バッグを持ってない…ゼタのこの傷、どうしたら…え？）",
  ui_story_5080_50801202_29_dialog_content = "また私が指揮を誤ったのか？また、私のせいで隊員が…",
  ui_story_5080_50801202_30_dialog_content = "守ろうとしたのに、なぜ…",
  ui_story_5080_50801202_31_dialog_content = "なぜ、またこんなミスを？\n私が自分のことばかり考えすぎていたのか？",
  ui_story_5080_50801202_32_dialog_content = "そんなに自分を責めちゃいけない。ゼタは助かる！\n急いで、ゼタを俺の背に！急いでここから離れるぞ！",
  ui_story_5080_50801202_33_dialog_content = "ゼタ、しっかりするんだ！\n俺が必ず連れて帰ってやる、頑張るんだぞ！",
  ui_story_5080_50801202_34_dialog_content = "「改心した魔人エンジニア」、勇者ゼタの旅はここで終わりみたい…\nこれから先、あたしのことはもう忘れて…",
  ui_story_5080_50801202_35_dialog_content = "何バカなことを言ってるんだ！",
  ui_story_5080_50801202_36_dialog_content = "しっかりするんだ！新しいバルブを注文してたろ？",
  ui_story_5080_50801202_37_dialog_content = "もう少しで最新のW型8気筒エンジンを作れるんだぞ。\n運転してみたくないのか！",
  ui_story_5080_50801202_38_dialog_content = "え！？",
  ui_story_5080_50801202_39_dialog_content = "頑張るんだ。そうすればこれからはクルマの改造は俺がやってやる。\nアズールの手助けはもうしない、どうだ？",
  ui_story_5080_50801202_40_dialog_content = "それから、アズールの車のデータを欲しがってたろ？\n俺が聞いてやるよ！",
  ui_story_5080_50801202_41_dialog_content = "一緒にロイ に仲間になってもらえるよう頼もうじゃないか…\nゼタ、しっかりするんだ！",
  ui_story_5080_50801202_42_dialog_content = "ロイのオッサンと一緒にアズールにイタズラしてやるから、\n楽しみにしてろって！",
  ui_story_5080_50801202_43_dialog_content = "そ、そうだぞ、キャンディーガール。私も手伝える。\n私は士官学校では、機械工学専攻だったんだ。",
  ui_story_5080_50801202_44_dialog_content = "でも、名前も呼んでくれない…",
  ui_story_5080_50801202_45_dialog_content = "車の改造なら、私にもできる。\n啓光の科学技術がどれだけのものか、君も知っているだろう？",
  ui_story_5080_50801202_46_dialog_content = "啓光式のお姫様のような車を運転してみたくないか？",
  ui_story_5080_50801202_47_dialog_content = "ホント！？やった～、今すぐ見たいな。設計図はある？",
  ui_story_5080_50801202_48_dialog_content = "ゼタ？…何ともないのか？",
  ui_story_5080_50801202_49_dialog_content = "うっ…へへ、しょってたハニーハンターが守ってくれたみたい。\nあたしってやっぱり生まれながらの主役なんだね～！",
  ui_story_5080_50801202_50_dialog_content = "勇者ゼタ、完全復活！",
  ui_story_5080_50801202_51_dialog_content = "な、なんだと…",
  ui_story_5080_50801202_52_dialog_content = "これぞ荒野の子、勇者ゼタの物語だよ！\nそう簡単にやられるワケな…うっ…",
  ui_story_5080_50801202_53_dialog_content = "だまそうとしたんじゃないよ。\nただフェラールにおんぶしてもらいたかっただけ。",
  ui_story_5080_50801202_54_dialog_content = "まったく驚かせないでくれよ。こんな時に…\nま、無事で何よりだ。",
  ui_story_5080_50801202_55_dialog_content = "（気づいた時はどう言い出すべきか迷ったけど、\nよかった、いつまでも悪ふざけが続かなくて…）",
  ui_story_5080_50801202_56_dialog_content = "でも、背中はホントにすごく痛いんだ。",
  ui_story_5080_50801202_57_dialog_content = "飛鷹ハンター、顔色が良くないね。あたしのこと怒ってるの…",
  ui_story_5080_50801202_58_dialog_content = "ええっ！？ホントにひどい顔…黒化の兆候だよ。\n悪い顔だね、いったいどんな恐ろしい物語の中から出てきたの！？",
  ui_story_5080_50801202_59_dialog_content = "そんなんじゃ…",
  ui_story_5080_50801202_60_dialog_content = "え！？",
  ui_story_5080_50801202_61_dialog_content = "ゼタ…無事で…本当によかった。",
  ui_story_5080_50801202_62_dialog_content = "軽々しく勇者の頭をなでないでよ！\nまぁ、あたしに甘えたいっていうなら、そうさせてあげてもいいけど…あれ？",
  ui_story_5080_50801202_63_dialog_content = "い、今、ゼタって呼んだ！？",
  ui_story_5080_50801202_64_dialog_content = "こんな冗談はよくない…",
  ui_story_5080_50801202_65_dialog_content = "隊長…",
  ui_story_5080_50801202_66_dialog_content = "もちろんだよ。あたしはヒロインなんだから、\n同じ手はしょっちゅう使わないよ。へへへ。",
  ui_story_5080_50801202_67_dialog_content = "よし、君が無事なら、このままマグマ地帯に留まる理由もない。\n引き続き前進だ！",
  ui_story_5080_50801202_68_dialog_content = "空の末裔1号、ヤングドラゴン2号、後れをとるな！",
  ui_story_5080_50801202_69_dialog_content = "なんだ…結局コードネームなのね…",
  ui_story_5080_50801202_70_dialog_content = "今はそんなこと構ってないで、行こう。",
  ui_story_5080_50801202_71_dialog_content = "任務はまだ終わっていない、急げ！",
  ui_story_5080_50801202_72_dialog_content = "（途端にいつもの冷たい表情に戻ったけど、\n今見ると何だかすごく違和感あるな…）",
  ui_story_5080_50801202_73_dialog_content = "行こう、バイス。今回のこの件、もうすぐ終わる気がするんだ。",
  ui_story_5080_50801202_74_dialog_content = "急げ！危険エリアから離れねば…うっ。",
  ui_story_5080_50801202_75_dialog_content = "どうしたの？",
  ui_story_5080_50801202_76_dialog_content = "何でもない、急ぐぞ！",
  ui_story_5080_50801202_77_dialog_content = "ホークハンター1号、偵察モードで隊を先導しろ。\n皆1号に続け！",
  ui_story_5080_50801202_78_dialog_content = "全員の命が私にかかっている…私が…倒れるわけにはいかない…",
  ui_story_5080_50801301_1_dialog_content = "グガァ――！！",
  ui_story_5080_50801301_2_dialog_content = "どんどん増えてるわ。",
  ui_story_5080_50801301_3_dialog_content = "悪意と怨念に満ちてる。",
  ui_story_5080_50801301_4_dialog_content = "イェリア、急いでここを離れて。私は大丈夫。",
  ui_story_5080_50801301_5_dialog_content = "何言ってるのよ。目が不自由なあなたを置いていけるワケないでしょ。",
  ui_story_5080_50801301_6_dialog_content = "あなたの能力は…ここで戦うのに向いてない。",
  ui_story_5080_50801301_7_dialog_content = "これでもクーリエ隊のエルダーなんだけど！",
  ui_story_5080_50801301_8_dialog_content = "地面が、下降してるわ…マグマに落ちる。",
  ui_story_5080_50801301_9_dialog_content = "ドーン！左よ、アタシの手をつかみなさい！",
  ui_story_5080_50801301_10_dialog_content = "急いで逃げて、イェリア。",
  ui_story_5080_50801301_11_dialog_content = "つかんだわ。放すんじゃないわよ、ドーン。",
  ui_story_5080_50801301_12_dialog_content = "暗鬼が、来るわ。",
  ui_story_5080_50801301_13_dialog_content = "今はそんなこと考えてる暇ないでしょ。",
  ui_story_5080_50801301_14_dialog_content = "どうして？イェリア、あなたは生きなきゃ。",
  ui_story_5080_50801301_15_dialog_content = "あなたがいなくなったら、みんな悲しむのよ。",
  ui_story_5080_50801301_16_dialog_content = "イブの泣き顔を想像してごらんなさい。",
  ui_story_5080_50801301_17_dialog_content = "あなたを抱えて号泣するに決まってるわ！",
  ui_story_5080_50801301_18_dialog_content = "…",
  ui_story_5080_50801301_19_dialog_content = "「凧の糸」って本当に丈夫なのねぇ…\nあなたをしっかり引き留められたみたい。",
  ui_story_5080_50801301_20_dialog_content = "人とつながったからには、そう簡単に切れると思うんじゃないわよ！",
  ui_story_5080_50801301_21_dialog_content = "イェリア…危ない！",
  ui_story_5080_50801301_22_dialog_content = "アタル。アタシ、ちゃんと頑張ったわよ…",
  ui_story_5080_50801301_23_dialog_content = "<color=#FFB400>速射感知！</color>",
  ui_story_5080_50801301_24_dialog_content = "間に合った、ゼタ！爆弾で奴らを止めろ！",
  ui_story_5080_50801301_25_dialog_content = "へっへ～ん、甘～い終極の爆弾をお見舞いしちゃうよ！",
  ui_story_5080_50801301_26_dialog_content = "イェリア！フェラール、ドーンをお願い…",
  ui_story_5080_50801301_27_dialog_content = "<color=#FFB400>アイスブロッサム！</color>",
  ui_story_5080_50801301_28_dialog_content = "「橋」ができたわ。急いで上がってくるのよ！",
  ui_story_5080_50801301_29_dialog_content = "カレン？イブ？",
  ui_story_5080_50801301_30_dialog_content = "ドーン、助けにきたよ！",
  ui_story_5080_50801301_31_dialog_content = "白夜城のお姫様、本当に助かったわ。",
  ui_story_5080_50801301_32_dialog_content = "とんでもない。あなたも懸命に絆を守ろうとしていたでしょう？",
  ui_story_5080_50801301_33_dialog_content = "ドーン、付いてきなさい。アタシの手を放すんじゃないわよ！",
  ui_story_5080_50801301_34_dialog_content = "イェリア…手…",
  ui_story_5080_50801301_35_dialog_content = "やっと合流できたね。カレン、皆無事だった？",
  ui_story_5080_50801301_36_dialog_content = "ええ、私たちは無事よ。ただマグマが危険すぎるわ。\nここでの長期間の戦闘は無理よ。",
  ui_story_5080_50801301_37_dialog_content = "猛禽ちゃん、お姫様。急いでゼタを連れてここを離れてちょうだい。",
  ui_story_5080_50801301_38_dialog_content = "空の末裔くん、悪いけど感知能力で、\nアタシたちをサメヤマの所へ連れてってちょうだい。",
  ui_story_5080_50801301_39_dialog_content = "君も行くのか？",
  ui_story_5080_50801301_40_dialog_content = "フフ、ここまで来て、サメヤマを放っておけると思う？",
  ui_story_5080_50801301_41_dialog_content = "ゼタはここから出ないよ！あたしも狂戦士を救いに行くんだから！",
  ui_story_5080_50801301_42_dialog_content = "私もこのまま立ち去るわけにはいかないわ。",
  ui_story_5080_50801301_43_dialog_content = "あのねぇ、なんだってこんな時に揃いも揃って頑固なのよ？",
  ui_story_5080_50801301_44_dialog_content = "では、奥へ進むぞ。",
  ui_story_5080_50801301_45_dialog_content = "隊長？",
  ui_story_5080_50801301_46_dialog_content = "任務は続行だ。より多くの情報を集めなければ…\nついでにあのR・Wの頭を助けても、特に支障はない。",
  ui_story_5080_50801301_47_dialog_content = "「R・Wのエンジニア」、工具を借りたい。\nヤングドラゴン2号、君の武器をこっちへ。",
  ui_story_5080_50801301_48_dialog_content = "え？俺のことかい？",
  ui_story_5080_50801301_49_dialog_content = "よし。君の武器を改良しておいた。少し慣れないだろうが、\nけがをしている今はこっちの方がいいだろう。",
  ui_story_5080_50801301_50_dialog_content = "ホークハンター1、2、3号、戻ってこい！",
  ui_story_5080_50801301_51_dialog_content = "…1号と3号は破損している。この先はホークハンター2号が先陣を切れ。",
  ui_story_5080_50801301_52_dialog_content = "いいか、任務を続行するぞ。",
  ui_story_5080_50801301_53_dialog_content = "持ちやすくて、軽くなった気が…",
  ui_story_5080_50801301_54_dialog_content = "隊長は私の癖まで覚えててくれたんだわ。\nこんなに優しいのに、どうして距離を置こうとするのかしら？",
  ui_story_5080_50801301_55_dialog_content = "隊長だもの。任務の完遂だけでなく、隊員の命も預かっているのよ。",
  ui_story_5080_50801301_56_dialog_content = "自分のために隊員が傷つくことがないよう、好感を持たれないようにしてるんだ。\nそれがレイチェルが最終的に行き着いたやり方なんだろうね。",
  ui_story_5080_50801301_57_dialog_content = "彼女がどれだけの重荷を背負っているか、私には分かるわ。",
  ui_story_5080_50801301_58_dialog_content = "サメヤマ――",
  ui_story_5080_50801301_59_dialog_content = "このバカ者がっ！聞こえてんのか――！？",
  ui_story_5080_50801301_60_dialog_content = "サメ坊！答えてくれ！",
  ui_story_5080_50801301_61_dialog_content = "ロイ、下を見てみろ！\nマグマの横の地面にあるのって、サメヤマの髪じゃねえか？",
  ui_story_5080_50801301_62_dialog_content = "どっちだろうと、確認するぞ！",
  ui_story_5080_50801301_63_dialog_content = "おい！下はマグマだぞ、そんなふうに飛び降りんじゃねえよ！おいっ！",
  ui_story_5080_50801301_64_dialog_content = "クソッ、かまうもんか！俺様はサメヤマを越えるんだ。\nこんなとこで引き下がってたまるかよ！",
  ui_story_5080_50801301_65_dialog_content = "そりゃ！",
  ui_story_5080_50801301_66_dialog_content = "うわああああああ――",
  ui_story_5080_50801301_67_dialog_content = "マグマしかねえじゃねえかああ！",
  ui_story_5080_50801301_68_dialog_content = "どけどけっ！",
  ui_story_5080_50801301_69_dialog_content = "<color=#e8d9bb>ドン！</color>",
  ui_story_5080_50801301_70_dialog_content = "オッさん、押しつぶされるところだったよォ…",
  ui_story_5080_50801301_71_dialog_content = "見ろ、サメヤマだ！マジでサメヤマだぜ！生きてんぞ！",
  ui_story_5080_50801301_72_dialog_content = "サメ坊、お前…",
  ui_story_5080_50801301_73_dialog_content = "こりゃ…全部暗鬼の死体じゃねぇか。サメヤマの野郎、1人でやったのか？",
  ui_story_5080_50801301_74_dialog_content = "上から落っこちて、重傷を負ったってのに、\nこんだけの暗鬼をやったのかよ！？",
  ui_story_5080_50801301_75_dialog_content = "おお、来たか…ちょうど、このデカブツを絞め殺してたとこだ…",
  ui_story_5080_50801301_76_dialog_content = "サメヤマ！？",
  ui_story_5080_50801301_77_dialog_content = "サメヤマ、しっかりしろ。ソイツはもう死んでる。\n手を放せ、行くぞ！",
  ui_story_5080_50801301_78_dialog_content = "おいっ！サメヤマ！？",
  ui_story_5080_50801301_79_dialog_content = "さっきのメシ、あんま食ってねぇから…また腹が空いてきたな…",
  ui_story_5080_50801301_80_dialog_content = "戻って、皆でメシ食いてぇな。にぎやかな方がうめぇし…",
  ui_story_5080_50801301_81_dialog_content = "ロイ 、俺は眠くって仕方ねぇや…\nここ2日あれやこれや気を揉みっぱなしだったせいかもな…",
  ui_story_5080_50801301_82_dialog_content = "さっさと戻って祝賀会にしようぜ。待たせちゃいけねぇ…",
  ui_story_5080_50801301_83_dialog_content = "おいっ…ど、どうしたんだよ？ロイ、見てくれ！\nくたばらせるワケにはいかねぇよ！",
  ui_story_5080_50801301_84_dialog_content = "…大丈夫だ。一気に力を使い過ぎて、疲れて寝ちまっただけさ。",
  ui_story_5080_50801301_85_dialog_content = "昨日の晩からゼタたちを探しに出て、戻っても大して食ってねェしなァ。\nずいぶん難儀なことさしちまった…",
  ui_story_5080_50801301_86_dialog_content = "ふん、こいつがそんなヤワじゃねぇことぐらい知ってたさ。",
  ui_story_5080_50801301_87_dialog_content = "こいつがくたばる時は俺様に倒された時だ！",
  ui_story_5080_50801301_88_dialog_content = "さ、俺様が背負ってやる。",
  ui_story_5080_50801301_89_dialog_content = "目が覚めた時、俺様に背負われたって知ったら、\nきっと恥ずかしがるぜ！",
  ui_story_5080_50801301_90_dialog_content = "じゃ、頼んだぞ。\nオッさんが道案内してやるから、さっさと上に戻るぞ…",
  ui_story_5080_50801301_91_dialog_content = "レンチはどこ行った？",
  ui_story_5080_50801301_92_dialog_content = "落っこった時にどっかに落としたのかもな…探さねぇと…",
  ui_story_5080_50801301_93_dialog_content = "<color=#e8d9bb>ドンッ！</color>",
  ui_story_5080_50801301_94_dialog_content = "今の、聞こえたか？",
  ui_story_5080_50801301_95_dialog_content = "ありゃマグマの音か？",
  ui_story_5080_50801301_96_dialog_content = "<color=#e8d9bb>ドンドン！</color>",
  ui_story_5080_50801301_97_dialog_content = "またか！",
  ui_story_5080_50801301_98_dialog_content = "…あれは、足音だ。ヘール、逃げるぞ！",
  ui_story_5080_50801301_99_dialog_content = "<color=#e8d9bb>ドンドンドン！</color>",
  ui_story_5080_50801301_100_dialog_content = "急げ！",
  ui_story_5080_50801302_1_dialog_content = "助けてくれえええええ――！！",
  ui_story_5080_50801302_2_dialog_content = "誰だ？",
  ui_story_5080_50801302_3_dialog_content = "そっちこそ誰だ？",
  ui_story_5080_50801302_4_dialog_content = "おっ！啓光の隊長だ！ロイ 、急げ、こっちだ！！",
  ui_story_5080_50801302_5_dialog_content = "何があったんだ？",
  ui_story_5080_50801302_6_dialog_content = "<size=45><color=#e8d9bb>ドンドンドンドン、ドンドン、ドドドドドドドドオオオ</color></size>",
  ui_story_5080_50801302_7_dialog_content = "<color=#e8d9bb>ガア――</color>",
  ui_story_5080_50801302_8_dialog_content = "暗鬼だと！？いや、違う…<color=#FFB400>ターゲット</color>だ！",
  ui_story_5080_50801302_9_dialog_content = "啓光のお嬢ちゃん、ありがとよ、助かった。",
  ui_story_5080_50801302_10_dialog_content = "制圧射撃なら私に任せろ。\n君たちは早く逃げるんだ、他の者は私の後ろへ！",
  ui_story_5080_50801302_11_dialog_content = "急ぐぞ、ロイ…",
  ui_story_5080_50801302_12_dialog_content = "危ない！",
  ui_story_5080_50801302_13_dialog_content = "グオォ――",
  ui_story_5080_50801302_14_dialog_content = "なんて狡猾なヤツなんだろうねェ。\n撃たれ続けてでも道は塞ぐってか。",
  ui_story_5080_50801302_15_dialog_content = "どういうことだ？あの暗鬼、道を塞いだぞ。",
  ui_story_5080_50801302_16_dialog_content = "アイツは…アイツがそうなの？アタルを殺したのは…",
  ui_story_5080_50801302_17_dialog_content = "イブがやる！",
  ui_story_5080_50801302_18_dialog_content = "<color=#FFB400>竜巻！</color>",
  ui_story_5080_50801302_19_dialog_content = "<color=#e8d9bb>天井が雷で砕け、例の暗鬼に当たった。\nしかし、その大きな力は火山の咆哮を呼び、再び地震が起こった。</color>",
  ui_story_5080_50801302_20_dialog_content = "この力…大変よ、火山が噴火するわ！",
  ui_story_5080_50801302_21_dialog_content = "「R・Wのお嬢さん」、攻撃を続けるんだ！",
  ui_story_5080_50801302_22_dialog_content = "でも、そんなことしたら火山が噴火しちゃうよ。",
  ui_story_5080_50801302_23_dialog_content = "山はとっくに覚醒している。\nそれに奴を逃がしたら、他の者に大きな危害が及ぶだろ！",
  ui_story_5080_50801302_24_dialog_content = "絶対に当たったのに、ぜんぜんダメージ受けてる感じがしないよ。\nいったいどこに弱点があるの？",
  ui_story_5080_50801302_25_dialog_content = "「ホークハンター」たちがすでに探ってくれた。\n奴の身体の表面は、マグマと同じ温度に達しているわけではない。",
  ui_story_5080_50801302_26_dialog_content = "それに、いかなる生物も食事を摂る時には無防備になるものだ。",
  ui_story_5080_50801302_27_dialog_content = "もし、身体の外側を壊せば、エネルギーを吸収しに行くかもしれない。\nその時こそ奴が弱点をさらす時だ！",
  ui_story_5080_50801302_28_dialog_content = "当時はあんだけ大きかったのが…地中でのうのうと10数年も暮らしてたっつーのに、\nなんで小さくなってんだ…？",
  ui_story_5080_50801302_29_dialog_content = "<color=#FFB400>破滅の製図！</color>",
  ui_story_5080_50801302_30_dialog_content = "<color=#FFB400>竜巻！</color>",
  ui_story_5080_50801302_31_dialog_content = "<color=#FFB400>速射感知！</color>",
  ui_story_5080_50801302_32_dialog_content = "<color=#FFB400>アイスブロッサム！</color>",
  ui_story_5080_50801302_33_dialog_content = "グォォ――！！！",
  ui_story_5080_50801302_34_dialog_content = "ダメージがあったわ、攻撃が効いてる！",
  ui_story_5080_50801302_35_dialog_content = "<color=#e8d9bb>ドン！！！</color>",
  ui_story_5080_50801302_36_dialog_content = "まずいぞ、壁が崩れた。マグマが流れ込んでくるぞ！",
  ui_story_5080_50801302_37_dialog_content = "気を付けろ、奴がエネルギーを吸収しにいくかもしれない！",
  ui_story_5080_50801302_38_dialog_content = "ヘール、サメヤマを連れて上へ走れ！イブ、お前も気を付けろよ！",
  ui_story_5080_50801302_39_dialog_content = "わああああっ――あたしのロボットに火が付いたあっ！",
  ui_story_5080_50801302_40_dialog_content = "ゼタ、私たちがいたら邪魔よ。先に退くわよ！",
  ui_story_5080_50801302_41_dialog_content = "でも、救世主はこんな時こそ引き下がっちゃいけないんだ！",
  ui_story_5080_50801302_42_dialog_content = "ゼタ、言うこと聞くんだ！\nオッさんに心配かけるのはお前だって嫌だろ？",
  ui_story_5080_50801302_43_dialog_content = "グガァ――",
  ui_story_5080_50801302_44_dialog_content = "暗鬼が巣からゾロゾロ出てきたぞ！",
  ui_story_5080_50801302_45_dialog_content = "ロイがそう言うなら…ドーン、援護してあげる！\n新しい仲間を集めにいくよ！",
  ui_story_5080_50801302_46_dialog_content = "お兄ちゃんには手を出させない！",
  ui_story_5080_50801302_47_dialog_content = "イブ、下がって。イェリア、あなたたちも…",
  ui_story_5080_50801302_48_dialog_content = "アタシが引き付けるわ。早くサメヤマを連れて逃げなさい！",
  ui_story_5080_50801302_49_dialog_content = "イェリア？",
  ui_story_5080_50801302_50_dialog_content = "アイツが本当にアタルを殺したヤツなら…逃しはしないわ！",
  ui_story_5080_50801302_51_dialog_content = "マグマがなだれ込んできているのに、吸収しに行こうとしない…なぜだ？",
  ui_story_5080_50801302_52_dialog_content = "それだけじゃない…マグマから逃げてるみたいだよ？",
  ui_story_5080_50801302_53_dialog_content = "ちょっと待って、バイス。そこは危険すぎるよ、もっと僕の方へ！",
  ui_story_5080_50801302_54_dialog_content = "カレン、君の力で足場を作って、ヤツの頭上まで行くんだ！",
  ui_story_5080_50801302_55_dialog_content = "私が援護するわ、急いで！",
  ui_story_5080_50801302_56_dialog_content = "<color=#FFB400>言霊たちよ！</color>",
  ui_story_5080_50801302_57_dialog_content = "グォォ――！！！",
  ui_story_5080_50801302_58_dialog_content = "動きが鈍くなった？僕も手伝う！",
  ui_story_5080_50801302_59_option_content = "強制感知！",
  ui_story_5080_50801302_60_dialog_content = "飛ぶ鳥の翼を折ろうなんてふざけたヤツね！代償は払ってもらうわ！",
  ui_story_5080_50801302_61_dialog_content = "お姫様、今よ、行ける？",
  ui_story_5080_50801302_62_dialog_content = "<color=#FFB400>アイスブロッサム！</color>",
  ui_story_5080_50801302_63_dialog_content = "マグマの表皮の温度が高すぎるわ。ダメージが足りない…",
  ui_story_5080_50801302_64_dialog_content = "効いてはいる。今のうちに攻撃をたたみかけなければ…",
  ui_story_5080_50801302_65_dialog_content = "ホークハンター1号、3号、すまない――",
  ui_story_5080_50801302_66_dialog_content = "<color=#FFB400>自爆攻撃！</color>",
  ui_story_5080_50801302_67_dialog_content = "グォォ――！！！",
  ui_story_5080_50801302_68_dialog_content = "（まずい…ヤツのマグマのエネルギーが強すぎて、\nどんな攻撃も相殺されちゃう…）",
  ui_story_5080_50801302_69_dialog_content = "皆気を付けて…ヤツが感知の拘束から抜ける！",
  ui_story_5080_50801302_70_dialog_content = "（頭が…痛い…）",
  ui_story_5080_50801302_71_dialog_content = "おい、洞窟が崩れるぞ！キミたちもさっさと上がってくるんだ！",
  ui_story_5080_50801302_72_dialog_content = "<color=#e8d9bb>ドン！！！</color>",
  ui_story_5080_50801302_73_dialog_content = "熱気が増しているわ。このままでは――",
  ui_story_5080_50801302_74_dialog_content = "お姫様は受け止めたわよ！早く逃げて！",
  ui_story_5080_50801302_75_dialog_content = "大変だ、カレンとイェリアが閉じ込められた！",
  ui_story_5080_50801302_76_dialog_content = "速度は落ちるけれど、私が道を作るわ。皆、気を付けるのよ！",
  ui_story_5080_50801302_77_dialog_content = "なぜだ？きちんと計測したはずだ…\n奴のエネルギーはなぜこうも大きい？",
  ui_story_5080_50801302_78_dialog_content = "私の判断が誤っていたのか？",
  ui_story_5080_50801302_79_dialog_content = "戦闘中も、力を補充し続けられるということか？",
  ui_story_5080_50801302_80_dialog_content = "マグマが押し寄せてきます！隊長、急いでください！",
  ui_story_5080_50801302_81_dialog_content = "君たちは行け！私には責任がある。撤退を援護しよう！",
  ui_story_5080_50801302_82_dialog_content = "来い！",
  ui_story_5080_50801302_83_dialog_content = "<color=#FFB400>速射感知！</color>",
  ui_story_5080_50801302_84_dialog_content = "こっちに来なさい！",
  ui_story_5080_50801302_85_dialog_content = "グォォ――！！！",
  ui_story_5080_50801302_86_dialog_content = "ヤングドラゴン2号！",
  ui_story_5080_50801302_87_dialog_content = "バイスを傷つけないで！！",
  ui_story_5080_50801302_88_option_content = "強制感知！",
  ui_story_5080_50801302_89_dialog_content = "ヤングドラゴン2号、無事か？しっかりするんだ！",
  ui_story_5080_50801302_90_dialog_content = "（効率をあんなに大事にする人が、バイスのために攻撃のチャンスをムダに…）",
  ui_story_5080_50801302_91_dialog_content = "でも…どうして、こんな時に嬉しくなるんだろう…すごく頭が痛いけど…",
  ui_story_5080_50801302_92_dialog_content = "そんなことに構っちゃいられないよ。イブ、キミたちは早く行け！",
  ui_story_5080_50801302_93_dialog_content = "来たよ！",
  ui_story_5080_50801302_94_dialog_content = "<color=#FFB400>アレンの拳骨！</color>",
  ui_story_5080_50801302_95_dialog_content = "お姫様、橋を支える役は任せたわよ！",
  ui_story_5080_50801302_96_dialog_content = "<color=#FFB400>竜巻！</color>",
  ui_story_5080_50801302_97_dialog_content = "やったよ！こんな遠い所から命中させた！",
  ui_story_5080_50801302_98_dialog_content = "暑いな…この高さじゃ、オッさんにはどうなったか見えやしないねェ。",
  ui_story_5080_50801302_99_dialog_content = "グォォ――！！！",
  ui_story_5080_50801302_100_dialog_content = "逃げるよ！",
  ui_story_5080_50801302_101_dialog_content = "そうはさせないわ！",
  ui_story_5080_50801302_102_dialog_content = "追っちゃダメだ、イェリア！足下がマグマに飲まれる！",
  ui_story_5080_50801302_103_dialog_content = "…みんな…大丈夫よ。アタシに任せて。",
  ui_story_5080_50801302_104_dialog_content = "言霊たちが壁のもろい所を見つけたの。こっちよ。",
  ui_story_5080_50801302_105_dialog_content = "はぁ…はぁ…「氷の橋」よ、伸びて…",
  ui_story_5080_50801302_106_dialog_content = "今はこれくらいの力しか残っていないわ。",
  ui_story_5080_50801302_107_dialog_content = "私がヤングドラゴン2号を背負っていこう…全員、ここを離れるぞ。",
  ui_story_5080_50801401_1_dialog_content = "<color=#FFB400>アイスブロッサム！</color>",
  ui_story_5080_50801401_2_dialog_content = "破れていない！？",
  ui_story_5080_50801401_3_dialog_content = "壁の温度が高すぎるんだ。強行突破は難しいぞ。",
  ui_story_5080_50801401_4_dialog_content = "私のせいだ…ホークハンター1号、2号を無駄に自爆させてしまった。",
  ui_story_5080_50801401_5_dialog_content = "ここは温度が高いからね。俺もそんなに爆発物を持ってきてないんだ…",
  ui_story_5080_50801401_6_dialog_content = "少し時間をくれないか。精確な爆破方法を計算する。",
  ui_story_5080_50801401_7_dialog_content = "おい、ロイ。見えるか？あいつら通路で立ち往生してるぞ。",
  ui_story_5080_50801401_8_dialog_content = "この角度からじゃ、攻撃を当てられないよ…",
  ui_story_5080_50801401_9_dialog_content = "やめるんだ、イブ。お前の力じゃ攻撃範囲がデカすぎる！",
  ui_story_5080_50801401_10_dialog_content = "この中で、そんなことできんのはサメヤマだけだ。\n俺様が起こしてやる！",
  ui_story_5080_50801401_11_dialog_content = "ロイ 、持ってる食糧をぜんぶ出せ！",
  ui_story_5080_50801401_12_dialog_content = "え？お兄ちゃんに何するの…？",
  ui_story_5080_50801401_13_dialog_content = "ハッハー、言うまでもねえよ。食いモンを全部口に突っ込むんだよ！",
  ui_story_5080_50801401_14_dialog_content = "ウググググオッ――",
  ui_story_5080_50801401_15_dialog_content = "やめろ、サメヤマを殺す気か？",
  ui_story_5080_50801401_16_dialog_content = "<size=45>やめて！！</size>",
  ui_story_5080_50801401_17_dialog_content = "バイス…バイス…脅かすな…",
  ui_story_5080_50801401_18_dialog_content = "ヤングドラゴン2号、目を覚ませ。",
  ui_story_5080_50801401_19_dialog_content = "ホークハンター2号、すぐに救急モードに切り換えるんだ。\n電気マッサージレベル2、準備！",
  ui_story_5080_50801401_20_dialog_content = "<color=#FFB400>開始！</color>",
  ui_story_5080_50801401_21_dialog_content = "う～ん…",
  ui_story_5080_50801401_22_dialog_content = "よかった、無事だったか…",
  ui_story_5080_50801401_23_dialog_content = "ヤングドラゴン2号！聞こえるか？心配はいらない。必ず連れて帰る…",
  ui_story_5080_50801401_24_dialog_content = "隊長…",
  ui_story_5080_50801401_25_dialog_content = "ヤングドラゴン2号？",
  ui_story_5080_50801401_26_dialog_content = "…レイチェル、もうやめてよ！",
  ui_story_5080_50801401_27_dialog_content = "誰かの心を「覚ましたい」なら、せめて名前を呼んであげて！",
  ui_story_5080_50801401_28_dialog_content = "バイスはヤングドラゴン2号なんかじゃない。\nちゃんとバイスっていう名前があるんだ！",
  ui_story_5080_50801401_29_dialog_content = "空の末裔1号…",
  ui_story_5080_50801401_30_dialog_content = "僕のことはどうだっていいよ。でもバイスは違う…",
  ui_story_5080_50801401_31_dialog_content = "バイスはずっと君に憧れて、尊敬してたんだ。\n君と隊を組めるって聞いて、本当に喜んでたんだよ。",
  ui_story_5080_50801401_32_dialog_content = "それなのに、こんな時でさえ名前を呼んであげないなんて！",
  ui_story_5080_50801401_33_dialog_content = "…",
  ui_story_5080_50801401_34_dialog_content = "そこにいるのはバイスなんだ！君のために、夜更かしして任務報告を書いてた…\n眠くて仕方ないのに、すっごく興奮した目をしながら…",
  ui_story_5080_50801401_35_dialog_content = "名前なんて呼んでくれたことないのに、\nそれでもバイスは先輩と話ができて、嬉しかったんだよ！",
  ui_story_5080_50801401_36_dialog_content = "バイスは本当に上官たちのことが好きで、褒めてもらいたいって思ってた。\n何も悪いことしてないのに、ただ名前を呼ぶだけなのに、君はいったい何を怖がってるの…？",
  ui_story_5080_50801401_37_dialog_content = "お願いだよ。せめて…せめて、こんな時くらい名前を呼んであげてよ…",
  ui_story_5080_50801401_38_dialog_content = "私は…二度と、他人に余計な情は持たないと決めた…",
  ui_story_5080_50801401_39_dialog_content = "猛禽ちゃん…",
  ui_story_5080_50801401_40_dialog_content = "今はもう任務とは関係ない…私はこれ以上…\n他人を巻き添えにするわけにはいかない…",
  ui_story_5080_50801401_41_dialog_content = "…すまない。彼女は十分よくやった。すべては私のせいだ…",
  ui_story_5080_50801401_42_dialog_content = "足手まといにはなりたくない…\n二度と私のせいで誰かが犠牲になってほしくない…",
  ui_story_5080_50801401_43_dialog_content = "また新しい絆ができれば…また仲間が私の指揮によって犠牲になる…\nそんなことは…もう耐えられない…",
  ui_story_5080_50801401_44_dialog_content = "そうじゃないよ。責任なんか追及するつもりはないんだ。",
  ui_story_5080_50801401_45_dialog_content = "君は本当は優しくて、皆のことを気に掛けてるのに、\nどうして隠してるの？",
  ui_story_5080_50801401_46_dialog_content = "君が真心を差し出してこそ、\n他の人も命を惜しまず、君を守ってくれるんだ。",
  ui_story_5080_50801401_47_dialog_content = "それがどうして、余計なの…",
  ui_story_5080_50801401_48_dialog_content = "空の末裔1号、君には分からないだろう…",
  ui_story_5080_50801401_49_dialog_content = "僕にはわからない！？誰かが僕のために犠牲になってるのに、\n何もできないって気持ち、どうして僕に分からないって言えるの？",
  ui_story_5080_50801401_50_dialog_content = "僕は一族全員を失った。それでも、やっと友だちができて、\nなのに僕のせいで…",
  ui_story_5080_50801401_51_dialog_content = "誰かを失う痛みも、自分を苛む孤独も、\n僕は分かってる…レイチェル。",
  ui_story_5080_50801401_52_dialog_content = "僕を助けてくれた人全員に心から感謝してるんだ。\nその人たちがいたから、僕とバイスは、仲間たちはこうして前に進み続けられる。",
  ui_story_5080_50801401_53_dialog_content = "それを余計なつながりだなんて、僕は思わない。",
  ui_story_5080_50801401_54_dialog_content = "皆と出会えて、本当によかった…\nもしできるなら、今でも皆の名前を呼んで、皆と話したい…",
  ui_story_5080_50801401_55_dialog_content = "PlayerName…",
  ui_story_5080_50801401_56_dialog_content = "それ以上、言わないでくれ…空の末裔1号…",
  ui_story_5080_50801401_57_dialog_content = "心に深い「愛」があるから、人は誰かのために犠牲になれるんだ。",
  ui_story_5080_50801401_58_dialog_content = "君を守った仲間の人たちも、バイスも、任務のためなんかじゃないんだよ！",
  ui_story_5080_50801401_59_dialog_content = "皆ただ君を守りたかっただけなんだ。だから…レイチェル。\n君がこうして生きてるだけで、皆心から喜んでるよ。",
  ui_story_5080_50801401_60_dialog_content = "フリーバードの隊長みたいに…その隊長さんもきっと隊員たちを本当に大切に思ってたんだよ。\nだから、名誉が傷つくことも惜しまず、皆を連れて帰ってきたんだ。",
  ui_story_5080_50801401_61_dialog_content = "ただ後ろにいる人たちを守りたいから、犠牲を払う…",
  ui_story_5080_50801401_62_dialog_content = "分かり合ったもの同士には、\n理由なんてそれだけでいいんじゃないかな…",
  ui_story_5080_50801401_63_dialog_content = "それ以上、言わないでくれ…私は…",
  ui_story_5080_50801401_64_dialog_content = "レイチェルも本当はよく分かってるんだよね…\nいつだって、僕たちのために自分の危険も顧みない…",
  ui_story_5080_50801401_65_dialog_content = "そうすれば、もっと効率がいいなんて理由じゃないでしょ？",
  ui_story_5080_50801401_66_dialog_content = "君はただ誰かが傷つくのが怖いだけなんだ…\nだから、全員を守ろうとする…",
  ui_story_5080_50801401_67_dialog_content = "だったら…どうして、まだ人とのつながりを拒もうとするの…？",
  ui_story_5080_50801401_68_dialog_content = "PlayerName…泣かないで…あなたももう、力を使い切っているのよ…",
  ui_story_5080_50801401_69_dialog_content = "…もうすぐ爆破できる。もう少し待っててくれ。",
  ui_story_5080_50801401_70_dialog_content = "猛禽ちゃん…いいえ、レイチェル。",
  ui_story_5080_50801401_71_dialog_content = "砂漠にはよく鳥が飛んでくるわ…でも、たとえはぐれたとしても、\nいつかは必ず群れに戻っていくのよ。",
  ui_story_5080_50801401_72_dialog_content = "アタシも…今までは理解できなかったけど、今ならわかるわ。\n猛禽になることを選んでも、結局仲間って、できちゃうものなのよ。",
  ui_story_5080_50801401_73_dialog_content = "わ、私には…仲間など必要ない…",
  ui_story_5080_50801401_74_dialog_content = "君は…なんて頑固なんだ…",
  ui_story_5080_50801401_75_dialog_content = "<color=#e8d9bb>ドン！！！</color>",
  ui_story_5080_50801401_76_dialog_content = "どうしたんだ？どこかで爆発したのか？",
  ui_story_5080_50801401_77_dialog_content = "グォォ――！！！",
  ui_story_5080_50801401_78_dialog_content = "危ない！",
  ui_story_5080_50801401_79_dialog_content = "レイチェル！手伝うわ！",
  ui_story_5080_50801401_80_dialog_content = "グォォ――！！！",
  ui_story_5080_50801401_81_dialog_content = "まずいわ。地面を攻撃してる！",
  ui_story_5080_50801401_82_dialog_content = "言霊たちよ、先にお姫様を上へ！",
  ui_story_5080_50801401_83_dialog_content = "<color=#e8d9bb>ドン！！！</color>",
  ui_story_5080_50801401_84_dialog_content = "壁が崩れたぞ！ついて来い！",
  ui_story_5080_50801401_85_dialog_content = "PlayerNameたちがまだ下にいるのよ！",
  ui_story_5080_50801401_86_dialog_content = "グォォ――！！！",
  ui_story_5080_50801401_87_dialog_content = "させるかっ…！私の仲間に手を出すな！",
  ui_story_5080_50801401_88_dialog_content = "PlayerName！カレンたちとここを離れるんだ！",
  ui_story_5080_50801401_89_dialog_content = "レイチェル…やっと…素直になってくれたんだね…",
  ui_story_5080_50801401_90_dialog_content = "まったく…身体は正直なものだな…\nPlayerName、攻撃から君を守った瞬間…",
  ui_story_5080_50801401_91_dialog_content = "意地を張る術を忘れてしまったようだ。",
  ui_story_5080_50801401_92_dialog_content = "だから…行くんだ。",
  ui_story_5080_50801401_93_dialog_content = "マグマが押し寄せてくるわよ！空の末裔くん、アタシの手をつかんで！",
  ui_story_5080_50801401_94_dialog_content = "マリー、ルイ、リナ、テイルス…仲間たちよ、私に力を与えてくれ！",
  ui_story_5080_50801401_95_dialog_content = "友を無事に逃がしてやってくれ！",
  ui_story_5080_50801401_96_dialog_content = "いや…僕は逃げないよ…",
  ui_story_5080_50801401_97_dialog_content = "PlayerName！？",
  ui_story_5080_50801401_98_dialog_content = "言ったでしょ？僕は、僕を助けてくれたすべての人に感謝してるって…\nそういうつながりを何よりも大切にしてるって…",
  ui_story_5080_50801401_99_dialog_content = "だから、僕は誰1人仲間を置いていったりしないよ、レイチェル。",
  ui_story_5080_50801401_100_dialog_content = "…上官の指示を無視するとは…困った兵士だな。",
  ui_story_5080_50801401_101_dialog_content = "だが、PlayerName。私は嬉しい…",
  ui_story_5080_50801401_102_dialog_content = "君たちとチームを組めたことを栄誉に思う。",
  ui_story_5080_50801401_103_dialog_content = "共に戦うぞ。",
  ui_story_5080_50801401_104_dialog_content = "カレン、最後の力を貸して！僕たちの足下を固めて！",
  ui_story_5080_50801401_105_dialog_content = "イェリア、君の言霊なら、崩れてくる壁を支えられるよね？",
  ui_story_5080_50801401_106_dialog_content = "フェラール、敵への直接攻撃は頼んだよ。",
  ui_story_5080_50801401_107_dialog_content = "一緒に戦おう！",
  ui_story_5080_50801402_1_dialog_content = "マグマの勢いが増している…<color=#FFB400>氷の道</color>が…く、崩れるわ！",
  ui_story_5080_50801402_2_dialog_content = "あとほんのちょっとよ！\nヤツの「ヨロイ」ももうすぐエネルギー切れよ！",
  ui_story_5080_50801402_3_dialog_content = "大変よ！PlayerName、レイチェル！",
  ui_story_5080_50801402_4_dialog_content = "（まずい…マグマで道が切断されて、皆バラバラに…）",
  ui_story_5080_50801402_5_dialog_content = "僕たちには構わないで…僕はもう力を使い過ぎた…\n皆、早くフェラールが造ってくれた穴から逃げて…",
  ui_story_5080_50801402_6_dialog_content = "バカを言うな！持ちこたえろよ、今行く！",
  ui_story_5080_50801402_7_dialog_content = "よりによってこんな場所に…\nもう一度氷の橋を造るのは…無理よ…",
  ui_story_5080_50801402_8_dialog_content = "<size=40>グォオオ！！</size>",
  ui_story_5080_50801402_9_dialog_content = "バケモノめ、どくものか！たとえ…拳銃だけになろうと…",
  ui_story_5080_50801402_10_dialog_content = "<color=#e8d9bb>バンッ――バンッ――バンッ――</color>",
  ui_story_5080_50801402_11_dialog_content = "<color=#e8d9bb>レイチェルの弾はすべて暗鬼に命中した。\nだが、敵の最後に残っていたエネルギーがそれを弾いてしまった。</color>",
  ui_story_5080_50801402_12_dialog_content = "<color=#e8d9bb>カチャッ――</color>",
  ui_story_5080_50801402_13_dialog_content = "弾が…切れた…",
  ui_story_5080_50801402_14_dialog_content = "武器がなくなっても、まだ拳がある。",
  ui_story_5080_50801402_15_dialog_content = "PlayerName、私の後ろに隠れているんだ！\n動くんじゃないぞ！",
  ui_story_5080_50801402_16_dialog_content = "レイチェル…早く逃げて…僕はもう動けないんだ…",
  ui_story_5080_50801402_17_dialog_content = "私は…絶対にあきらめない！",
  ui_story_5080_50801402_18_dialog_content = "<color=#e8d9bb>ドン！</color>",
  ui_story_5080_50801402_19_dialog_content = "またマグマの爆発か？この火山はおそらく、もうすぐ…\n待て。何だ、あれは？",
  ui_story_5080_50801402_20_dialog_content = "レンチ…サメヤマのレンチ！？どうしてこんな所に？",
  ui_story_5080_50801402_21_dialog_content = "ちょうどいい！",
  ui_story_5080_50801402_22_dialog_content = "待て、レイチェル！\nそのレンチは重いんだ、ムリをしちゃいけない！",
  ui_story_5080_50801402_23_dialog_content = "はぁ…はぁ…戻ったぜ…って、なにぃっ！？",
  ui_story_5080_50801402_24_dialog_content = "おい、待てよ。そりゃサメヤマのレンチだろ？\nバカやってんじゃねえ！",
  ui_story_5080_50801402_25_dialog_content = "わ、私は…隊員に無理させるのが…一番嫌いだ…",
  ui_story_5080_50801402_26_dialog_content = "自分が無理するのが大好きなんだ！",
  ui_story_5080_50801402_27_dialog_content = "グォォ！！！",
  ui_story_5080_50801402_28_dialog_content = "私の隊員に手を出すんじゃない！",
  ui_story_5080_50801402_29_dialog_content = "ガァアア――！！",
  ui_story_5080_50801402_30_dialog_content = "ウソだろ？サメヤマ以外に、あのレンチを振り回せる奴がいんのかよ…",
  ui_story_5080_50801402_31_dialog_content = "グワァ…グォオオ！！",
  ui_story_5080_50801402_32_dialog_content = "まだ生きてるの！？",
  ui_story_5080_50801402_33_dialog_content = "だったら…もう1度やるまで…",
  ui_story_5080_50801402_34_dialog_content = "（ダメだ…僕には分かる。レイチェルの身体はもう限界だ…\n無理しすぎだよ…これ以上無理したら…）",
  ui_story_5080_50801402_35_dialog_content = "絶対に…あきらめない…もう1度だ！",
  ui_story_5080_50801402_36_dialog_content = "グォォ！！！",
  ui_story_5080_50801402_37_dialog_content = "氷の橋…お願い、速く！",
  ui_story_5080_50801402_38_dialog_content = "お姫様も限界よ…このままじゃ…2人とも…",
  ui_story_5080_50801402_39_dialog_content = "ガアアガアア、うるせぇなあ！眠れねぇじゃねえか！",
  ui_story_5080_50801402_40_dialog_content = "サ…サメヤマ！？",
  ui_story_5080_50801402_41_dialog_content = "おっ、お嬢ちゃん。いい根性してんじゃねぇか。",
  ui_story_5080_50801402_42_dialog_content = "そのレンチを持ち上げられるってことは、「力」があるってことだな。",
  ui_story_5080_50801402_43_dialog_content = "他人を守るために、その「力」を使えるんなら、\nあんたにはちゃんと立派な「意志」があるんだ。",
  ui_story_5080_50801402_44_dialog_content = "さあ、行くぞ！その心ん中にある<color=#FFB400>大義</color>のために、\n<color=#FFB400>最大限の力</color>を振り絞れ！",
  ui_story_5080_50801402_45_dialog_content = "<size=45>はぁあああっ――！！</size>",
  ui_story_5080_50801402_46_dialog_content = "<color=#e8d9bb>ドン！</color>",
  ui_story_5080_50801402_47_dialog_content = "まったく違う世界に生きてる2人が、\n誰かを守るために、1つのレンチを振り上げる…",
  ui_story_5080_50801402_48_dialog_content = "2人の後ろ姿は…",
  ui_story_5080_50801402_49_dialog_content = "手を出すな！",
  ui_story_5080_50801402_50_dialog_content = "行かせないわ！",
  ui_story_5080_50801402_51_dialog_content = "最初はあなたのこと、理解できなかった彼女も、\n今はあのレンチを手にしてるわ――",
  ui_story_5080_50801402_52_dialog_content = "フッ…あなたたちの意志は、ちゃんと受け継がれてるわよ…アタル…",
  ui_story_5080_50801402_53_dialog_content = "…<color=#FFB400>「R・W」</color>にね。",
  ui_story_5080_50801402_54_dialog_content = "やっと片付いたか…マグマが押し寄せて来るぞ、さあ急げ！",
  ui_story_5080_50801402_55_dialog_content = "氷の橋もできたわ。行きましょう。",
  ui_story_5080_50801402_56_dialog_content = "おーい！こっちだ！",
  ui_story_5080_50801402_57_dialog_content = "ケーブルを上につないでおいた。登るんだ！",
  ui_story_5080_50801402_58_dialog_content = "PlayerName…行くぞ…うっ！",
  ui_story_5080_50801402_59_dialog_content = "おいおい、大丈夫かよ？手負いのくせにムリしやがって、\n完全に力を使い果たしたみてぇだな。",
  ui_story_5080_50801402_60_dialog_content = "仕方ねえなぁ。「R・Wの賊」の手を貸してやろうか？",
  ui_story_5080_50801402_61_dialog_content = "…",
  ui_story_5080_50801402_62_dialog_content = "あ、おいっ！",
  ui_story_5080_50801402_63_dialog_content = "<color=#e8d9bb>落下してきた石が2人の傍らをかすめて、マグマの中へ落ちていった。</color>",
  ui_story_5080_50801402_64_dialog_content = "…誰が…立てないと言った。\nお前こそ啓光の「働きアリ」の手を借りたいんじゃないか？",
  ui_story_5080_50801402_65_dialog_content = "はっはぁ！あんたも強がったりしねぇ方が可愛いと思うがな。",
  ui_story_5080_50801402_66_dialog_content = "この程度の石ころ、俺にとっちゃ何てことねぇよ…\nま、イブを心配させずに済んだがな。",
  ui_story_5080_50801402_67_dialog_content = "ありがとよ。",
  ui_story_5080_50801402_68_dialog_content = "あの、ごめん…誰か僕に手を貸してくれない？\n感知能力を使い過ぎて、本当にもう力が残ってないんだ…",
  ui_story_5080_50801402_69_dialog_content = "…",
  ui_story_5080_50801402_70_dialog_content = "だろうな…",
  ui_story_5080_50801402_71_dialog_content = "はっはっは――",
  ui_story_5080_50801402_72_dialog_content = "笑ってねぇで、さっさと行くぞ！",
  ui_story_5080_50801402_73_dialog_content = "<color=#e8d9bb>ゴオオオ――</color>",
  ui_story_5080_50801402_74_dialog_content = "ふうっ、ようやく出てこられた。\nああ、空気がおいしい！温度も心地いいなぁ！",
  ui_story_5080_50801402_75_dialog_content = "あ！早かったね！？",
  ui_story_5080_50801402_76_dialog_content = "お前らを先に行かせといて正解だったねェ。\nこりゃ方向音痴っつーか、なんつーか…",
  ui_story_5080_50801402_77_dialog_content = "ゼタが案内したのよ。",
  ui_story_5080_50801402_78_dialog_content = "な、なによ、あたしはラリーの伝説だよ。\n洞窟探険がほんのちょっと苦手だっていいんだもん！",
  ui_story_5080_50801402_79_dialog_content = "ははははは――",
  ui_story_5080_50801402_80_dialog_content = "ちょっと！狂戦士、笑わないで！",
  ui_story_5080_50801402_81_dialog_content = "こりゃ笑わずにはいられねェなァ。",
  ui_story_5080_50801402_82_dialog_content = "ええ！？ロ、ロイまで勇者ゼタをイジメるなんて…！",
  ui_story_5080_50801402_83_dialog_content = "おいっ、宴会に間に合わねえぞ！まったく…",
  ui_story_5080_50801402_84_dialog_content = "こんなとこでモタモタしてちゃ、先に始まっちまうぞ！",
  ui_story_5080_50801402_85_dialog_content = "それはダメだよ！\nあたしが全員まとめて、すぐに連れ帰ってあげる！",
  ui_story_5080_50801402_86_dialog_content = "乗って！",
  ui_story_5080_50801402_87_dialog_content = "ねぇ、ジョナ…",
  ui_story_5080_50801402_88_dialog_content = "アズールか？",
  ui_story_5080_50801402_89_dialog_content = "どうしたっていうの？\nせっかく戻ってきたのに、ずいぶん静かじゃない。",
  ui_story_5080_50801402_90_dialog_content = "あ、待ってください！そっちは――",
  ui_story_5080_50801402_91_dialog_content = "<color=#e8d9bb>ドーン！！ドドドドドオオーン！！</color>",
  ui_story_5080_50801402_92_dialog_content = "<color=#e8d9bb>仕掛けてあった罠の爆発で、すべての地雷が連鎖反応を起こした。\nあっという間にキャンプは見る影もなくなってしまった。</color>",
  ui_story_5080_50801402_93_dialog_content = "そっちは地雷が仕掛けてあるんです…",
  ui_story_5080_50801402_94_dialog_content = "どうしたの？何があった？",
  ui_story_5080_50801402_95_dialog_content = "なんでキャンプがこんなことになってるの？\nう～ん…今夜の宴会、できるかな？",
  ui_story_5080_50801402_96_dialog_content = "なんだこりゃああああ！！！",
  ui_story_5080_50801402_97_dialog_content = "バカ者どもがっ！！いったい何しやがった！？",
  ui_story_5080_50801402_98_dialog_content = "ちょっとした計算ミスだよ～！",
  ui_story_5080_50801402_99_dialog_content = "逃げるな！待ちやがれ！今日という今日は許さねえぞ！",
  ui_story_5080_50801402_100_dialog_content = "まあまあ、ひとまずガキんちょどものことはほっといて、\n使える食材がないか見ないとねェ。",
  ui_story_5080_50801402_101_dialog_content = "うわあ～ん…バーバラの…バーバラのステージが――",
  ui_story_5080_50801402_102_dialog_content = "おいおい、泣かないでくれ。直せるかどうか見てやるから…",
  ui_story_5080_50801402_103_dialog_content = "ふっふ～ん、あんたにもこんな日がくるとはね、「魔女」！",
  ui_story_5080_50801402_104_dialog_content = "あんたは知らないだろうけど、\nゼタ様はものスゴイ快挙を成し遂げたんだよ！",
  ui_story_5080_50801402_105_dialog_content = "…まぁ、いいわ…あなたに会えて、お姉さん嬉しいもの。",
  ui_story_5080_50801402_106_dialog_content = "いったい何なんだ…",
  ui_story_5080_50801402_107_dialog_content = "まったく…",
  ui_story_5080_50801402_108_dialog_content = "え？レイチェル！レイチェル！",
  ui_story_5080_50801402_109_dialog_content = "どうしたどうした？オッさんが見てやるよ…",
  ui_story_5080_50801402_110_dialog_content = "お、大丈夫だ。気が抜けて、気を失っちまっただけさ。",
  ui_story_5080_50801402_111_dialog_content = "彼女のドローン、なんでまた壊れちゃってるの？\nふんっ！オティ、見てなさい。あたしの卓越した修理技術を！",
  ui_story_5080_50801402_112_dialog_content = "この私がいるかぎり、あなたの出番はないわ――",
  ui_story_5080_50801402_113_dialog_content = "ここは…カナン城か？",
  ui_story_5080_50801402_114_dialog_content = "いつ戻ったんだ…",
  ui_story_5080_50801402_115_dialog_content = "隊長、隊長～！",
  ui_story_5080_50801402_116_dialog_content = "な…なぜ？",
  ui_story_5080_50801402_117_dialog_content = "ホワイトグース…いや、マリー、君たちも…",
  ui_story_5080_50801402_118_dialog_content = "本当に久しぶりですね…あら！？",
  ui_story_5080_50801402_119_dialog_content = "隊長、ど…どうして泣いてるんですか？",
  ui_story_5080_50801402_120_dialog_content = "すまない…本当にすまなかった…ずっと伝えたかったんだ…",
  ui_story_5080_50801402_121_dialog_content = "私はいい隊長ではなかった。君たちを…私は…",
  ui_story_5080_50801402_122_dialog_content = "ハハッ、隊長は泣く時、こんな感じだったんですね。",
  ui_story_5080_50801402_123_dialog_content = "初めて見ますが…最後にしたいものですね。",
  ui_story_5080_50801402_124_dialog_content = "生き残ったのが隊長で、本当によかったです。",
  ui_story_5080_50801402_125_dialog_content = "隊長を救えたんです。こんなに嬉しいことありません。",
  ui_story_5080_50801402_126_dialog_content = "それに、今の隊長は前よりもずっとカンペキじゃないですか。\n全員守り切ったんですから。",
  ui_story_5080_50801402_127_dialog_content = "隊長は、やはり最高の隊長です。",
  ui_story_5080_50801402_128_dialog_content = "みんな…",
  ui_story_5080_50801402_129_dialog_content = "隊長と出会えて、本当によかった。",
  ui_story_5080_50801402_130_dialog_content = "山ほどある部隊の中で、あたしたちは隊長の小隊に選ばれました。\nこんな幸せなことはありません。",
  ui_story_5080_50801402_131_dialog_content = "だから、隊長も幸せにならなきゃいけませんよ。",
  ui_story_5080_50801402_132_dialog_content = "どこへ行くんだ？戻ってきてくれ！まだ話したいことが…",
  ui_story_5080_50801402_133_dialog_content = "戻ってください、隊長。\n今隊長が大切にすべきなのは、もう我々じゃないでしょう。",
  ui_story_5080_50801402_134_dialog_content = "生きてください。たくさん笑って…それが一番なんです！",
  ui_story_5080_50801402_135_dialog_content = "待ってくれ、行かないでくれ！",
  ui_story_5080_50801402_136_dialog_content = "隊長――",
  ui_story_5080_50801402_137_dialog_content = "待ってくれ！！",
  ui_story_5080_50801402_138_dialog_content = "隊長――！",
  ui_story_5080_50801402_139_dialog_content = "君は…",
  ui_story_5080_50801402_140_dialog_content = "バイスか？",
  ui_story_5080_50801402_141_dialog_content = "隊長…？",
  ui_story_5080_50801402_142_dialog_content = "無事で…本当に良かった。",
  ui_story_5080_50801402_143_dialog_content = "あ…！い、今…隊長、私の名前を呼びましたか？",
  ui_story_5080_50801402_144_dialog_content = "うわああんっ…隊長！隊長！！",
  ui_story_5080_50801402_145_dialog_content = "<color=#e8d9bb>喜びのあまり泣き出したバイスはレイチェルをぎゅっと抱きしめた。\nレイチェルが固まっていようと構わずに。</color>",
  ui_story_5080_50801402_146_dialog_content = "（気持ちって…やっぱり、通じるんだね）",
  ui_story_5080_50801402_147_dialog_content = "大丈夫だ…もう大丈夫だ…",
  ui_story_5080_50801402_148_dialog_content = "ありがとう、バイス。",
  ui_story_5080_50801402_149_dialog_content = "君たち全員に感謝するよ。",
  ui_story_5080_50801500_1_dialog_content = "身を守るために、あの暗鬼を片付けちゃったけど、\n今地震はおさまってるし、火山も結局噴火しなかったわねぇ。",
  ui_story_5080_50801500_2_dialog_content = "つまり…別のもんが火山のエネルギーを抑え込んでるっつーことか？",
  ui_story_5080_50801500_3_dialog_content = "ただの推測だけどね。\nあそこを離れる前、言霊たちが見た限り――",
  ui_story_5080_50801500_4_dialog_content = "あなたたちがヤツを叩き潰した所が陥落してたんだけど、\nその下にまだ道があったの。",
  ui_story_5080_50801500_5_dialog_content = "火山の中心内部に、まだ回廊が存在するってこと？",
  ui_story_5080_50801500_6_dialog_content = "でも今は、マグマに覆われてしまったから、\n調査は不可能でしょうね。",
  ui_story_5080_50801500_7_dialog_content = "…ロイが言うには、あの暗鬼は当時の暗鬼じゃねぇってよ。",
  ui_story_5080_50801500_8_dialog_content = "そうでしょうね。地理的要因を除けば、あの暗鬼は大した相手じゃなかったわ。\nアイツが当時の相手だったなら、アタルがやられるはずないしね…",
  ui_story_5080_50801500_9_dialog_content = "どうやら、すべては真の深層部に隠されているようだな。",
  ui_story_5080_50801500_10_dialog_content = "俺たちの真の<color=#FFB400>仇</color>も…\nそこにいる可能性が高いってことだな。",
  ui_story_5080_50801500_11_dialog_content = "マグマが冷え固まって、皆の傷も治ったら、もう一度調査しに行こう。",
  ui_story_5080_50801500_12_dialog_content = "R・Wもこんな活火山地帯で暮らして、苦労が絶えないだろうな。",
  ui_story_5080_50801500_13_dialog_content = "さあな…俺たちゃ今を楽しむバカどもだからな。\nあれやこれや悩む頭は持っちゃいねぇよ。",
  ui_story_5080_50801500_14_dialog_content = "ステージが直ったわよ…今の今まで休みなく作業したのよ。\nまったく、疲れちゃったわ！！",
  ui_story_5080_50801500_15_dialog_content = "大丈夫だ、任せろ！\n私の情熱で、この夜空を熱く燃やしてやる――！",
  ui_story_5080_50801500_16_dialog_content = "はあ？ゼ、ゼタなの？な、なんなの、その化粧…",
  ui_story_5080_50801500_17_dialog_content = "ヒドイ顔だよ！",
  ui_story_5080_50801500_18_dialog_content = "え！？魔女がゼタをオトナのオンナにしてくれたって…",
  ui_story_5080_50801500_19_dialog_content = "まさか…あの魔女め！！",
  ui_story_5080_50801500_20_dialog_content = "ちょっと、どこ行くの～！？バックダンサーやってくれるっていったじゃない！\nあいつと勝負しなきゃいけないのにぃっ！",
  ui_story_5080_50801500_21_dialog_content = "ヘール、見たでしょう？みんなお腹を空かしてるんです。",
  ui_story_5080_50801500_22_dialog_content = "こういう時は野菜を一番早く洗った人が混乱を治めた大功臣なんです。\nきっとみんなから尊敬されるでしょうね～。",
  ui_story_5080_50801500_23_dialog_content = "おおお！言われなくてもわかってるぜ！\n俺様はそれくらい修練済みだからな、見てろよ！",
  ui_story_5080_50801500_24_dialog_content = "おやおや、こんなに簡単にだまされるとは…あ、ちょっと！\nいい野菜洗い器があるんですがね、要りませんか？",
  ui_story_5080_50801500_25_dialog_content = "キャンプがめちゃくちゃだね。イブも手伝うよ。",
  ui_story_5080_50801500_26_dialog_content = "私も。",
  ui_story_5080_50801500_27_dialog_content = "さあ、どいたどいた！俺様のジャマすんじゃねえ！",
  ui_story_5080_50801500_28_dialog_content = "やらせときなよ。また大騒ぎになったら大変じゃん。",
  ui_story_5080_50801500_29_dialog_content = "アズール、アズール！どこだ？",
  ui_story_5080_50801500_30_dialog_content = "急いで倉庫を空にするからな。今夜は飲み明かすぞ！",
  ui_story_5080_50801500_31_dialog_content = "まったく、騒がしいヤツらだな…",
  ui_story_5080_50801500_32_dialog_content = "俺はここの古株じゃねえし、\nただふらっと流れてきた、ただのガキだよ。",
  ui_story_5080_50801500_33_dialog_content = "アストラはこんなにデカいってのによ…\n行き場のねぇイブと俺を受け入れてくれたのはここだけだった。",
  ui_story_5080_50801500_34_dialog_content = "ようやく俺たちも、自分たちの力で自給自足して、\n家族として暮らせるようになったんだな。",
  ui_story_5080_50801500_35_dialog_content = "誰かの顔色見たり、拒まれるのを怖がる必要もなくなったんだ。",
  ui_story_5080_50801500_36_dialog_content = "そんなこと…あなたの口から聞けるなんて思わなかったわ。",
  ui_story_5080_50801500_37_dialog_content = "皆どこか尖った、おかしなヤツらばっかだからな。ぶつかり合って、\n砂みてぇにまとまるんだ。血だらけだろうと構わねぇよ。それでこそ一つってことだろ。",
  ui_story_5080_50801500_38_dialog_content = "こいつらと毎日一緒にいられて、俺は嬉しいんだ。",
  ui_story_5080_50801500_39_dialog_content = "どんなことがあろうと、一緒に痛快な暮らしを追い求める――\nそれが俺たちの自由ってヤツさ。",
  ui_story_5080_50801500_40_dialog_content = "だから、毎日こうやって騒いでいられるように、\n何度でもレンチを振り回して、俺たちのジャマするやつらを追っぱらってやるんだよ。",
  ui_story_5080_50801500_41_dialog_content = "君は立派なリーダーだ…サメヤマ。",
  ui_story_5080_50801500_42_dialog_content = "頼みがある。任務は完遂したが、これで終わりとは思っていない。",
  ui_story_5080_50801500_43_dialog_content = "ここに危険が潜んでいる限り、私も共に戦いたい。",
  ui_story_5080_50801500_44_dialog_content = "それに君たちの先代の頭はおばを救ってくれた。\n何としても、彼女の心残りを晴らしたい。",
  ui_story_5080_50801500_45_dialog_content = "なら聞くが――「犠牲」の意味は、分かったのか？",
  ui_story_5080_50801500_46_dialog_content = "それは…",
  ui_story_5080_50801500_47_dialog_content = "え？どうして僕たちのこと見てるの？",
  ui_story_5080_50801500_48_dialog_content = "私は決めたんだ。隊員たちを心配させないためにも、\n軽々しく「犠牲」という言葉は使わない。",
  ui_story_5080_50801500_49_dialog_content = "でも…また危険に陥るようなことがあれば、\n彼らを守るためなら、命も惜しまない。",
  ui_story_5080_50801500_50_dialog_content = "どんなことがあっても、側にいる者たちを守りたいんだ。",
  ui_story_5080_50801500_51_dialog_content = "そう…私たちは啓光の軍人として、任務のためでもなく、\n栄誉のためでもなく――",
  ui_story_5080_50801500_52_dialog_content = "ただ目の前のすべてを「守る」ために、そうするんだ。",
  ui_story_5080_50801500_53_dialog_content = "レイチェル…",
  ui_story_5080_50801500_54_dialog_content = "この身を烈火に化そうとも、道を照らし、他人の未来をつないでいく――\nそれが啓光の大義だ！",
  ui_story_5080_50801500_55_dialog_content = "私の一族は代々、誰かに助けられ、誰かのために犠牲になってきた。\n私も例外ではない！",
  ui_story_5080_50801500_56_dialog_content = "これからは、この意志を守るために戦う。\n途切れることのない啓光の防衛線となるためにな！",
  ui_story_5080_50801500_57_dialog_content = "言ってることは大して変わっちゃいねぇが、ま、いい目になったな。",
  ui_story_5080_50801500_58_dialog_content = "ってことは、もう心は決まったってことか？",
  ui_story_5080_50801500_59_dialog_content = "啓光の信条は「一は万人のためにあり、万人もまた一のためにある」だ。",
  ui_story_5080_50801500_60_dialog_content = "それでも私たちは自身の意志に基づき、何のために戦い、\n何のために命をかけるのか、決められるんだ。",
  ui_story_5080_50801500_61_dialog_content = "この意志こそ永遠の真実なんだ！…あ！",
  ui_story_5080_50801500_62_dialog_content = "今、お前の心の中に啓明の光はあるか？",
  ui_story_5080_50801500_63_dialog_content = "どうしたんですか？隊長？具合でも悪いんですか？",
  ui_story_5080_50801500_64_dialog_content = "…いや、何でもない。",
  ui_story_5080_50801500_65_dialog_content = "ただ…あの問いの答えが今ようやく、分かっただけだ。",
  ui_story_5080_50801500_66_dialog_content = "あの問い、ですか…？",
  ui_story_5080_50801500_67_dialog_content = "ふん…どうやら、やっと自分の目標が分かったみてぇだな。",
  ui_story_5080_50801500_68_dialog_content = "いいぜ。調査に入れてやるよ。",
  ui_story_5080_50801500_69_dialog_content = "だが、今は手負いなんだ。急ぐことはねぇ。",
  ui_story_5080_50801500_70_dialog_content = "今夜はここでメシ食って、ゆっくり休んでいくといい。\n調査だなんだってのは、それからだ。",
  ui_story_5080_50801500_71_dialog_content = "ああ…だが…",
  ui_story_5080_50801500_72_dialog_content = "ああ？",
  ui_story_5080_50801500_73_dialog_content = "協力はしても、もしR・Wが悪事を働けば、\n私は迷わず徹底的に追及する！",
  ui_story_5080_50801500_74_dialog_content = "そのレンチに受け継がれた意志を汚すなら、\nそのレンチは私がいただこう。",
  ui_story_5080_50801500_75_dialog_content = "なっ…",
  ui_story_5080_50801500_76_dialog_content = "ほしいなら、自分で取りにくりゃいいだろ。",
  ui_story_5080_50801500_77_dialog_content = "まったくかなわねぇぜ。\n啓光のヤツは、マジでおかしんじゃねぇか。",
  ui_story_5080_50801500_78_dialog_content = "あははは――",
  ui_story_5080_50801500_79_dialog_content = "なに笑ってんだよ？",
  ui_story_5080_50801500_80_dialog_content = "サメヤマが困ってるところなんて、初めて見たから…\nははっ、あははは…",
  ui_story_5080_50801500_81_dialog_content = "クソッ、お前なぁ――",
  ui_story_5080_50801500_82_dialog_content = "ボス！これを見てくれ！",
  ui_story_5080_50801500_83_dialog_content = "キャンプを片付けてる時に見つけたんだ。\n先代の残した日記らしい。",
  ui_story_5080_50801500_84_dialog_content = "爆発で壊れた箱の中で見つけたんだ…\nどうやら、隠してたみたいだね。",
  ui_story_5080_50801500_85_dialog_content = "…そうか、分かった。だが、今はまず保管しておけ。",
  ui_story_5080_50801500_86_dialog_content = "これから宴会だからな。それ以外のことは明日でいい。\nさあさあ、行くぞ！",
  ui_story_5080_50801500_87_dialog_content = "分かったよ。分かったから、押さないでよ…イタッ！",
  ui_story_5080_50801500_88_dialog_content = "今度は俺が笑う番だな！はっはっは――",
  ui_story_5080_50801500_89_dialog_content = "猛禽ちゃん、ちょっといいかしら？",
  ui_story_5080_50801500_90_dialog_content = "何だ？",
  ui_story_5080_50801500_91_dialog_content = "アタルがアタシに話してくれた物語の最後を話しておきたいの。",
  ui_story_5080_50801500_92_dialog_content = "当時、アタルは隊員を救い、任務を放棄した後、啓光を離れた。\n目標を失った彼女はしばらくの間、何の目的もなく各地をさまよっていたの。",
  ui_story_5080_50801500_93_dialog_content = "そして、知らず知らずのうちに、\n任務に失敗し、いまだ宿敵のはびこるこの砂漠へやってきたのよ。",
  ui_story_5080_50801500_94_dialog_content = "アタルが言ってたわ、自分はこの砂漠で生まれたんだって。\nここは無法地帯だけど、自由だってことも知ってた。ただ暮らしたことがないだけ。",
  ui_story_5080_50801500_95_dialog_content = "だから、見てみたかったのよ。少なくとも、自分が犠牲になった隊員たちのために、\n安息の地を見つけてあげたかったのね。",
  ui_story_5080_50801500_96_dialog_content = "…",
  ui_story_5080_50801500_97_dialog_content = "でも、そうやって放浪してる途中、賊に遭って、さらになんの運命のイタズラか、\n彼らを率いて暗鬼に立ち向かい、伝説のレンチを手にすることになった。",
  ui_story_5080_50801500_98_dialog_content = "その人たちのために、アタルはレンチをかかげ、\n砂漠の賊たちをまとめあげ、砂漠の混乱を終息させたの。",
  ui_story_5080_50801500_99_dialog_content = "その後、みんなとオアシスに定住するうち、\nレンチに関する伝説も知った。",
  ui_story_5080_50801500_100_dialog_content = "だから、彼女はオアシスで採掘したレディーゼルオイルでレンチを染め、\n正式に「R・W」を立ち上げたのよ。",
  ui_story_5080_50801500_101_dialog_content = "アタルは幸せだったと思うわ。真の自由を手に入れただけじゃなく、\n最後の最後まで、すべてを守って死ねたんだから。",
  ui_story_5080_50801500_102_dialog_content = "なぜ…私にそれを？",
  ui_story_5080_50801500_103_dialog_content = "戻ったら、おばさんに話してあげて。",
  ui_story_5080_50801500_104_dialog_content = "あなたの隊長は目的もなく啓光に背いたんじゃない。\n最初から最後まで、誰かの自由のために武器を振るい続けたんだってね。",
  ui_story_5080_50801500_105_dialog_content = "おばさんの気持ちが少しでも楽になればいいんだけど。",
  ui_story_5080_50801500_106_dialog_content = "ありがとう…それ以外に、何を言ったらいいのか思いつかない。",
  ui_story_5080_50801500_107_dialog_content = "猛禽ちゃん、歌いましょうよ。歌が聞こえるでしょ？",
  ui_story_5080_50801500_108_dialog_content = "歌…？",
  ui_story_5080_50801500_109_dialog_content = "燃え盛れ～！愛する楽園、愛する我が家～♪",
  ui_story_5080_50801500_110_dialog_content = "さあ、さあ！明日もまた、傷だらけの世界を見るんだとしても――",
  ui_story_5080_50801500_111_dialog_content = "声をあげて、歌うのよ…それが…生きてるってコトなんだから。",
  ui_story_5080_50801500_112_dialog_content = "レイチェル隊長！こっちです、宴会が始まりますよ！",
  ui_story_5080_50801500_113_dialog_content = "フフ…今行くわぁ～！",
  ui_story_5080_50801500_114_dialog_content = "…私もそろそろ…",
  ui_story_5080_50801500_115_dialog_content = "どこ行くんだ？ほれ。",
  ui_story_5080_50801500_116_dialog_content = "これって…",
  ui_story_5080_50801500_117_dialog_content = "サボテンのサソリの肝焼きだ、うまいぞ。食ったことねぇだろ？",
  ui_story_5080_50801500_118_dialog_content = "…アタシの知らない所で、あなたたちも色々探索してたのね。",
  ui_story_5080_50801500_119_dialog_content = "ふん、あったりめぇよ。",
  ui_story_5080_50801500_120_dialog_content = "あのよ、イェリア…お前もたまには帰ってこいよ。\n一緒にメシ食おうぜ。",
  ui_story_5080_50801500_121_dialog_content = "…今夜の宴会も、出席は義務ってコトかしら？",
  ui_story_5080_50801500_122_dialog_content = "あたりめぇだ、行こうぜ！",
  ui_story_5080_50801500_123_dialog_content = "レイチェル、こっちこっち！席を取っておいたよ。",
  ui_story_5080_50801500_124_dialog_content = "お肉が焼けたら、すぐに食べてね。\nここの皆は本当に遠慮も何もないから。",
  ui_story_5080_50801500_125_dialog_content = "ありがとう…皆、ありがとう。",
  ui_story_5080_50801500_126_dialog_content = "え？こんなことくらいでお礼言うことないよ。",
  ui_story_5080_50801500_127_dialog_content = "いや…君たちは皆、ずっと広い心で私を受け止めてくれていた。ありがとう。",
  ui_story_5080_50801500_128_dialog_content = "握手しよう。啓光の礼儀だ。",
  ui_story_5080_50801500_129_dialog_content = "…うん！",
  ui_story_5080_50801500_130_dialog_content = "実に不思議だ…君は数少ない空の末裔のはずなのに、\nなぜこんなに親しみが湧くのだろうな。",
  ui_story_5080_50801500_131_dialog_content = "何の偏見も違和感もなく接してくれる。\n啓光の者に慣れているんだな。",
  ui_story_5080_50801500_132_dialog_content = "（何から話せばいいのかな？僕たちの旅のこと…\nグラムやレビィ、レインハトさんにバートン、それから他の皆のこと…）",
  ui_story_5080_50801500_133_dialog_content = "PlayerName、さっき言った通り、一緒に！",
  ui_story_5080_50801500_134_dialog_content = "うん！",
  ui_story_5080_50801500_135_dialog_content = "啓明の光のために！敬礼！",
  ui_story_5080_50801500_136_dialog_content = "僕を助けてくれて、バイスを助けてくれて、ありがとう！",
  ui_story_5080_50801500_137_dialog_content = "様になっているではないか…フッ、君たちは共に多くのことを経験してきたんだな。\nだからこうして伝説のチームになったわけだ。",
  ui_story_5080_50801500_138_dialog_content = "今分かった。なぜ大元帥が君たちを特別だとおっしゃったのか。",
  ui_story_5080_50801500_139_dialog_content = "だが今は、2人とも私の仲間だ…",
  ui_story_5080_50801500_140_dialog_content = "今夜は共に楽しもう！",
  ui_story_5080_50801500_141_dialog_content = "<color=#e8d9bb>R・Wの荒々しくも、この上なくさわやかで、自由気ままな歌声が響き渡る。\nその情熱が暑い砂漠をさらに熱気で満たし、空には朝まで歌が響いていた。</color>",
  ui_story_5080_50801500_142_dialog_content = "マリー…ルイ…テイルス…リナ、聞こえているか？",
  ui_story_5080_50801500_143_dialog_content = "この砂漠はありとあらゆる魂を受け入れてくれるそうだ。\nだから、きっと…",
  ui_story_5080_50801500_144_dialog_content = "君たちのことも、受け入れてくれる。",
  ui_story_5080_50801500_145_dialog_content = "飛べ…自由なこの夜空を。",
  ui_story_5080_50801500_146_dialog_content = "魂が安息を得る、その時まで。"
}
return config
